(window.GAMES = window.GAMES || {})[2002] = [{"t":"007: Agent Under Fire","p":["GameCube","Xbox"],"r":"March 12"},{"t":"007: Nightfire","p":["PlayStation 2","GameCube","Xbox","Windows"],"r":"November 19"},{"t":"2002 FIFA World Cup","p":["PlayStation 2","GameCube"],"r":"April 22","l":"https://en.wikipedia.org/wiki/2002_FIFA_World_Cup_(video_game)"},{"t":"Ace Lightning","p":["Windows"],"g":"Shooter, Platform, Adventure","l":"https://en.wikipedia.org/wiki/Ace_Lightning","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2six.jpg","s":"This third-person action-adventure game lets you guide the foremost of the Lightning Knights, Ace Lightning, on his mission to defeat the evil Lord Fear and send him and his gang back to prison in the sixth dimension. The only way to capture Lord Fear is to collect all the pieces of the magical Amulet of Zoar, which he has hidden throughout the Carnival of Doom--a scary place full of exaggeratedly imposing tents, rides and sideshows, with distorted geometry and disturbing lighting effects. You must guide Ace Lightning around the eerie halls of the Carnival, and into its four zones--the Ghost Town, Fun Park, Circus and House of Horror--on his great quest to collect the pieces of the Amulet."},{"t":"Activision Anthology","p":["PlayStation 2"],"r":"November 19","l":"https://en.wikipedia.org/wiki/Activision_Anthology"},{"t":"AdventureQuest","p":["Windows"],"d":"Artix Entertainment","u":"Artix Entertainment","g":"Role-playing","r":"October 2002","l":"https://en.wikipedia.org/wiki/AdventureQuest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1s7k.jpg","s":"AdventureQuest is a fully animated RPG that you can play when you are on your lunchbreak, when the big game servers go down, or even for hours every day! You fight against hordes of monsters and enemies so that you can grow stronger and obtain ancient weapons of unimaginable power. Explore an entire world, filled with over 700 monsters, hundreds of items, magical powers to gain, and many classes to master! Become a Fighter, Wizard, Ninja, Vampire Slayer, Rogue, Knight, Mage, Paladin, Dragonslayer, and more."},{"t":"Aero Elite: Combat Academy","p":["PlayStation 2"],"d":"Sega AM2","u":"Sega","g":"Combat flight simulator","r":"July 11, 2002","l":"https://en.wikipedia.org/wiki/Aero_Elite:_Combat_Academy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1osn.jpg","s":"Aero Elite: Combat Academy is the fourth game in the AeroWing series and is considered a true flight sim game as the planes react as their real world counterparts. There are 60 authentic aircraft to pilot including the Harrier, A-10 Warthog, the Mirage 2000 and the infamous Mig 29 along with helicopters as well. There are 12 different missions areas that are used and features the new \"Scramble Mode\" where the player is instructed to intercept a random intruder and identify and land or attack if instructed. There are multiple missions to participate in including interceptions of enemy squadrons and even mastering aerial stunt maneuvers."},{"t":"Agassi Tennis Generation","p":["Windows"],"d":"Aqua Pacific","u":"DreamCatcher Interactive","g":"Sports","l":"https://en.wikipedia.org/wiki/Agassi_Tennis_Generation","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6pa5.jpg","s":"\"Agassi Tennis Generation\" is a tennis sports game featuring former tennis player Andre Agassi."},{"t":"Age of Mythology","p":["Windows"],"u":"Microsoft Game Studios","r":"October 30, 2002","l":"https://en.wikipedia.org/wiki/Age_of_Mythology"},{"t":"Age of Wonders II: The Wizard's Throne","p":["Windows"],"d":"Triumph Studios","u":"Gathering of Developers, CAPCOM","g":"Turn-based strategy","r":"June 12, 2002","l":"https://en.wikipedia.org/wiki/Age_of_Wonders_II:_The_Wizard's_Throne","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qlf.jpg","s":"Age of Wonders II is the wildly anticipated sequel to the award-winning strategy phenomenon. Delivering an invigorating mix of Empire Building, Role-playing, and Warfare, Age of Wonders II brings turn-based strategy to new heights.\n\nAwakened to join an immortal group of Wizards in the Circle of Evermore, you must restore balance to a world on the brink of collapse."},{"t":"Aggressive Inline","p":["GameCube","PlayStation 2"],"u":"Acclaim Entertainment","r":"July 31, 2002","l":"https://en.wikipedia.org/wiki/Aggressive_Inline_(video_game)"},{"t":"AirBlade","p":["PlayStation 2"],"r":"January 28","l":"https://en.wikipedia.org/wiki/AirBlade"},{"t":"Akane Maniax","p":[],"l":"https://en.wikipedia.org/wiki/Akane_Maniax"},{"t":"Akira Psycho Ball","p":["PlayStation 2"],"d":"KAZe","u":"Bandai","g":"Pinball","r":"February 21, 2002","l":"https://en.wikipedia.org/wiki/Akira_Psycho_Ball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ia9.jpg","s":"Akira Psycho Ball is a digital pinball game based on the popular Akira series created by Katsuhiro Otomo. It features the original storyline and the animated film adaptation's theme song."},{"t":"Alien Hominid","p":["Browser"],"d":"The Behemoth","u":"The Behemoth","g":"Run and gun","r":"August 7, 2002","l":"https://en.wikipedia.org/wiki/Alien_Hominid","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8qjt.jpg"},{"t":"All-Star Baseball 2003","p":["PlayStation 2"],"r":"February 26","l":"https://en.wikipedia.org/wiki/All-Star_Baseball#Series"},{"t":"Alpine Racer 3","p":["PlayStation 2"],"d":"Namco","u":"Namco, Sony Computer Entertainment","g":"Racing, Sports","r":"March 28, 2002","l":"https://en.wikipedia.org/wiki/Alpine_Racer_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2yo2.jpg","s":"Alpine Racer 3 is a Skiing game by Namco."},{"t":"Altered Beast: Guardian of the Realms","p":["Game Boy Advance"],"d":"3d6 Games","u":"THQ, Sega","g":"Beat 'em up","r":"November 26, 2002","l":"https://en.wikipedia.org/wiki/Altered_Beast:_Guardian_of_the_Realms","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5v1i.jpg","s":"Zeus, creator and ruler of the Guardians of the Gates, raises you from your grave! You must go fourth and defeat a new, unknown evil that has destroyed the Guardians and ravaged the universe. To do so, you must collect the keys and Essence of each land, transforming you into beasts with unnatural powers and special abilities. Conquer this evil and you will become the sole Guardian, the protector of the universe."},{"t":"American Conquest","p":["Windows"],"d":"GSC Game World","u":"CDV Software Entertainment","g":"Real-time strategy","r":"November 15, 2002","l":"https://en.wikipedia.org/wiki/American_Conquest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5nr7.jpg","s":"American Conquest: In the year 1492, travel to America as Christopher Columbus and ignite the fire that will fan 300 years of heated battles for land, riches, and freedom. In eight historical campaigns spanning 42 missions, you will take on the roles of great legends such as Francisco Pizarro and George Washington. Secure new technologies, unique weaponry, and improved fighting units, but also master the delicate world of diplomacy. Play with fire! Conquer America."},{"t":"An American Tail: Fievel's Gold Rush","p":["Game Boy Advance"],"d":"Hokus-Pokus","u":"Swing! Entertainment, Conspiracy Entertainment","g":"Platform","r":"March 1, 2002","l":"https://en.wikipedia.org/wiki/An_American_Tail:_Fievel's_Gold_Rush","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co47xr.jpg","s":"Fievel Mousekewitz, a rodent with an immigration card, is heading west in An American Tail: Fievel's Gold Rush. Based on the animated series from Universal Studios, the game has players controlling Fievel as he travels through 18 levels and six worlds, including \"New York City\" and \"Gold Dust Gulch,\" to piece together Cat Malone's treasure map. Fievel will swing on rope, attack with his ten-gallon hat, ride riverboats, and jump the train to find Wylie Burp's gold."},{"t":"Animal Crossing","p":["GameCube"],"r":"September 15","l":"https://en.wikipedia.org/wiki/Animal_Crossing_(video_game)"},{"t":"Anno 1503","p":["Windows"],"d":"Max Design","u":"Sunflowers Interactive, Electronic Arts, Ubisoft","g":"Real-time strategy, city-building game","r":"October 25, 2002","l":"https://en.wikipedia.org/wiki/Anno_1503","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2i87.jpg","s":"Lay claim to the New World in an epic saga of adventure and discovery. ANNO 1503 A.D. is a PC title that blends the excitement of real-time strategy with the depth of empire building.\nThe aim of the game is to establish colonies and seek out wealth and power. Watch your colonies grow while establishing trade and diplomatic ties with neighbouring cultures. Engage in combat on land and at sea to protect your colonies or to maintain freedom and independence.\nThe all-new combat system allows for much more sophisticated tactical preparation and some truly epic land and sea-based battles. Enjoy the variety and challenge of five varying climate zones while competing against computer-controlled players, including interactions with nine different cultures such as the Africans, Aztecs and Native Americans."},{"t":"Another War","p":["Windows"],"d":"Mirage Interactive","u":"Cenega","g":"role-playing video game","r":"September 30, 2002","l":"https://en.wikipedia.org/wiki/Another_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ie7.jpg","s":"Another War is a role-playing video game set in World War II. The game was released for PC on September 30, 2002 by Czech publisher Cenega. It was later released for Mac on December 31."},{"t":"Antz Extreme Racing","p":["Windows","Xbox","PlayStation 2","Game Boy Advance"],"d":"Supersonic Software, Magic Pockets","u":"Empire Interactive","g":"Racing","r":"July 26, 2002","l":"https://en.wikipedia.org/wiki/Antz_Extreme_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d0x.jpg","s":"0.5 MPH is extremely fast-when your vehicle is only big enough to carry an ant! Jockey for first place with your favorite character from the hit motion picture Antz, using vehicles that aren't your typical garden variety.\n\nSurf using a leaf, race on a fuse with wheels, even hop on a wasp for the antenna-raising thrill ride of your life! You may feel tiny, but practice will make you a giant among racers!"},{"t":"Arc the Lad Collection","p":["PlayStation"],"d":"Working Designs","u":"Working Designs","g":"Tactical role-playing","r":"April 18, 2002","l":"https://en.wikipedia.org/wiki/Arc_the_Lad_Collection"},{"t":"Archangel","p":["Windows"],"d":"Metropolis Software","u":"JoWooD Productions","g":"Action role-playing","r":"October 18, 2002","l":"https://en.wikipedia.org/wiki/Archangel_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sdo.jpg","s":"Archangel is an action game with slight role-playing elements. Travinsky can explore the worlds freely, talk to other characters and take on various side quests. During fights, the focus of the game, he can either use a variety of standard weapons (melee and ranged) or special abilities (e.g. health regeneration, a shield or invisibility) which use up his spirit energy. This energy automatically refills over time, but is also required to use the powerful Sword of Light. He can also shapeshift into either a strong warrior or a sneaky ghost, but which one has to be chosen at the start of the game. Solving quests and killing enemies rewards experience points which are used to upgrade special abilities and the second form."},{"t":"Armored Core 3","p":["PlayStation 2"],"r":"September 5","l":"https://en.wikipedia.org/wiki/Armored_Core_3"},{"t":"Armored Task Force","p":[],"l":"https://en.wikipedia.org/wiki/Armored_Task_Force"},{"t":"Army Men: RTS","p":["PlayStation 2"],"r":"March 27"},{"t":"Arthur's Knights II: The Secret of Merlin","p":["Windows"],"d":"Cryo Interactive Entertainment","u":"Wanadoo Edition, DreamCatcher Interactive","g":"Role-playing video game, third-person adventure","r":"April 2002","l":"https://en.wikipedia.org/wiki/Arthur's_Knights_II:_The_Secret_of_Merlin","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zj2.jpg","s":"Arthur's Knights II: The Secret of Merlin follows 2000's Arthur's Knights: Tales of Chivalry. The player takes the role of a knight of King Arthur."},{"t":"Arthur's Quest: Battle for the Kingdom","p":["Windows"],"d":"3LV Games","u":"ValuSoft","g":"First-person shooter","r":"August 21, 2002","l":"https://en.wikipedia.org/wiki/Arthur's_Quest:_Battle_for_the_Kingdom","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4tds.jpg","s":"A first-person action game based on the Arthurian legend."},{"t":"Arx Fatalis","p":["Windows"],"d":"Arkane Studios","u":"JoWooD Productions, Arkane Studios, DreamCatcher Interactive, Mindscape","g":"Action role-playing, dungeon crawl","r":"June 28, 2002","l":"https://en.wikipedia.org/wiki/Arx_Fatalis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2zpp.jpg","s":"This critically acclaimed first-person RPG takes the player on an incredible adventure in the fantastic world of Arx. The game mixes an intelligent story with immersive and real medieval environments. Arx Fatalis allows the player to feel that all his actions have a direct consequence to all those around him."},{"t":"Asheron's Call 2: Fallen Kings","p":["Windows"],"d":"Turbine Entertainment Software","u":"Microsoft Game Studios, Turbine, Warner Bros. Interactive Entertainment","g":"MMORPG","l":"https://en.wikipedia.org/wiki/Asheron's_Call_2:_Fallen_Kings","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/amgrsae3xhzyrbl9msmp.jpg","s":"Asheron's Call 2: Fallen Kings is a MMORPG, with a monthly subscription, that was released on November 22, 2002 as a sequel to the original Asheron's Call. The severs for AC2 were first shut down in December 2005 when the game did not have enough subscribers to continue being viable for the company to support. \r\n\r\nIt was announced that the game was going to be relaunched as a beta for those subscribed to Asheron's Call on December 13, 2012.\r\n\r\nTurbine announced that is would no longer develop MMOs on December 20, 2016 and that it's servers and account system would be transitioned over to a new studio, Standing Stone Games. As Turbine retained the rights for the Asheron's Call IP the game servers for both MMOs will go offline on January 31, 2017."},{"t":"Astonishia Story","p":["MS-DOS","GP32","Windows"],"d":"Sonnori, Compile Heart","u":"Sonnori, Sega, Ubisoft","g":"Role-playing","r":"January 21, 2002","l":"https://en.wikipedia.org/wiki/Astonishia_Story"},{"t":"Astral Tournament","p":["Windows"],"d":"Apus Software","u":"Apus Software","g":"Turn-based strategy, Collectible card game, Indie game","r":"September 23, 2002","l":"https://en.wikipedia.org/wiki/Astral_Tournament"},{"t":"Atelier Judie: The Alchemist of Gramnad and Atelier Viorate: The Alchemist of Gramnad 2","p":["PlayStation 2"],"d":"Gust","u":"Gust","g":"Role-playing","r":"June 27, 2002","l":"https://en.wikipedia.org/wiki/Atelier_Judie:_The_Alchemist_of_Gramnad_and_Atelier_Viorate:_The_Alchemist_of_Gramnad_2"},{"t":"ATV Offroad Fury 2","p":["PlayStation 2"],"r":"November 9","l":"https://en.wikipedia.org/wiki/ATV_Offroad_Fury_2"},{"t":"Austin Powers Pinball","p":["PlayStation"],"r":"October 25","l":"https://en.wikipedia.org/wiki/Austin_Powers_Pinball"},{"t":"Auto Modellista","p":["PlayStation 2"],"d":"Capcom Production Studio 1","u":"Capcom","g":"Arcade style racing","r":"August 22, 2002","l":"https://en.wikipedia.org/wiki/Auto_Modellista","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa0oh.jpg","s":"Handle the road like a pro with your own customizable racing machine or your choice of more than 60 top-of-the-line models. Race vehicles from manufacturers, including Toyota, Nissan, Honda, Subaru, and Mitsubishi, against up to eight drivers online or up to two drivers in split-screen mode. You'll tear past spectators, maneuver your way through tight mountain passes, and round each corner of the race track in your dream car at lightning speeds."},{"t":"Baldr Force","p":["Dreamcast","Windows","PlayStation 2"],"d":"GIGA","u":"GIGA, Alchemist","g":"action, adventure","r":"November 1, 2002","l":"https://en.wikipedia.org/wiki/Baldr_Force","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2wfv.jpg","s":"In the future, cyberspace has become exceedingly dominant. Armed conflicts and cyber-terrorism flourished. Giant mechas known as Simulacrums are utilized for battles within the cyberspace. Toru Souma is an expert hacker of the Steppenwolf group, which specializes in stealing and selling valuables from servers. One day, Toru was caught in a battle between the military organization FLAK and a terrorist group. In a series of events, his friend was killed. Stricken by grief, Toru decides to avenge his death and joins FLAK, only to unravel a much larger conspiracy.\n\nBaldr Force is a follow-up to Baldr Bullet. It uses a different scenario and character cast, but is very close to its predecessor gameplay-wise. Like in Baldr Bullet (and unlike Baldrhead), there is no exploration of any kind in the game, and all battles take place within confined areas as dictated by the plot. Combat system is nearly identical to that of the previous game, with the exception of \"force crashes\", powerful attacks that can be equipped on the protagonist's mech. The game's plot may branch depending on the decisions taken by the player during the visual novel-like portions."},{"t":"Baldur's Gate: Dark Alliance","p":["Xbox","GameCube"],"r":"October 22"},{"t":"Ballistic: Ecks vs. Sever","p":["Game Boy Advance"],"d":"Crawfish Interactive","u":"BAM! Entertainment","g":"First-person shooter","r":"September 26, 2002","l":"https://en.wikipedia.org/wiki/Ballistic:_Ecks_vs._Sever_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co70ty.jpg","s":"An FBI agent and a rogue NSA agent are pitted against each other in a deadly game of cat and mouse. Both skilled assassins bent on personal revenge, each must terminate the other in order to survive. But unknown to each other, they are both pawns in a much larger conspiracy. Now the as the hunters become the hunted, they must both determine who the real enemy is."},{"t":"Bandits: Phoenix Rising","p":["Windows","Linux"],"d":"Grin","u":"Pan Vision, Tri Synergy, Singularity Software","g":"Vehicular combat","r":"October 4, 2002","l":"https://en.wikipedia.org/wiki/Bandits:_Phoenix_Rising","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ei5.jpg","s":"The game features a story driven single player mode or up to 8 players in deathmatch or team deathmatch over internet or LAN."},{"t":"Barbarian","p":["PlayStation 2"],"r":"June 24","l":"https://en.wikipedia.org/wiki/Barbarian_(2002_video_game)"},{"t":"Barbie Sparkling Ice Show","p":["Windows"],"d":"Krome Studios","u":"Vivendi Universal Games","g":"Sports","r":"November 15, 2002","l":"https://en.wikipedia.org/wiki/Barbie_Sparkling_Ice_Show"},{"t":"Barbie: Groovy Games","p":["Game Boy Advance"],"d":"Digital Illusions Canada","g":"Puzzle","r":"September 2002","l":"https://en.wikipedia.org/wiki/Barbie:_Groovy_Games","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25bi.jpg","s":"Enjoy nine fun and different games in nine cool locations. Compete against Barbie and her friends or against your own friends."},{"t":"Baseball Advance","p":["Game Boy Advance"],"r":"March 20","l":"https://en.wikipedia.org/wiki/Baseball_Advance"},{"t":"Battle Realms: Winter of the Wolf","p":["Windows"],"d":"Liquid Entertainment","u":"Ubi Soft, Crave Entertainment","g":"Real-time strategy","r":"November 5, 2002","l":"https://en.wikipedia.org/wiki/Battle_Realms:_Winter_of_the_Wolf"},{"t":"BattleBots: Beyond the BattleBox","p":["Game Boy Advance"],"d":"Cave+Barn Studios, Pipe Dream Interactive","u":"Majesco, Vivendi Universal Games","g":"Action","r":"December 10, 2002","l":"https://en.wikipedia.org/wiki/BattleBots:_Beyond_the_BattleBox","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co985g.jpg","s":"Welcome to BattleBots, the sport of remote-controlled robotic combat. Based on the popular television series, you build your own customized, radio-controlled robots that employ an array of destructive weaponry such as hammers, saws and spikes. Watch the sparks fly as you duke it out in deadly arenas against your friends or one of the 16 actual BattleBots from the T.V. show. This is the ultimate contest of strategy and creativity where the goal is survival."},{"t":"Battlefield 1942","p":["Windows"],"u":"Electronic Arts","r":"September 10, 2002","l":"https://en.wikipedia.org/wiki/Battlefield_1942"},{"t":"BCT Commander","p":["Windows"],"d":"ProSIM Company","u":"Shrapnel Games","g":"Computer wargame","r":"February 25, 2002","l":"https://en.wikipedia.org/wiki/BCT_Commander"},{"t":"Beach Head 2002","p":["Arcade","macOS","Windows"],"d":"Digital Fusion","u":"Digital Fusion, Infogrames, Inc., MacSoft","g":"First-person shooter, shooting gallery","r":"June 15, 2002","l":"https://en.wikipedia.org/wiki/Beach_Head_2002","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobqct.jpg","s":"BEACHHEAD 2002 follows on the success of BEACHHEAD 2000 with ease of use and hard-core, non-stop 3D shooting action in a photorealistic and accurate environment. Players will be assigned to an inland defense perimeter, protecting a command post to repel an expected airborne assault. It has more depth and game play variations, smarter troops and with more weapons to choose from. Continuous day and night fighting with searchlights and night flares and much, much more."},{"t":"Beach Life","p":["Windows"],"d":"Deep Red Games","u":"Eidos Interactive","g":"Business simulation","r":"September 6, 2002","l":"https://en.wikipedia.org/wiki/Beach_Life","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2v5l.jpg","s":"Beach Life is a business strategy video game for Windows developed by Deep Red Games. The game was published by Eidos Interactive and released on September 6, 2002. In the game, players assume the role of a manager for an island holiday resort. As vacationers enjoy their stay at the resort, players must build, employ, and finance the right lodging, entertainment, and shopping establishments to please the clients and their individual needs."},{"t":"Beach Spikers","p":["GameCube"],"r":"August 12","l":"https://en.wikipedia.org/wiki/Beach_Spikers"},{"t":"Beam Breakers","p":["Windows"],"d":"Similis","u":"JoWooD Productions","g":"Racing","r":"October 21, 2002","l":"https://en.wikipedia.org/wiki/Beam_Breakers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/nfskmwhbb917p1daij7a.jpg","s":"With towering skyscrapers and anti-gravity cars changing the metropolis atmosphere, racing has become a more dangerous sport. Death-defying drivers from rival gangs risk everything in wild, illegal races in the middle of rush hour--always on the run from the MetroPolice. Now, a new challenge has come, and you must take control of one of 30 cars and race against five different gangs. Each track takes you through realistic and densely populated living environments."},{"t":"Beat Angel Escalayer","p":[],"l":"https://en.wikipedia.org/wiki/Beat_Angel_Escalayer"},{"t":"Beatmania IIDX 7th Style","p":["Arcade","PlayStation 2"],"d":"Konami, Konami Computer Entertainment Studio","u":"Konami, Konami Computer Entertainment Studio","g":"Music","r":"March 27, 2002","l":"https://en.wikipedia.org/wiki/Beatmania_IIDX_7th_Style","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hur.jpg","s":"The 7th game in the IIDX series."},{"t":"Beatmania IIDX 8th Style","p":["Arcade","PlayStation 2"],"d":"Konami, Konami Computer Entertainment Studio","u":"Konami","g":"Music","r":"September 27, 2002","l":"https://en.wikipedia.org/wiki/Beatmania_IIDX_8th_Style","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hus.jpg"},{"t":"Beyblade: Super Tournament Battle","p":["GameCube"],"d":"A.I.","u":"Takara, Atari Interactive","g":"Action role-playing","r":"December 19, 2002","l":"https://en.wikipedia.org/wiki/Beyblade:_Super_Tournament_Battle","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co52sv.jpg","s":"Beyblade V-Force: Super Tournament Battle is a Beyblade 2002 role-playing video game. The game was released originally on December 19, 2002 in Japan and was later released in the west in 2003. It is based on the Beyblade V-Force season."},{"t":"Big Air Freestyle","p":["GameCube"],"d":"Paradigm Entertainment","u":"Infogrames","g":"Racing","r":"September 13, 2002","l":"https://en.wikipedia.org/wiki/Big_Air_Freestyle","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6tt0.jpg","s":"Floss and fly your bike through 20 different supercross or motocross tracks with 10 riders on the track fighting for first. Big Air means sick tricks in six freestyle arenas. Nine other bikes will catch your vapors as you fly by. Multiplayer mode for head-to-head action."},{"t":"Big Biz Tycoon","p":["Windows"],"d":"Animedia","u":"Activision Value","g":"Business simulation game","r":"May 30, 2002","l":"https://en.wikipedia.org/wiki/Big_Biz_Tycoon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/k4bwnnldfyrtockmu1c6.jpg","s":"Run the business of your dreams!"},{"t":"Big Money!","p":["Windows"],"g":"Puzzle, Arcade","l":"https://en.wikipedia.org/wiki/Big_Money!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8i89.jpg","s":"Cash in on this excellent puzzle game. Collect groups of 3 or more matching coins... fill up the money meter... grab money bags and advance to the next level. It's sure to keep your interest!"},{"t":"Big Mutha Truckers","p":["PlayStation 2","Xbox"],"d":"Eutechnyx, Raylight Studios","u":"Empire Interactive, THQ, Destination Software, Zoo Digital Publishing","g":"Racing","r":"December 6, 2002","l":"https://en.wikipedia.org/wiki/Big_Mutha_Truckers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7mdv.jpg","s":"Big Mutha Truckers is a truck racing game where you are one of Ma Jackson's four kids. You have to make money for 60 days. The one who earns most money in that period will get Ma's business. There are plenty obstacles to change your success to failure. Players make cash by trading various commodities in the five cities that make up Hick State County, by taking on special jobs (some legal, some not so legal), by wagering with other rival drivers and by causing as much chaos as possible!"},{"t":"Big Scale Racing","p":["Windows"],"d":"BumbleBeast","u":"HD Interactive","g":"Racing","r":"August 16, 2002","l":"https://en.wikipedia.org/wiki/Big_Scale_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobmzi.jpg"},{"t":"Bikini Karate Babes","p":["Windows","macOS"],"d":"Creative Edge Studios","g":"Fighting","l":"https://en.wikipedia.org/wiki/Bikini_Karate_Babes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3gaj.jpg","s":"Bikini Karate Babes combines the basics of a fighting game with realistic real-life video. Players can choose from various (all-female) fighters, with several secret characters incorporated. Play modes include your average 'arcade' mode, but modes like 'spectacle' (watch the CPU do all the work), 'practice' (senselessly beating a passive opponent) and 'marathon' are also included. As a bonus, the game features some 'Sweet Stuff', which acts like a jukebox/gallery sort of section, in which themes and movies can be replayed."},{"t":"Bionicle: Matoran Adventures","p":["Game Boy Advance"],"r":"November 1"},{"t":"Black & White: Creature Isle","p":["Windows","macOS"],"d":"Lionhead Studios","u":"Electronic Arts, Feral Interactive","g":"Real-time strategy, God game","r":"January 23, 2002","l":"https://en.wikipedia.org/wiki/Black_&_White:_Creature_Isle"},{"t":"Black Shades","p":["macOS","Windows","Linux"],"d":"Wolfire Games","u":"Wolfire Games","g":"First-person shooter, stealth","l":"https://en.wikipedia.org/wiki/Black_Shades","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2tth.jpg","s":"Black Shades, the cross platform, open-source, psychic body guard game, has made its way onto the iPhone and iPod Touch! Black Shades was one of the winners of the UDevGame 2002 game contest."},{"t":"Blade II","p":["PlayStation 2"],"r":"September 2","l":"https://en.wikipedia.org/wiki/Blade_II"},{"t":"Blender Bros.","p":["Game Boy Advance"],"r":"April 15","l":"https://en.wikipedia.org/wiki/Blender_Bros."},{"t":"Blinx: The Time Sweeper","p":["Xbox"],"d":"Artoon, Microsoft Game Studios Japan","u":"Microsoft Game Studios","g":"Platform","r":"October 8, 2002","l":"https://en.wikipedia.org/wiki/Blinx:_The_Time_Sweeper","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xqi.jpg","s":"Blinx: The Time Sweeper is a platform game developed by Artoon and published by Microsoft Game Studios. It was released for the Xbox on October 7, 2002. A sequel, Blinx 2: Masters of Time and Space, was released for the Xbox in 2004."},{"t":"Blood Omen 2","p":["PlayStation 2"],"r":"March 21","l":"https://en.wikipedia.org/wiki/Blood_Omen_2"},{"t":"BloodRayne","p":["PlayStation 2"],"r":"October 15","l":"https://en.wikipedia.org/wiki/BloodRayne"},{"t":"Bloody Roar 3","p":["GameCube"],"r":"March 19","l":"https://en.wikipedia.org/wiki/Bloody_Roar_3"},{"t":"Bloody Roar Extreme","p":["GameCube"],"d":"Eighting","u":"Hudson Soft, Activision, Konami","g":"Fighting","r":"March 19, 2002","l":"https://en.wikipedia.org/wiki/Bloody_Roar_Extreme","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4t49.jpg","s":"Bloody Roar Extreme (also known as Bloody Roar: Primal Fury outside of Japan) is a fighting game. It is an updated version of the PS2 game Bloody Roar 3. Players can control a number of characters which have the ability to morph into powerful animals, such as tigers and wolves."},{"t":"Blue's Clues Kindergarten","p":["Windows","macOS"],"d":"ImaginEngine","u":"Infogrames","g":"Edutainment","r":"July 24, 2002","l":"https://en.wikipedia.org/wiki/Blue's_Clues_Kindergarten","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/yxx3mfdmeqg9zx2m3mp9.jpg"},{"t":"BMX XXX","p":["PlayStation 2","GameCube"],"r":"November 16","l":"https://en.wikipedia.org/wiki/BMX_XXX"},{"t":"Bokomu no Tatsujin","p":["Dreamcast"],"g":"Card & Board Game","l":"https://en.wikipedia.org/wiki/Bokomu_no_Tatsujin","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4tqi.jpg","s":"Board game videogame published by Fujicom for the Sega Dreamcast on 2002."},{"t":"Boku no Natsuyasumi 2","p":["PlayStation 2"],"d":"Millennium Kitchen","u":"Sony Computer Entertainment","g":"Adventure","r":"July 11, 2002","l":"https://en.wikipedia.org/wiki/Boku_no_Natsuyasumi_2"},{"t":"Bomber Hehhe!","p":["Dreamcast"],"g":"Simulator, Strategy","l":"https://en.wikipedia.org/wiki/Bomber_Hehhe!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3bzz.jpg","s":"This puzzle simulation tasks players with running a demolition crew. In each stage, players are given a set number of charges and can then navigate through a 3D floor plan, setting charges wherever they want. After setting their charges, the game simulates the building's collapse and players are scored based on how successful their job was. If players do well enough, they can move on to the next stage, but if they do badly enough their botched demolition might just make the evening news."},{"t":"Bomberman Generation","p":["GameCube"],"d":"Game Arts","u":"Majesco, Hudson Soft, Vivendi Universal Games","g":"Action-adventure","r":"June 4, 2002","l":"https://en.wikipedia.org/wiki/Bomberman_Generation","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2w96.jpg","s":"Bomberman returns with a new cel-shaded 3D look. The same storyline applies, however. Bomberman has been given the task of taking back a powerful element of magic, and protecting it from the hands of evil. To do so, he must use his bombing abilites to blast his way through mazes filled with crazy enemies and hidden secrets. There are 5 worlds in all, each with 16 levels to complete. And after completing cetain objectives and picking up items, Bomberman will learn new techniques and abilities to improve his range with his bombs or use new weapons.\n\nAlso included is a 4 player classic bomberman multi-player modes. Unlike the adventure mode, all of the multi-player modes are set in the original 2D, top down style perspective. The last man standing wins in most rounds, with the added twist of other enemies on screen and timed battles."},{"t":"Bomberman Jetters","p":["PlayStation 2","GameCube"],"d":"Hudson Soft, AI","u":"Hudson Soft, Majesco","g":"Action-adventure","r":"December 19, 2002","l":"https://en.wikipedia.org/wiki/Bomberman_Jetters_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5gh1.jpg","s":"Bomberman Jetters is a 2002 Japanese anime television series created by Studio Deen and NAS. It has also spawned two manga series and three video games, one of which was localized and given an English dub. It is based on the popular Bomberman video game series created by Hudson Soft."},{"t":"Bomberman Max 2","p":["Game Boy Advance"],"d":"Hudson Soft","u":"Hudson Soft, Majesco, Vivendi Universal Games","g":"Action","r":"February 7, 2002","l":"https://en.wikipedia.org/wiki/Bomberman_Max_2"},{"t":"Boulder Dash EX","p":["Game Boy Advance"],"r":"September 16","l":"https://en.wikipedia.org/wiki/Boulder_Dash_EX"},{"t":"Bratz","p":["Windows"],"d":"DC Studios","u":"Ubi Soft","g":"Music","r":"December 17, 2002","l":"https://en.wikipedia.org/wiki/Bratz_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobzfn.jpg","s":"This is a dance game where you can be one of the 5 Bratz girls. You can practice or make your way through the Bratz tournament.\n\nThere's a competitive dance mode and a copycat mode where you can have fun with your friends."},{"t":"Breath of Fire II","p":["Game Boy Advance"],"r":"April 15","l":"https://en.wikipedia.org/wiki/Breath_of_Fire_II"},{"t":"Breath of Fire: Dragon Quarter","p":["PlayStation 2"],"d":"Capcom Production Studio 3","u":"Capcom","g":"Role-playing","r":"November 14, 2002","l":"https://en.wikipedia.org/wiki/Breath_of_Fire:_Dragon_Quarter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7k1t.jpg","s":"Breath of Fire: Dragon Quarter is a radical departure from the previous titles of the Breath of Fire series, and in some ways from standard Japanese-style role-playing games in general. The game is built like a huge dungeon crawler, with no overworld map. The combat is tactical: each character has action points (AP), which can be used to move around the screen during an enemy encounter, and perform a variety of combo attacks. There is no magic in the game, and many of the items found in dungeons are random. All the enemies are visible on screen. Depending on who first initiated a physical contact, the party or the enemies get an extra turn in battles.\n\nThe game allows (and even encourages) the player to restart it from the beginning, keeping the items and the party experience. The game also features a special counter - Ryu can use his traditional dragon transformation abilities, but the counter raises with each such transformation, and when the counter reaches 100, the game is over. Raising the D-ratio allows characters to access new areas every time the game is replayed."},{"t":"Britney's Dance Beat","p":["Game Boy Advance","PlayStation 2","Windows"],"r":"March 25","l":"https://en.wikipedia.org/wiki/Britney_Spears_products"},{"t":"Broken Sword: The Shadow of the Templars","p":["Game Boy Advance"],"r":"March 17"},{"t":"Bruce Lee: Quest of the Dragon","p":["Xbox"],"r":"July 2"},{"t":"Brány Skeldalu 2: Pátý Učedník","p":["Windows"],"d":"Napoleon Games","u":"Napoleon Games","g":"Adventure","r":"December 1, 2002","l":"https://en.wikipedia.org/wiki/Br%C3%A1ny_Skeldalu_2:_P%C3%A1t%C3%BD_U%C4%8Dedn%C3%ADk","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ms9.jpg","s":"Help Engeor, a student at the University of Magic, save Rovenland from the evil wizard Wahargem. In the beginning of the game Engeor accidentally says something against the evil wizard and finds himself in a prison camp. His first task is to free himself from the prison so he can continue on his journey to save his country and its inhabitants."},{"t":"Bubble Bobble Old & New","p":[],"l":"https://en.wikipedia.org/wiki/Bubble_Bobble_Old_&_New"},{"t":"Bubble Shooter","p":["macOS","Browser","Mobile phone","Windows Mobile"],"d":"Absolutist LTD, Ilyon Dynamics","u":"Absolutist LTD, Ilyon Dynamics","g":"Puzzle Bobble 2 clone, puzzle","l":"https://en.wikipedia.org/wiki/Bubble_Shooter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobdyh.jpg","s":"Bubble Shooter is an untimed bubble-popping strategy game with a classic interface and arcade special effects noises."},{"t":"Buffy the Vampire Slayer","p":["Xbox"],"r":"August 18","l":"https://en.wikipedia.org/wiki/Buffy_the_Vampire_Slayer_(2002_video_game)"},{"t":"Burnout 2: Point of Impact","p":["PlayStation 2"],"u":"Acclaim Entertainment","r":"September 30, 2002"},{"t":"Cabela's Ultimate Deer Hunt 2","p":["Windows"],"d":"Sylum Entertainment, Ltd.","u":"Activision Value","g":"Sports","r":"September 2002","l":"https://en.wikipedia.org/wiki/Cabela's_Ultimate_Deer_Hunt_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/lfufchglw2sgjmpzuiml.jpg","s":"Cabela's Ultimate Deer Hunt 2 is a realistic hunting simulation with 6 large maps and a variety of deer types. Hunt in Texas, Washington, Alaska, Missouri, Idaho and Michigan. Choose quick hunt for instant action, or mission-based play to face a series of 26 specific challenges. Customize your hunting experience with a wide selection of gear, and set off on your virtual hunt, with full 3D terrain, trees and grass."},{"t":"Car Battler Joe","p":["Game Boy Advance"],"r":"July 30","l":"https://en.wikipedia.org/wiki/Car_Battler_Joe"},{"t":"Carnivores: Cityscape","p":["Windows"],"d":"Sunstorm Interactive","u":"Infogrames","g":"First-person shooter","r":"March 26, 2002","l":"https://en.wikipedia.org/wiki/Carnivores:_Cityscape","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2zh2.jpg","s":"245 million years of evolution collide when a starship crashes, releasing hoards of furious Jurassic beasts into the parks, sewers and streets. Eradicate the escaped carnivores or play the dinosaur and stomp, claw and bite your way to freedom.\n\nDeveloped by Sunstorm Interactive, Carnivores: Cityscape offers up a furious first-person experience with a malevolent motive--the dinosaurs can now fight back, and for the first time, players can assume the role of their favorite carnivore.\n\nWhether thrashing a subway or blasting through a pack of prehistoric flesh, Carnivores: Cityscape magnifies the on-screen mayhem with multiplayer functionality that supports cooperative play and head-to-head \"Dinomatch.\""},{"t":"Casper: Spirit Dimensions","p":["GameCube"],"r":"October 15"},{"t":"Castlevania: Harmony of Dissonance","p":["Game Boy Advance"],"r":"September 16"},{"t":"Castleween","p":["PlayStation 2"],"d":"Wanadoo Edition","u":"Wanadoo Edition, DreamCatcher Interactive, MTO","g":"Platform","r":"November 27, 2002","l":"https://en.wikipedia.org/wiki/Castleween"},{"t":"Celtic Kings: Rage of War","p":["Windows"],"d":"Haemimont Games","u":"Strategy First, Wanadoo Edition","g":"Real-time strategy, role-playing","r":"August 19, 2002","l":"https://en.wikipedia.org/wiki/Celtic_Kings:_Rage_of_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3dcj.jpg","s":"Julius Caesar wants to expand his already massive empire and he has his sights set on the lush countryside of Gaul. Celtic Kings: Rage of war brings you the excitement of the Roman conquests in two modes: strategic and adventure.\n\nIn strategic mode, you play as either the Romans or the Gauls in a world where tactical and strategic maneuveres are the key to victory. In adventure mode you take on the role of Larax and the battle the warring tribes who have raided your village and killed your wife.\n\nTwo exciting game modes, one action-packed conquest - let the best warrior win!"},{"t":"Championship Manager: Season 02/03","p":["Xbox"],"d":"Sports Interactive","u":"Eidos Interactive","g":"Sports","r":"November 29, 2002","l":"https://en.wikipedia.org/wiki/Championship_Manager:_Season_02/03","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/irppn0otsfbescbtjz4f.jpg","s":"The ultimate football management game returns exclusively for Xbox! \nChampionship Manager is undoubtedly the most popular football management game in the UK. With sales of over 3 million worldwide and continued critical acclaim, the series moves from strength to strength. Now the legions of Championship Manager fans can experience the most up to date and accurate football management game ever."},{"t":"Chase: Hollywood Stunt Driver","p":["Xbox"],"d":"I-Imagine Interactive","u":"BAM! Entertainment","g":"Racing, action","r":"September 20, 2002","l":"https://en.wikipedia.org/wiki/Chase:_Hollywood_Stunt_Driver","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co900i.jpg","s":"Chase places you in the exciting world of Hollywood-movie stunt-car action. In the game, you take the role of Chase Corrada, a young stuntwoman who is starting her promising career as a movie stunt driver. In four unique sets--including a gangster set, a postapocalyptic set, and more--it's up to you to perfect the film's action sequences. You'll drive not only traditional 4-wheeled vehicles but also motorcycles and a 3-wheeled Ramen delivery Tuk-Tuk. You'll have to hit your marks as you attempt jumps, smash through props, and race through the set to please the director."},{"t":"Cherry Petals Fall Like Teardrops","p":[],"l":"https://en.wikipedia.org/wiki/Cherry_Petals_Fall_Like_Teardrops"},{"t":"Chessmaster 9000","p":["Windows","macOS"],"d":"Ubi Soft, Zonic","u":"Ubi Soft, Feral Interactive","g":"Computer chess","r":"August 27, 2002","l":"https://en.wikipedia.org/wiki/Chessmaster_9000","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocjmz.jpg","s":"The Chessmaster series returns, offering three variant opponents for players to compete with.\n\nThe Teacher: Chessmaster teaches beginning and advanced players the best openings and the best endings, alerts players to damaging moves, explains why certain moves are illegal, and spots checkmates as many moves in advance as the player wishes.\n\nThe Mentor: Get advice on your next move, see tutorials from chess coach Bruce Pandolfni, study classic games and endings.\n\nThe Ultimate Opponent: Play against Chessmaster's The King AI, compete against over 150 opponents or create your own, or take Chessmaster online and play against human opponents around the world."},{"t":"Chulip","p":["PlayStation 2"],"d":"Punchline","u":"Victor Interactive Software, Natsume Inc.","g":"Adventure, Life simulation","r":"October 3, 2002","l":"https://en.wikipedia.org/wiki/Chulip","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1otk.jpg","s":"You and your penniless father have just moved into a rural town famous for an ancient legend. It's been said that a couple who kisses underneath the old tree will be destined to live happily ever after. With your eyes set on a girl living in a nearby pipe...you set out on your quest. Filled with a new determination, you've sworn to yourself that you'll do whatever it takes to kiss this charming little girl underneath the ancient tree and spend the rest of your life with her."},{"t":"Circus Maximus: Chariot Wars","p":["PlayStation 2"],"r":"February 24"},{"t":"Civilization III: Play the World","p":["Windows"],"d":"Firaxis Games","u":"Infogrames Interactive","g":"Turn-based strategy","r":"October 29, 2002","l":"https://en.wikipedia.org/wiki/Civilization_III:_Play_the_World"},{"t":"Clock Tower 3","p":["PlayStation 2"],"d":"Capcom, Sunsoft","u":"Capcom","g":"Survival horror","r":"December 12, 2002","l":"https://en.wikipedia.org/wiki/Clock_Tower_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1otl.jpg","s":"Clock Tower 3 is a survival horror video game co-developed by Capcom and Sunsoft for the PlayStation 2. Released in 2002, it is the fourth installment in the Clock Tower series, and the first and only video game directed by Japanese film director Kinji Fukasaku. The plot and characters have very little relation with the previous Clock Tower games. The story follows 14-year-old Alyssa Hamilton who is part of a family lineage of female warriors who travel through time to defeat evil spirits. Alyssa travels from her time in 2003 London to the 1940s and 1960s in order to defeat these \"Entities\" and bring peace to troubled souls."},{"t":"Colin McRae Rally 2.0","p":["Game Boy Advance"],"r":"September 16","l":"https://en.wikipedia.org/wiki/Colin_McRae_Rally_2.0"},{"t":"Colin McRae Rally 3","p":["PlayStation 2","Xbox"],"d":"Codemasters","u":"Codemasters","g":"Racing","r":"October 25, 2002","l":"https://en.wikipedia.org/wiki/Colin_McRae_Rally_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1otn.jpg","s":"You are given 3 seasons to win the world rally championship, racing the Ford Focus RS RWC. In each season there are 8 competitions, staged in Australia, the USA, England, Sweden, Japan, Greece and Finland. Each competition has 6 stages set around different landscapes, and a special head-to-head stage at the end. You are out to beat the clock, and the time set by the opposing teams, on each occasion. Beat the time, win the stage, and you are once step closer to taking the world title.\n\nAlong the way you can alter and modify the Focus' setup, from the wheels used, gearboxes, brakes, suspension and so forth. You can also test drive the car before any event to make sure the setup is to your liking."},{"t":"Coloball 2002","p":["PlayStation 2"],"d":"Vanpool","u":"Enterbrain","g":"Turn-based strategy","r":"June 27, 2002","l":"https://en.wikipedia.org/wiki/Coloball_2002","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2v45.jpg","s":"Coloball 2002 is a turn-based strategy role-playing video game for the PlayStation 2. The game was developed by Vanpool and published by Enterbrain exclusively in Japan on June 27, 2002. The title Coloball is short for \"Colosseum Ball,\" and although the game is touted as a sports adventure game, it is most similar to an RPG board game."},{"t":"Combat Flight Simulator 3","p":["Windows"],"d":"Microsoft Game Studios","u":"Microsoft Game Studios","g":"Combat flight simulator","r":"October 24, 2002","l":"https://en.wikipedia.org/wiki/Combat_Flight_Simulator_3"},{"t":"Combat Mission II: Barbarossa to Berlin","p":["Windows"],"u":"Battlefront.com","r":"September 20, 2002"},{"t":"Command & Conquer: Renegade","p":["Windows"],"g":"Action, Adventure, Strategy","r":"February 26","l":"https://store.steampowered.com/app/2229890","i":"images/steam-2229890.jpg","s":"Command &amp; Conquer gets up close and personal in this classic First Person Shooter for one of the most iconic franchises."},{"t":"Commandos 2: Men of Courage","p":["PlayStation 2"],"r":"August 28"},{"t":"Conflict: Desert Storm","p":["PlayStation 2"],"r":"September 30"},{"t":"Contra Advance: The Alien Wars EX","p":["Game Boy Advance"],"r":"November 3"},{"t":"Contra: Shattered Soldier","p":["PlayStation 2"],"r":"October 22"},{"t":"Crash Bandicoot: The Huge Adventure","p":["Game Boy Advance"],"r":"February 25"},{"t":"Crash Bandicoot: The Wrath of Cortex","p":["GameCube"],"r":"September 17"},{"t":"Crazy Taxi 3: High Roller","p":["Xbox"],"d":"Hitmaker","u":"Sega","g":"Racing, action","r":"July 23, 2002","l":"https://en.wikipedia.org/wiki/Crazy_Taxi_3:_High_Roller","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaszs.jpg","s":"After New York, what city could be screwy enough for a CRAZY TAXI game? You guessed it, an amped-up version of Las Vegas serves as the backdrop for this chapter in this ultra-tense driving game. As with previous series installments, the object of the game is to collect as much fare money as possible by picking up and delivering passengers at record speeds. You'll have to create a few shortcuts of your won in order to win, and that will mean causing a few crashes and knocking down a few buildings."},{"t":"Crimson Sea","p":["Xbox"],"d":"Koei","u":"Koei","g":"Third-person shooter, Hack and slash, Action adventure, RPG","r":"December 12, 2002","l":"https://en.wikipedia.org/wiki/Crimson_Sea","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ypk.jpg","s":"Travel thousands of years into the future to the galaxy Theophilus. As Sho, your job is to solve the mystery of countless murders that have been committed by an invading alien force. Along the way, you'll decimate hordes of alien creatures and liquid-morphing enemies with customized blaster rifles and plasma swords. Summon the power of Neo-Psionics to blast through hordes of alien menaces in a single move. Now, with Crimson Sea's Phantom Sensor System, use sound and touch to discover the hidden enemy."},{"t":"CT Special Forces","p":["Game Boy Advance","PlayStation"],"d":"Light & Shadow Production","u":"Light & Shadow Production, Hip Games","g":"Run and gun","r":"July 12, 2002","l":"https://en.wikipedia.org/wiki/CT_Special_Forces","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3zgn.jpg","s":"As part of the Counter-Terrorist Special Forces unit, you have all the necessary means for putting an end to the threat of terrorism. Your team comprises highly trained soldiers who can do anything from dressing in camouflage to initiating surgical strikes on the enemy. In both ground missions and air combat, you'll plunge into 12 levels that span jungles, cities, mountains, and deserts. You can equip your team with various state-of-the-art weapons, including assault rifles and rocket launchers. Multiplayer mode lets you team up with a friend to complete missions."},{"t":"Cubivore: Survival of the Fittest","p":["GameCube"],"d":"Saru Brunei, Intelligent Systems","u":"Nintendo, Atlus USA","g":"Action-adventure","r":"February 21, 2002","l":"https://en.wikipedia.org/wiki/Cubivore:_Survival_of_the_Fittest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xtb.jpg","s":"Eat or be eaten! Assume the role of an animal in it's early stages of evolutionary development. As your animal instincts take over, you will boldly traverse hostile environments, savagely stalking your prey to assert your place in the animal chain of power. Will you have what it takes to become the new king of beasts?\n\nThe game started development on the Nintendo 64, but went unreleased, being later ported to the Nintendo GameCube. A prototype of the Nintendo 64 version has been found."},{"t":"Cultures 2: The Gates of Asgard","p":["Windows"],"d":"Funatics Software","u":"JoWooD Productions","g":"Real-time strategy, City-building game","r":"July 12, 2002","l":"https://en.wikipedia.org/wiki/Cultures_2:_The_Gates_of_Asgard","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23hn.jpg","s":"The Viking Bjarni whiles his days days away in an idyllic village on Greenland’s coast until a dark prophecy knocks on his door. In his premonition, Bjarni witnesses an epic struggle between the forces of Good and Evil. He must journey to battle the Midgard Serpent. Get ready for a quest that will take you through Europe (including England and Byzantium) and the outskirts of Baghdad. Your journey will unite the four great western cultures with a common purpose. But how long can it last? Inspired by Norse mythology, the real time strategy title, Cultures 2: Gates of Asgard, combines elements of simulation, adventure, and role-playing to immerse you in Bjarni’s quest to defeat the fabled beast."},{"t":"Custom Robo GX","p":["Game Boy Advance"],"d":"Noise","u":"Nintendo","g":"Action role-playing","r":"July 26, 2002","l":"https://en.wikipedia.org/wiki/Custom_Robo_GX","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co509y.jpg","s":"The Game Boy Advance iteration in the Custom Robo franchise.\n\nCustom Robo GX is a Japan-exclusive GBA version of Custom Robo. It maintains the series' trademark RPG-hybrid gameplay, but changes the battle system to accommodate the limited capacity of the GBA.\n\nThe Robos can still be customized in the same manner as the console games (Body, Gun, Bomb, Pod, Feet) but the battles take place on a 2-d plane in zero gravity. There is still auto-aim, and the Robos have the same fire modes as the console releases. Different arenas have obstacles, and Robos have dash moves to move around them more effectively. Generally a Robo is based on its 3d counterpart, so a slow and powerful Robo will still be slow and powerful.\n\nThis game was originally planned to be the first Custom Robo game released in America, but Nintendo chose the Gamecube release instead."},{"t":"CyberVirus","p":["Atari Lynx"],"d":"Beyond Games","u":"Songbird Productions","g":"First-person shooter","l":"https://en.wikipedia.org/wiki/CyberVirus"},{"t":"Da Capo","p":[],"l":"https://en.wikipedia.org/wiki/Da_Capo_(video_game)"},{"t":"Dance Dance Revolution 4thMix","p":["Arcade","PlayStation","Windows"],"d":"Konami","u":"Konami","g":"Music, exercise","r":"April 30, 2002","l":"https://en.wikipedia.org/wiki/Dance_Dance_Revolution_4thMix"},{"t":"Dance Dance Revolution Extreme","p":["Arcade"],"d":"Konami, Bemani","u":"Konami","g":"Music, exercise","r":"December 25, 2002","l":"https://en.wikipedia.org/wiki/Dance_Dance_Revolution_Extreme","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5eg5.jpg","s":"Dance Dance Revolution Extreme is a music video game by Konami and is the eighth release in the main Dance Dance Revolution (DDR) series. It was released on December 25, 2002 for Japanese arcades, on October 9, 2003 for the Japanese PlayStation 2, and on September 21, 2004 for the North American PlayStation 2. This game is the ninth release in North America, but despite having the same name as its Japanese counterpart, its gameplay and soundtrack is significantly different[1] and won the Video Music Awards in 2005 on MTV for Best Video Game Soundtrack.\n\nWhile the PlayStation 2 version came out in North America, the arcade version was exclusive to Japan. Despite this, the arcade version was exported to many arcades in the USA (most of them being bootlegged). Dance Dance Revolution Extreme was the last game in the DDR arcade franchise for four years until Dance Dance Revolution SuperNova in 2006. The arcade release of the game contains one of the largest soundtracks of any DDR game, featuring 240 songs, as well as music from other Bemani music titles. Konami issued an in-game thank you to the fans of Dance Dance Revolution and announced a rejuvenation of the entire series, but did not go into details. Konami's announcement led people to believe that DDR Extreme might be the final DDR release or that the series might be on hiatus or rebooted in the same manner as Beatmania and Beatmania IIDX."},{"t":"Dark Arena","p":["Game Boy Advance"],"r":"January 18","l":"https://en.wikipedia.org/wiki/Dark_Arena"},{"t":"Dark Chronicle","p":["PlayStation 2"],"u":"Sony Computer Entertainment","r":"November 28, 2002","l":"https://en.wikipedia.org/wiki/Dark_Chronicle"},{"t":"Dark Fall","p":["Windows"],"d":"XXv Productions","u":"XXv Productions, Darkling Room, Iceberg Interactive","g":"Adventure, psychological horror","r":"April 2002","l":"https://en.wikipedia.org/wiki/Dark_Fall","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3o3x.jpg","s":"This Myst-style horror-adventure game will bring fear into your heart. From the very beginning you are exposed to an overwhelming but invisible ghost presence – strange calls, footsteps, voices from nowhere. In order to help your brother and survive you will need to solve the mystery of this abandoned, haunted place. And remember! Do not let it to find you! Do not let it to find you... Do not.. Let... find...\n\nThe game is best played in a dark room with your speakers turned up. Unless you're scared, of course."},{"t":"Dark Planet: Battle for Natrolis","p":["Windows"],"d":"Creative Edge Software","u":"Ubi Soft","g":"Real-time strategy","r":"March 21, 2002","l":"https://en.wikipedia.org/wiki/Dark_Planet:_Battle_for_Natrolis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3izh.jpg","s":"3 unique races to play with different strategies for success: Colonists - High Tech (a sci-fi mechanized army), Sorin - Swords and Sorcery (a fantasy army with magic powers), Dreil - Monsters (use brute force and hive and cocooning behavior)\n\nHighly detailed 3D world with day and night cycles, plants that sway in the wind, and ambient creatures that have their own life cycles and AI. Realistic weather that effects your strategy. Rains will slow down movement, wind patterns change, nighttime brings darkness.\n\nTrue 3D engine with fully adjustable perspective, zoom, and viewing angle.\n\nClassic RTS Gameplay with brand new concepts. Easy to learn, but a challenge to master.\n\nMultiplayer options with several different modes, including Domination, Capture the Flag, and Campaign."},{"t":"Darkened Skye","p":["Windows","GameCube"],"d":"Boston Animation","u":"Simon & Schuster Interactive, Oxygen Interactive, TDK Mediactive Europe","g":"Third-person shooter, action-adventure","r":"January 28, 2002","l":"https://en.wikipedia.org/wiki/Darkened_Skye","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2i93.jpg","s":"In the action-oriented 3D role-playing game Darkened Skye, the player takes the role of the title character and embarks on a quest to collect four prisms that may help bring the light of goodness back to the world. Skye of Lynlora was just a restless shepherd when she first came across the strange item that would change her life forever. Now she has opened a portal to another place and chaos has come forth. Only Skye can set things right once again. She will face an assortment of fantasy characters and creatures in her journeys as she makes her way through 30 missions set across five different game worlds. It is notable that, like some other releases from publisher Simon and Schuster (including the Boston Animation-developed M&M's: The Lost Formulas), this game features prominent product placement in the form of Skittles brand fruit-flavored candies. Indeed, it is the mystic power of Skittles that moves Skye through more than one threatening game situation. In spite of any potential incongruities of featuring a familiar consumer item in a fantasy world, Darkened Skye strives to provide the graphical competence, engrossing story, and state-of-the-art play that gamers expect from a major 2002 release. ~ T.J. Deci, All Game Guide"},{"t":"Dave Mirra Freestyle BMX 3","p":["Game Boy Advance"],"r":"November 26","l":"https://en.wikipedia.org/wiki/Dave_Mirra_Freestyle_BMX_3"},{"t":"David Beckham Soccer","p":["Game Boy Advance"],"r":"October 7","l":"https://en.wikipedia.org/wiki/David_Beckham_Soccer"},{"t":"Davis Cup Tennis","p":["Game Boy Advance"],"d":"Hokus Pokus Games","u":"Ubisoft","g":"Sports","r":"June 7, 2002","l":"https://en.wikipedia.org/wiki/Davis_Cup_Tennis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/scnmbq2j3l7l0kdbamhl.jpg","s":"Enter a battle among tennis legends. With 142 nations abattling to possess the Silver Trophy, the biggest war of the tennis world is about to begin! Play in the Davis CupTournament or challenge friends to fierce 2-on-2 multiplayer matches. Gain experience points for your team and pit them against your friends in multiplayer mode. Master your game on clay, carpet, and grass."},{"t":"DDRMAX: Dance Dance Revolution","p":["PlayStation 2"],"r":"October 28"},{"t":"Dead to Rights","p":["Xbox","PlayStation 2"],"r":"June 3","l":"https://en.wikipedia.org/wiki/Dead_to_Rights"},{"t":"Deadly Dozen: Pacific Theater","p":["Windows"],"d":"Interactive","u":"Infogrames","g":"Tactical shooter","r":"November 11, 2002","l":"https://en.wikipedia.org/wiki/Deadly_Dozen:_Pacific_Theater","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3o8u.jpg","s":"Deadly Dozen: Pacific Theater is a World War II oriented squad-based first-person shooter developed by nFusion Interactive and is the sequel to Deadly Dozen."},{"t":"Deathrow","p":["Xbox"],"r":"October 22","l":"https://en.wikipedia.org/wiki/Deathrow_(video_game)"},{"t":"Defender","p":["PlayStation 2"],"r":"October 22","l":"https://en.wikipedia.org/wiki/Defender_(2002_video_game)"},{"t":"Delta Force: Task Force Dagger","p":["Windows"],"d":"Zombie Inc.","u":"NovaLogic","g":"First-person shooter","r":"June 26, 2002","l":"https://en.wikipedia.org/wiki/Delta_Force:_Task_Force_Dagger","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3oc1.jpg","s":"As the US army's elite special operations soldiers you are the most potent 'smart weapon' known to man. You are the 'tip of the spear' for covert operations around the world — you are the first line of attack. Nothing stands in your way. From the war torn streets of Somalia you have been re-deployed to take out targets in Colombia and Iran. As the US military's preemptive strike force you must work with your team to get the job done."},{"t":"Delta Force: Urban Warfare","p":["PlayStation"],"d":"Rebellion Developments","u":"NovaLogic","g":"Tactical first-person shooter","r":"July 2, 2002","l":"https://en.wikipedia.org/wiki/Delta_Force:_Urban_Warfare","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8z8d.jpg","s":"Delta Force: Urban Warfare is a first-person shooter by developer and publisher NovaLogic. It was designed to be a military simulation loosely based on the Delta Force special operations force. The storyline spans twelve missions, including a bank robbery, hostage rescue, and an assault on an offshore oil rig."},{"t":"Demon Front","p":["Arcade"],"d":"IGS","u":"IGS","g":"Run and gun","l":"https://en.wikipedia.org/wiki/Demon_Front","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6vd8.jpg","s":"The gameplay is similar to Metal Slug and other run and gun games. It lacks the vehicles that were an element of Metal Slug.\n\nIn addition, there are some unique features in the game. Each of the four characters brings along a pet, which can be sent to attack enemies or used as a shield. There are three buttons: Shoot, jump, and shield. Holding the shoot button charges your pet, and when released the pet launches a stationary devastating attack for a few seconds. The shield button converts the pet into a shield that is permanent - until you press the button again or it takes enough damage to disappear. Melee attacks and pet attacks release hearts which boost your shield power.\n\nCharacters include Jake and Sara, two regular humans from Earth. Dr. J, a scientist, and Maya an ape. All characters largely play the same."},{"t":"Densetsu no Starfy","p":["Game Boy Advance"],"d":"Tose","u":"Nintendo","g":"Platform","r":"September 6, 2002","l":"https://en.wikipedia.org/wiki/Densetsu_no_Starfy_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4an9.jpg","s":"In the beginning, Starfy was moving things around Pufftop Palace, until he tripped and dropped some things he was moving. One of them fell into the ocean, which was the Magic Jar, an object that seals the evil being known as Ogura."},{"t":"Destroyer Command","p":["Windows"],"d":"Ultimation Inc.","u":"Ubisoft","g":"Vehicle simulation game","r":"February 17, 2002","l":"https://en.wikipedia.org/wiki/Destroyer_Command","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/u9uyfowrsoqssl5zvah0.jpg","s":"The game placed the player in command of a Destroyer during World War II, featuring campaigns from both the Pacific War and the Battle of the Atlantic. Customized missions may be played and players can select the opponent's forces and their own. Players can also have the chance to choose the difficulty rating in different games by adjusting the different realism ratings . \n \nThe game features two campaigns that include the entire Pacific and Atlantic warfare with 20 missions each. There are 20 predefined historical missions, for example, the 'Battle of Savo Island', additionally to some training missions, and automatically generated, customized missions. Classes of Destroyers that can be commanded by the player are Bagley, Benham, Benson, Clemson, Farragut, Fletcher, Gleaves, Gridley, Mahan, Porter, Somers, Sims, Allen M. Sumner, and the Wickes classes. \n \nWeaponry that can be controlled by the player are the dual purpose 5\"/38 caliber gun, the 4-inch/50 SP gun, the light guns Bofors 40 mm gun and Oerlikon 20 mm cannon, 200 to 600 lb depth charges, and 21-inch torpedoes."},{"t":"Deus Ex: The Conspiracy","p":["PlayStation 2"],"r":"March 25"},{"t":"Dexter's Laboratory: Chess Challenge","p":["Game Boy Advance"],"r":"October 29"},{"t":"Dexter's Laboratory: Mandark's Lab?","p":["PlayStation"],"d":"Red Lemon Studios","u":"BAM! Entertainment","g":"Action-adventure","r":"March 29, 2002","l":"https://en.wikipedia.org/wiki/Dexter's_Laboratory:_Mandark's_Lab%3F","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ta0.jpg","s":"Cartoon Network's boy genius Dexter is trying to save his laboratory from his archival Mandark in Dexter's Laboratory: Mandark's Lab? Mandark has infiltrated Dexter's lab and reprogrammed his computer, so players must help Dexter win it back by completing this adventure game covering four areas comprised of Dexter's house and his laboratory.\n\nIn each area there are two mini-games and four hidden blueprint pieces to one of Dexter's inventions that give him an advantage in each of the mini-games. Both Dee Dee's Dance Off, which has players pressing buttons in time to music, and Cootie Call where Dexter exterminates flying cootie bugs, take place in Dee Dee's bedroom. What's Buggin' Dexter, a foot race between Dexter and a bug that could potentially infect his computer, takes place in his computer's circuit board, and Dexter's Dodgeball takes place in the school yard with Dexter targeting school bullies with playground balls."},{"t":"Dhaka Racing","p":["Windows"],"d":"eSophers","u":"eSophers","g":"Racing","r":"March 2, 2002","l":"https://en.wikipedia.org/wiki/Dhaka_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob9yo.jpg","s":"Dhaka Racing is a racing game set in the streets of Dhaka. It was the first 3D game developed in Bangladesh."},{"t":"Die Hard: Nakatomi Plaza","p":["Windows"],"d":"Piranha Games","u":"Sierra Entertainment, Fox Interactive","g":"First-person shooter","r":"April 23, 2002","l":"https://en.wikipedia.org/wiki/Die_Hard:_Nakatomi_Plaza","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2y56.jpg","s":"The game is a first-person shooter that follows the plot of the first Die Hard film. Players take the role of John McClane, and try to stop the terrorist attack on the Nakatomi Plaza. The game's levels are based on the sets from the film. The various action scenes from the film have also been recreated.\n\nThe game expands on the film's plot, and adds a few missions not found in the film, such as escorting a SWAT team around the building or saving various hostages stranded on various floors of the building."},{"t":"Die Hard: Vendetta","p":["GameCube"],"d":"Bits Studios","u":"Vivendi Universal Games, Fox Interactive","g":"First-person shooter","r":"November 15, 2002","l":"https://en.wikipedia.org/wiki/Die_Hard:_Vendetta","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ou6.jpg","s":"John McClane is back. Many years have passed since his work in New York, and he now works for the Century City Police Department (CCPD) in Los Angeles.\n\nYou are in John's shoes as he must face a new threat. Piet Gruber, the son of Hans Gruber and McClane's old enemy, is up to no good at the Townsend Art Museum. He has stolen valuable art and kidnapped John's now adult daughter and fellow CCPD police officer, Lucy.\n\nThis game is a First Person Shooter, but it also adds two features: Stealth Mode and Hero Time. Stealth Mode allows John to sneak around quietly, even being able to grab his foes and use them as hostages. This means it may not be best to go in guns blazing, when they could be arrested. Hero Time allows John to react far more quickly, just like Bullet Time in Max Payne. Hero Time is earned by saving hostages and performing heroic tasks in the game."},{"t":"Digimon Battle Online","p":["Windows"],"d":"movegames, WeMade Entertainment","u":"movegames, Bandai, CDC Games, WeMade Entertainment, GAMEKING","g":"Massively multiplayer online role-playing","r":"January 22, 2002","l":"https://en.wikipedia.org/wiki/Digimon_Battle_Online"},{"t":"Digimon Tamers: Battle Spirit Ver. 1.5","p":["WonderSwan Color"],"d":"Dimps","u":"Bandai","g":"Fighting","r":"April 27, 2002","l":"https://en.wikipedia.org/wiki/Digimon_Tamers:_Battle_Spirit_Ver._1.5"},{"t":"Digimon World 3","p":["PlayStation"],"r":"June 5","l":"https://en.wikipedia.org/wiki/Digimon_World_3"},{"t":"Digital Monster Card Game Ver. WonderSwan Color","p":["WonderSwan Color"],"g":"Turn-based strategy (TBS)","l":"https://en.wikipedia.org/wiki/Digital_Monster_Card_Game_Ver._WonderSwan_Color","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7jxw.jpg","s":"Digital Monster Card Game Ver. WonderSwan Color is a Strategy game, developed by Tom Create and published by Bandai, which was released in Japan in 2002."},{"t":"Digital Monster: D-Project","p":[],"l":"https://en.wikipedia.org/wiki/Digital_Monster:_D-Project"},{"t":"Dino Island","p":["Windows"],"d":"Monte Cristo","u":"Monte Cristo, Strategy First","g":"Business simulation","r":"May 22, 2002","l":"https://en.wikipedia.org/wiki/Dino_Island","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co306f.jpg","s":"Dino Island is a theme park simulator not unlike Theme Park, Roller Coaster Tycoon, or even Zoo Tycoon. However, it is rendered in full 3D - players can rotate, pan and zoom at will. Dinosaurs, staff and visitors are fully animated. The game uses a typical point and click and menu interface."},{"t":"Dino Stalker","p":["PlayStation 2"],"r":"September 9","l":"https://en.wikipedia.org/wiki/Dino_Stalker"},{"t":"Dinotopia: The Timestone Paradise","p":["Game Boy Advance"],"r":"April 30"},{"t":"Dinotopia: The Timestone Pirates","p":["Game Boy Advance"],"d":"RFX Interactive","u":"TDK Mediactive","g":"Action","r":"April 30, 2002","l":"https://en.wikipedia.org/wiki/Dinotopia:_The_Timestone_Pirates","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2zk9.jpg","s":"Danger! Angry dinosaurs are poised for invasion. Scurvy pirates are hungry for treasure. And an ancient stone of unimaginable power is about to fall into the wrong hands. Take to the skies and prepare for battle -- only you can preserve the special world that is Dinotopia!"},{"t":"Dirt Track Racing 2","p":["Windows"],"d":"Ratbag Games","u":"Infogrames","g":"Racing","r":"September 24, 2002","l":"https://en.wikipedia.org/wiki/Dirt_Track_Racing_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9fda.jpg","s":"Dirt Track Racing 2 is a video game developed by the now-defunct Australian-based Ratbag Games and published by Infogrames. It is the third and final game in the Dirt Track Racing series by Ratbag."},{"t":"Disciples II: Dark Prophecy","p":["Windows"],"r":"January 24"},{"t":"Disney Golf","p":["PlayStation 2"],"r":"October 17","l":"https://en.wikipedia.org/wiki/Disney_Golf"},{"t":"Disney Sports Basketball","p":["Game Boy Advance","GameCube"],"d":"Konami Computer Entertainment Osaka, Polygon Magic","u":"Konami","g":"Sports","r":"November 25, 2002","l":"https://en.wikipedia.org/wiki/Disney_Sports_Basketball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rzc.jpg","s":"Mickey and his pals are holding court! Are you ready for some of the fastest-paced, highest-flying, hardest-slamming basketball action you've ever seen? Disney Sports Basketball brings exaggerated moves and original locations to life as your favorite Disney characters take to the court.\n\nGame features include 2-on-2 courtside action, 6 game modes including a full range of mini games and over 25 magic items to boost performance."},{"t":"Disney Sports Football","p":["Game Boy Advance","GameCube"],"d":"Konami Computer Entertainment Osaka","u":"Konami","g":"Sports","r":"July 25, 2002","l":"https://en.wikipedia.org/wiki/Disney_Sports_Football","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d13.jpg","s":"Get ready for hard-hitting tackles and wild touchdowns as Mickey, Goofy, and other Disney characters take to the gridiron. In Disney Sports Football, you'll create a team and compete in four modes: Challenge, Cup, Exhibition, and Practice. You'll have plenty of running and passing plays, offensive and defensive formations, and turbo moves to master, plus magic items to boost your team's performance. In single or multiplayer modes, you'll face a variety of opponents inside fantastic stadiums."},{"t":"Disney Sports Skateboarding","p":["Game Boy Advance"],"r":"November 15","l":"https://en.wikipedia.org/wiki/Disney_Sports_Skateboarding"},{"t":"Disney Sports Soccer","p":["Game Boy Advance","GameCube"],"d":"Konami Computer Entertainment Osaka","u":"Konami","g":"Sports","r":"July 18, 2002","l":"https://en.wikipedia.org/wiki/Disney_Sports_Soccer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocu7y.jpg","s":"Disney Sports Soccer takes the fun of a neighborhood soccer game and adds the excitement of Disney-style competition. Seven distinctive game modes, as well as a multi-player mode create the perfect soccer experience."},{"t":"Disney's Kim Possible: Revenge of Monkey Fist","p":["Game Boy Advance"],"r":"November 22","l":"https://en.wikipedia.org/wiki/Kim_Possible_(video_game_series)"},{"t":"Disney's Lilo & Stitch","p":["Game Boy Advance","PlayStation"],"r":"June 7","l":"https://en.wikipedia.org/wiki/Lilo_%26_Stitch_(franchise)#Video_games"},{"t":"Disney's Magical Mirror Starring Mickey Mouse","p":["GameCube"],"d":"Capcom","u":"Nintendo","g":"Adventure","r":"August 9, 2002","l":"https://en.wikipedia.org/wiki/Disney's_Magical_Mirror_Starring_Mickey_Mouse","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dz2.jpg","s":"One night, a mischievous ghost traps a sleepwalking Mickey Mouse in a magical mirror. Returning to his bed won't be easy, though, because Mickey must first recover the broken mirror pieces that have been strewn about the house by the prankish poltergeist. Just as in a Mickey cartoon, you will have to outwit enemies and pull gags. You will also be able to uncover special souvenirs, such as Pluto's collar or Minnie's bow, which are all displayed in Mickey's room at the end of the game."},{"t":"Disney's Party","p":["GameCube"],"d":"Neverland, Jupiter Corporation","u":"Hudson Soft, Tomy, Electronic Arts","g":"Party","r":"August 1, 2002","l":"https://en.wikipedia.org/wiki/Disney's_Party","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2cy5.jpg","s":"Uncle Scrooge has invited you and a whole cast of Disney characters to visit his new Party Park, which he designed himself with all of his favorite youngsters in mind. Disney's Party drops you into the mix with Mickey Mouse and friends to embark on challenging adventures that include collecting magical objects, solving puzzles, and maneuvering through obstacle courses. Each player must complete his or her game board by buying or winning special items, such as stars, lollipops, and teacups. In four different gameplay modes, you can compete with friends in minigames, solve puzzles, and explore a variety of environments."},{"t":"Disney's PK: Out of the Shadows","p":["PlayStation 2"],"r":"November 1"},{"t":"Disney's Stitch: Experiment 626","p":["PlayStation 2"],"r":"June 19"},{"t":"Disney's Tarzan: Return to the Jungle","p":["Game Boy Advance"],"r":"September 14"},{"t":"Disney's Treasure Planet","p":["PlayStation 2"],"r":"November 11"},{"t":"Divine Divinity","p":["Windows"],"g":"RPG","r":"September 22","l":"https://en.wikipedia.org/wiki/Divine_Divinity","i":"images/steam-214170.jpg","s":"Divine Divinity is an epic role-playing game with hack-and-slash action, offering a huge world to explore and thousands of items to investigate, trade and use."},{"t":"DoDonPachi DaiOuJou","p":["Arcade"],"d":"Cave","u":"AMI","g":"Bullet hell","r":"April 2002","l":"https://en.wikipedia.org/wiki/DoDonPachi_DaiOuJou","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3c0h.jpg","s":"The fourth game in the Donpachi series."},{"t":"Doki Doki Idol Star Seeker Remix","p":[],"l":"https://en.wikipedia.org/wiki/Doki_Doki_Idol_Star_Seeker_Remix"},{"t":"Dokodemo Chocobo","p":[],"l":"https://en.wikipedia.org/wiki/Dokodemo_Chocobo"},{"t":"Donald Trump's Real Estate Tycoon","p":["Windows"],"d":"RedCap GmbH, Airborne Entertainment Inc.","u":"Activision Value, Empire Interactive","g":"Business simulation","r":"November 7, 2002","l":"https://en.wikipedia.org/wiki/Donald_Trump's_Real_Estate_Tycoon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w36.jpg","s":"One of the modern world's most famous entrepreneurs offers gamers the role of an international mogul in Donald Trump's Real-Estate Tycoon. The overall goal of the game is to unseat Trump himself as the most influential magnate on the planet. Players must find the best building site in which to found their business empires, choosing from locations in New York, Los Angeles, Atlantic City, London, and Paris. Design an office space layout to appeal to high-rent tenants and keep things running smoothly by hiring maintenance personnel."},{"t":"Doom II: Hell on Earth","p":["Game Boy Advance"],"r":"October 28"},{"t":"Downforce","p":["PlayStation 2"],"r":"June 14","l":"https://en.wikipedia.org/wiki/Downforce"},{"t":"Dr. Muto","p":["PlayStation 2"],"r":"November 19","l":"https://en.wikipedia.org/wiki/Dr._Muto"},{"t":"Dragon Ball Z: Budokai","p":["PlayStation 2"],"r":"December 3"},{"t":"Dragon Ball Z: Legendary Super Warriors","p":["Game Boy Color"],"d":"Flight-Plan","u":"Infogrames Europe, Banpresto, Infogrames","g":"Role-playing","r":"June 28, 2002","l":"https://en.wikipedia.org/wiki/Dragon_Ball_Z:_Legendary_Super_Warriors","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wb5.jpg","s":"Dragon Ball Z: Legendary Super Warriors is a mixture of a card game and a turn-based fighting game for the Game Boy Color. The game is played with original in-game cards for attacks, techniques and support items and initially has only two modes trade and story. Legendary Super Warriors’ story spans from the Saiyan saga to the end of the Buu Saga. Once beaten, a battle mode is unlocked, allowing players to square off with random enemies. Once the game is beaten, any character is usable in any battle, such as Frieza vs. Cell."},{"t":"Dragon Ball Z: The Legacy of Goku","p":["Game Boy Advance"],"r":"May 14"},{"t":"Dragon Quest Monsters 1+2","p":[],"l":"https://en.wikipedia.org/wiki/Dragon_Quest_Monsters_1+2"},{"t":"Dragon Throne: Battle of Red Cliffs","p":["Windows"],"d":"Object Software Limited","u":"Strategy First","g":"Real-time strategy","r":"March 26, 2002","l":"https://en.wikipedia.org/wiki/Dragon_Throne:_Battle_of_Red_Cliffs","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22pb.jpg","s":"San Guo Yan Yi: Huo Shao Chi Bi, also known as The Battle of Red Cliffs, is an unlicensed beat-'em-up game for the Sega Mega Drive released in some unknown year. The game is an unofficial port of the Sega Saturn title Tenchi wo Kurau II: Sekiheki no Tatakai."},{"t":"Dragon's Lair 3D: Return to the Lair","p":["Windows","Xbox"],"d":"Dragonstone Software","u":"Ubi Soft, Encore Software, THQ","g":"Action-adventure","r":"November 18, 2002","l":"https://en.wikipedia.org/wiki/Dragon's_Lair_3D:_Return_to_the_Lair","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22p7.jpg","s":"Dragon's Lair 3D: Return to the Lair is an action-adventure video game released in 2002 by Dragonstone Software. The game is based on Cinematronics' 1983 laserdisc arcade game Dragon's Lair, and follows a similar story; the hero, Dirk the Daring, must enter the evil wizard Mordroc's castle to rescue Princess Daphne from Singe the dragon. Many of the characters and locations from the 1983 original make appearances in the game, along with new puzzles, rooms and enemies. Animator and director Don Bluth, who produced the cartoon animation for the arcade original, also produced two new animated sequences for the opening and ending of the game. The game uses cel shading to mimic the distinctive style of the original."},{"t":"Drakan: The Ancients' Gates","p":["PlayStation 2"],"r":"January 28"},{"t":"Drihoo","p":["Xbox"],"d":"Highwaystar","u":"Highwaystar","g":"Action","r":"November 28, 2002","l":"https://en.wikipedia.org/wiki/Drihoo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co51ui.jpg","s":"Dunk the dwarf is a solo treasure hunter, left to his own devices after a cave-in separates him from the rest of his crew."},{"t":"Droopy's Tennis Open","p":["Game Boy Advance"],"d":"Bit Managers, Warthog Games","u":"Light & Shadow Production","g":"Tennis","r":"October 18, 2002","l":"https://en.wikipedia.org/wiki/Droopy's_Tennis_Open","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ybmatqa6lajw28x7hb6h.jpg","s":"Droopy's Tennis Open for Game Boy Advance has a total of six characters each with their own individual and unique set of characteristics and attributes. The player can choose from Droopy, Dripple, Butch, Bubbles, Vavoom, MC Wolf, and Screwy Squirrel. Each game can be played on a background that ranges like a jail, outside of an Old West saloon, and the North Pole with varying terrain like grass, clay, and ice. Games can be played in a two-player mode over a single cart and even up to four players with the support of a Game Boy Advance link cable. It will even support the Game Boy Advance's downloadable link for players without requiring a copy of the game. One of the best ways to play this game is in the arcade mode. This mode lets players use special impressive attacks when they build up their powers. The character called 'Vavoom' can set in motion a flirty ball that will dodge and sidestep swings. Droopy can blast off three balls of terror at once for players to panic over and attempt to retrieve them. In general, Butch has the most strength while Screwy possesses extraordinary athletic abilities. This arcade style game is a fun way to participate in an entertaining game with classic characters many already know and love."},{"t":"Dropship: United Peace Force","p":["PlayStation 2"],"r":"May 29"},{"t":"Dual Blades","p":["Game Boy Advance"],"r":"October 7","l":"https://en.wikipedia.org/wiki/Dual_Blades"},{"t":"Dual Hearts","p":["PlayStation 2"],"r":"September 23","l":"https://en.wikipedia.org/wiki/Dual_Hearts"},{"t":"Duke Nukem Advance","p":["Game Boy Advance"],"r":"August 12","l":"https://en.wikipedia.org/wiki/Duke_Nukem_Advance"},{"t":"Duke Nukem: Manhattan Project","p":["Windows"],"d":"Sunstorm Interactive","u":"Arush Entertainment, Ubi Soft","g":"Platform","r":"May 17, 2002","l":"https://en.wikipedia.org/wiki/Duke_Nukem:_Manhattan_Project","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9gcv.jpg","s":"Duke Nukem takes his Mighty Boot to the Big Apple. Using GLOPP (Gluon Liquid Omega-Phased Plasma), the maniacal mech Morphix has transformed the creatures of New York City into an army of bloodthirsty mutants. In Duke Nukem: Manhattan Project, Duke must deploy WIN (Weapons, Insults and Name-Calling) to rid the city of goo-based bad guys, and return peace and tranquility to The City That Never Sleeps."},{"t":"Dungeon Siege","p":["Windows"],"g":"RPG","r":"March 31","l":"https://en.wikipedia.org/wiki/Dungeon_Siege","i":"images/steam-39190.jpg","s":"Dungeon Siege® combines the immersive elements of a role-playing game with over-the-top intensity and non-stop action. Dungeon Siege plunges you into a continuous 3D fantasy world where you face off against an army of evil that has been unleashed."},{"t":"Dynasty Tactics","p":["PlayStation 2"],"r":"September 17","l":"https://en.wikipedia.org/wiki/Dynasty_Tactics"},{"t":"Dynomite!","p":["Windows"],"g":"Puzzle, Arcade","l":"https://en.wikipedia.org/wiki/Dynomite!_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22pg.jpg","s":"It's prehistoric egg-blasting fun! Use your slingshot to match three or more dino eggs of the same color... and watch them explode! Can you blast all the eggs before Mama Brontosaurus tramples your game?"},{"t":"Earth & Beyond","p":["Windows"],"d":"Westwood Studios","u":"Electronic Arts","g":"Massively multiplayer online role-playing game","r":"September 24, 2002","l":"https://en.wikipedia.org/wiki/Earth_&_Beyond","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20ii.jpg","s":"Earth and Beyond is a science fiction MMORPG set in a future where three human-descended races—Terrans, Progen, and Jenquai—control different regions of space. The Terrans dominate Earth through powerful trade corporations; the Progen, genetically engineered for strength and efficiency, inhabit Mars; and the Jenquai, focused on knowledge and exploration, occupy space stations orbiting Jupiter’s moons."},{"t":"Earthworm Jim 2","p":["Game Boy Advance"],"r":"May 31","l":"https://en.wikipedia.org/wiki/Earthworm_Jim_2"},{"t":"Ecco the Dolphin: Defender of the Future","p":["PlayStation 2"],"r":"March 3"},{"t":"Egg Mania: Eggstreme Madness","p":["PlayStation 2","Xbox","GameCube","Game Boy Advance"],"d":"HotGen","u":"Kemco","g":"Puzzle","r":"September 11, 2002","l":"https://en.wikipedia.org/wiki/Egg_Mania:_Eggstreme_Madness","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ttp.jpg","s":"As an Eggo builder, its your job to sort and organise air-dropped puzzle pieces to assemble platforms that gradually form a tower above a steadily rising ocean. Because water quickly seeps up through incomplete floors it is vital that you build complete platforms to slow the rising water. The goal is to reach the balloon that hovers high in the sky, however, to complicate matters, tower-tumbling and thieving enemies prowl the depths and soar the skies, looking for ways to drown your spirit - so work quickly!!"},{"t":"Elevator Action Old & New","p":["Game Boy Advance"],"d":"Taito","u":"MediaKite","g":"Platform","r":"December 20, 2002","l":"https://en.wikipedia.org/wiki/Elevator_Action_Old_&_New"},{"t":"Embodiment of Scarlet Devil","p":["Windows"],"r":"August 11","l":"https://en.wikipedia.org/wiki/Embodiment_of_Scarlet_Devil"},{"t":"Emogame","p":["Browser"],"g":"Action","l":"https://en.wikipedia.org/wiki/Emogame"},{"t":"Emperor: Rise of the Middle Kingdom","p":["Windows"],"d":"BreakAway Games, Impressions Games","u":"Sierra Entertainment","g":"City-building","r":"September 10, 2002","l":"https://en.wikipedia.org/wiki/Emperor:_Rise_of_the_Middle_Kingdom","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22rl.jpg","s":"Emperor: The Rise of the Middle Kingdom is a game about politics, trade, and city design in ancient China. In Emperor, players progress through 3000 years of Chinese history, facing ever-changing economic, military, and diplomatic challenges as each Chinese dynasty waxes and wanes."},{"t":"Empire Earth: The Art of Conquest","p":["Windows"],"d":"Mad Doc Software","u":"Sierra Entertainment","g":"Real-time strategy","r":"September 17, 2002","l":"https://en.wikipedia.org/wiki/Empire_Earth:_The_Art_of_Conquest"},{"t":"Enclave","p":["Xbox"],"d":"Starbreeze Studios","u":"Swing! Entertainment, Conspiracy Games, Atari Europe S.A.S.U., Black Label Games","g":"Action-adventure","r":"July 19, 2002","l":"https://en.wikipedia.org/wiki/Enclave_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2h0w.jpg","s":"Enclave is a level-based action RPG game with a mix of shooting and puzzles, pitting the player as one of twelve different characters on either side in this medieval era. As a member of the Light side: a Knight, a Huntress, a Wizard, a Druid, an Engineer or a Halfling can be chosen. At the opposite end of the spectrum: a Berserker, an Assassin, a Sorceress, a Lich, a Bombardier, or a Goblin. The player needs to perform different tasks leading ultimately to one objective; protect the Enclave (Light) or invade the land (Dark). To accomplish these tasks, various weapons, such as swords, bows, staffs and spears, can be used. To aid the player, shields are readily available, as well as a select few potions. Armor is abundant and comes in many shapes and sizes."},{"t":"Endgame","p":["PlayStation 2"],"r":"June 3"},{"t":"Enigma","p":["Windows","macOS","Linux"],"d":"Ronald Lamprecht, Raoul Bourquin, Andreas Lochmann, Daniel Heck, ...","g":"Puzzle","r":"May 14, 2002","l":"https://en.wikipedia.org/wiki/Enigma_(2002_video_game)"},{"t":"Enzai: Falsely Accused","p":[],"l":"https://en.wikipedia.org/wiki/Enzai:_Falsely_Accused"},{"t":"EOE: Eve of Extinction","p":["PlayStation 2"],"r":"February 26"},{"t":"Escape Velocity Nova","p":["macOS","Windows"],"d":"Ambrosia Software and ATMOS","u":"Ambrosia Software","g":"Space trading and combat game","r":"March 19, 2002","l":"https://en.wikipedia.org/wiki/Escape_Velocity_Nova","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3rnq.jpg","s":"Escape Velocity Nova (a.k.a. EV Nova or EVN) is a video game by Ambrosia Software, in collaboration with ATMOS. It is the third game in the Escape Velocity series of space trading & combat games."},{"t":"ESPN International Winter Sports 2002","p":["PlayStation 2"],"r":"January 28","l":"https://en.wikipedia.org/wiki/ESPN_International_Winter_Sports_2002"},{"t":"ESPN MLS ExtraTime 2002","p":["Xbox"],"r":"March 27","l":"https://en.wikipedia.org/wiki/ESPN_MLS_ExtraTime_2002"},{"t":"ESPN NBA 2Night 2002","p":["PlayStation 2"],"r":"February 25","l":"https://en.wikipedia.org/wiki/ESPN_NBA_2Night_2002"},{"t":"ESPN Winter X-Games Snowboarding 2002","p":["PlayStation 2"],"r":"January 14","l":"https://en.wikipedia.org/wiki/ESPN_Winter_X-Games_Snowboarding_2002"},{"t":"Eternal Darkness","p":["GameCube"],"u":"Nintendo","r":"June 23, 2002","l":"https://en.wikipedia.org/wiki/Eternal_Darkness"},{"t":"Eternal Daughter","p":["Windows"],"u":"Blackeye Software","g":"Action-adventure","r":"June 21, 2002","l":"https://en.wikipedia.org/wiki/Eternal_Daughter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2uwh.jpg","s":"Eternal Daughter is a free action-adventure game inspired by Super Metroid and Castlevania: Symphony of the Night."},{"t":"Ethnic Cleansing","p":["Windows"],"d":"National Alliance","u":"Resistance Records","g":"First-person shooter","r":"January 21, 2002","l":"https://en.wikipedia.org/wiki/Ethnic_Cleansing_(video_game)"},{"t":"Europa 1400: The Guild","p":["Windows"],"d":"4HEAD Studios","u":"JoWooD Productions","g":"Life simulation","r":"October 18, 2002","l":"https://en.wikipedia.org/wiki/Europa_1400:_The_Guild","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sbw.jpg","s":"It’s the year 1400- the late Middle Ages. Europe sees the dawn of the golden age of the new departures and the free spirit. Under the rule of the bourgeoisie and businessmen, more and more towns are emerging from the clutches of the aristocracy and are achieving independence, power and wealth. New businesses are flourishing, bringing financial strength and political influence to a growing economy.\n\nHowever, life in the narrow, overpopulated alleyways and streets of the towns also has its downsides: epidemics and diseases are spreading, and thieves and highwaymen lie in wait to get their piece of the wealth. Now you can try your hand in these exciting times of change. Will you head down the path of an honest craftsman or a dubious priest? It’s your choice."},{"t":"Ever 17: The Out of Infinity","p":["Dreamcast","PlayStation 2"],"d":"KID, Cyberfront, 5pb.","u":"KID, Success, Cyberfront, Hirameki","g":"Visual novel","r":"August 29, 2002","l":"https://en.wikipedia.org/wiki/Ever_17:_The_Out_of_Infinity","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q3u.jpg","s":"Ever 17: The Out of Infinity is a visual novel video game developed by KID. It is the second entry in the Infinity series; it is preceded by Never 7: The End of Infinity, and followed by Remember 11: The Age of Infinity, 12Riven: The Psi-Climinal of Integral, and Code_18.\n\nFrom VNDB:\n\"Ever17 is the tale of seven individuals who come to be trapped 153 feet within the underwater marine theme park, LeMU. During an apparently normal day at the park, a massive accident happens, placing almost half of the facility underwater. The path to the surface and the communication lines are cut off. In addition, LeMU is under constant assault by severe water pressure, limiting time to find a means of escape to 119 hours. Escape is not the only concern, however; many questions arise as to the legitimacy of the accident and whether or not those trapped there were brought there for a purpose.\""},{"t":"EverQuest: The Planes of Power","p":[],"l":"https://en.wikipedia.org/wiki/EverQuest:_The_Planes_of_Power"},{"t":"Evil Twin: Cyprien's Chronicles","p":["Dreamcast"],"r":"April 12"},{"t":"Evolution Skateboarding","p":["PlayStation 2"],"r":"October 9","l":"https://en.wikipedia.org/wiki/Evolution_Skateboarding"},{"t":"Evolution Snowboarding","p":["PlayStation 2"],"d":"Konami Computer Entertainment Osaka","u":"Konami","g":"Snowboarding","r":"November 25, 2002","l":"https://en.wikipedia.org/wiki/Evolution_Snowboarding","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5tyz.jpg","s":"Evolution Snowboarding is a sports video game first released on November 25, 2002 for the PlayStation 2. It was later released on February 25, 2003 for the Nintendo GameCube. The game was both developed and published by Japanese game company Konami. The game takes a new perspective on the snowboarding genre."},{"t":"Evolution Worlds","p":["GameCube"],"d":"Sting Entertainment","u":"Entertainment Software Publishing, Ubi Soft","g":"Role-playing","r":"July 26, 2002","l":"https://en.wikipedia.org/wiki/Evolution_Worlds"},{"t":"Extreme Ghostbusters: Code Ecto-1","p":["Game Boy Advance"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Extreme_Ghostbusters:_Code_Ecto-1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co85bn.jpg","s":"Extreme Ghostbusters: Code Ecto-1 (also released as Extreme Ghostbusters in North America) is the second of the Light & Shadow Production releases and was for the Game Boy Advance in March 2002. It commonly has been mistaken for Extreme Ghostbusters Video Game for GBC(Gameboy Color). The half-human/half-demon Count Mercharior has kidnapped Roland and Garett, two key members of the Ghostbusters team. The remaining team members, Eduardo and Kylie, immediately set off to find them, determined to capture the ghosts who have come to invade the city. The game was a combination platform and shooter game with some races, using a top-down perspective. There were 12 platform levels and four regions. It is especially interesting that the ghosts in the game can be either blasted by the proton gun or trapped."},{"t":"Eye of the Beholder","p":["Game Boy Advance"],"d":"Pronto Games","u":"Infogrames","g":"Role-playing","r":"November 8, 2002","l":"https://en.wikipedia.org/wiki/Eye_of_the_Beholder_(2002_video_game)"},{"t":"F1 2002","p":["Windows","PlayStation 2"],"u":"EA Sports","r":"June 13, 2002","l":"https://en.wikipedia.org/wiki/F1_2002_(video_game)"},{"t":"Fantasy Masters","p":["Windows"],"d":"Zeonix","g":"Fantasy, NTCG","l":"https://en.wikipedia.org/wiki/Fantasy_Masters"},{"t":"Farscape: The Game","p":["Windows"],"d":"Red Lemon Studios, Jim Henson Interactive","u":"Simon & Schuster","g":"Science fiction, Action-Adventure","r":"August 8, 2002","l":"https://en.wikipedia.org/wiki/Farscape:_The_Game","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co40h6.jpg","s":"Game based on the first season of the television show Farscape."},{"t":"Fatal Frame","p":["PlayStation 2","Xbox"],"r":"March 4","l":"https://en.wikipedia.org/wiki/Fatal_Frame_(video_game)"},{"t":"FateLords","p":[],"l":"https://en.wikipedia.org/wiki/FateLords"},{"t":"Ferrari F355 Challenge","p":["PlayStation 2"],"r":"September 28","l":"https://en.wikipedia.org/wiki/Ferrari_F355_Challenge"},{"t":"FIFA Football 2003","p":["Xbox","PlayStation 2","Game Boy Advance"],"u":"Electronic Arts","r":"November 1, 2002","l":"https://en.wikipedia.org/wiki/FIFA_Football_2003"},{"t":"FIFA Soccer 2003","p":["PlayStation 2"],"r":"November 14","l":"https://en.wikipedia.org/wiki/FIFA_Soccer_2003"},{"t":"Fila World Tour Tennis","p":["Windows","Xbox"],"d":"Hokus Pokus","u":"THQ, Xicat Interactive","g":"Sports","r":"September 2002","l":"https://en.wikipedia.org/wiki/Fila_World_Tour_Tennis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3rkr.jpg","s":"A fast-paced arcade tennis game with FILA branded clothes and equipment."},{"t":"Final Fantasy Origins","p":["PlayStation"],"d":"Squaresoft","u":"Square","g":"Role-playing","r":"October 31","l":"https://en.wikipedia.org/wiki/Final_Fantasy_Origins"},{"t":"Final Fantasy XI","p":["PlayStation 2"],"r":"May 16","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XI"},{"t":"Final Fantasy: Unlimited with U","p":["Mobile phone"],"g":"Role-playing (RPG)","l":"https://en.wikipedia.org/wiki/Final_Fantasy:_Unlimited_with_U","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2x5p.jpg","s":"A Japanese-only game for the i-mode service on cell phones based on the television anime Final Fantasy: Unlimited. It consists mostly of traditional RPG battles and assorted minigames, with the playable characters being the main characters of the TV series."},{"t":"Fire Blade","p":["PlayStation 2"],"r":"June 16"},{"t":"Fire Emblem: The Binding Blade","p":["Game Boy Advance"],"d":"Intelligent Systems","u":"Nintendo","g":"Tactical role-playing","r":"March 29, 2002","l":"https://en.wikipedia.org/wiki/Fire_Emblem:_The_Binding_Blade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobag0.jpg","s":"Fire Emblem: The Binding Blade is a Japanese tactical role-playing game developed by Intelligent Systems and published by Nintendo. The game was released on March 29, 2002 in Japan, is the sixth game in the Fire Emblem series, and the first of three games in the series that have appeared on Nintendo's Game Boy Advance handheld. It was the last Fire Emblem game to be released exclusively in Japan until the release of Fire Emblem: New Mystery of the Emblem. The Binding Blade was followed by a prequel, Fire Emblem: The Blazing Blade, set twenty years earlier."},{"t":"Fire Pro Wrestling 2","p":["Game Boy Advance"],"r":"October 23","l":"https://en.wikipedia.org/wiki/Fire_Pro_Wrestling_2"},{"t":"Firebugs","p":["PlayStation"],"d":"Attention to Detail","u":"Sony Computer Entertainment","g":"Racing","r":"October 18, 2002","l":"https://en.wikipedia.org/wiki/Firebugs_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co52sq.jpg","s":"Welcome to the Firebugs racing season, where teams of different worlds send their best racer to compete for fame and glory. Play as Gismo, Karrie, Zero, BOW or Kami - each with a background story, unique special weapon, and alternate vehicle designs that can be unlocked. You race in five distinct worlds: a group of linked islands (Archipelago), a droid factory (Droid Gardens), a desert wasteland (Terrian Dunes), an industrial area (Sky Port) and a wealthy city (Aerial City). While racing, the personal weapon is stored in the left weapon bay. Random weapons that can be picked up by all racers are stored on the right."},{"t":"First Kiss Story II","p":["Dreamcast","PlayStation 2"],"d":"HuneX, M2","u":"Broccoli, Arcadia Entertainer","g":"Visual novel","r":"August 8, 2002","l":"https://en.wikipedia.org/wiki/First_Kiss_Story_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8is4.jpg","s":"First Kiss Story II is a romance visual novel."},{"t":"Fly Guy","p":["Browser"],"u":"Trevor van Meter","g":"Graphic adventure","l":"https://en.wikipedia.org/wiki/Fly_Guy_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5z51.jpg","s":"A businessman, waiting for the bus, daydreams about escaping to more exciting locations. The player can guide him up off the ground and into the air, where he can meet with interesting people and find somewhere to escape to."},{"t":"FooBillard","p":["Linux","macOS","Windows"],"d":"Florian Berger","g":"Sports","l":"https://en.wikipedia.org/wiki/FooBillard"},{"t":"Football Mania","p":["PlayStation 2","Windows","Game Boy Advance"],"d":"Silicon Dreams Studio, Tiertex Design Studios","u":"Electronic Arts, Lego Interactive","g":"Sports video game","r":"June 18, 2002","l":"https://en.wikipedia.org/wiki/Football_Mania"},{"t":"Forever Kingdom","p":["PlayStation 2"],"r":"January 22","l":"https://en.wikipedia.org/wiki/Forever_Kingdom"},{"t":"Formula One 2002","p":["PlayStation 2"],"d":"Studio Liverpool","u":"Sony Computer Entertainment","g":"Racing","r":"November 1, 2002","l":"https://en.wikipedia.org/wiki/Formula_One_2002_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9rll.jpg","s":"Formula One 2002 is a Driving game, developed by Studio Liverpool and published by SCEE, which was released in Europe in 2002."},{"t":"Formula One Arcade","p":["PlayStation"],"d":"Studio 33","u":"Sony Computer Entertainment","g":"Racing","r":"July 19, 2002","l":"https://en.wikipedia.org/wiki/Formula_One_Arcade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocd18.jpg","s":"Do you like F1 cars but hate realism? Then this is the Formula One game for you."},{"t":"Freaks!","p":[],"l":"https://en.wikipedia.org/wiki/Freaks!"},{"t":"Freedom Force","p":["Windows"],"u":"Electronic Arts","g":"RPG, Strategy","r":"March 26, 2002","l":"https://en.wikipedia.org/wiki/Freedom_Force_(2002_video_game)","i":"images/steam-8880.jpg","s":"From a distant corner of the galaxy, an evil alien race sets in motion a sinister plan to conquer the Earth. They unleash a powerful catalyst — Energy X — that imbues the planet's worst miscreants with super-powers to bring the planet to its knees. Now Earth's only hope lies with a new breed of heroes... The Freedom Force!"},{"t":"Freekstyle","p":["PlayStation 2"],"r":"June 18","l":"https://en.wikipedia.org/wiki/Freekstyle"},{"t":"Frogger Advance: The Great Quest","p":["Game Boy Advance"],"d":"Vicarious Visions","u":"Konami","g":"Platform","r":"May 28, 2002","l":"https://en.wikipedia.org/wiki/Frogger_Advance:_The_Great_Quest"},{"t":"Frogger Beyond","p":["GameCube","Xbox"],"r":"December 10","l":"https://en.wikipedia.org/wiki/Frogger_Beyond"},{"t":"Frogger's Adventures 2: The Lost Wand","p":["Game Boy Advance"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Frogger's_Adventures_2:_The_Lost_Wand","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4de7.jpg","s":"Frogger's Adventures 2: The Lost Wand is an Adventure game, developed and published by Konami, which was released in 2002."},{"t":"From TV Animation - One Piece: Grand Battle! 2","p":["PlayStation"],"d":"Ganbarion","u":"Bandai","g":"Action","r":"March 20, 2002","l":"https://en.wikipedia.org/wiki/From_TV_Animation_-_One_Piece:_Grand_Battle!_2"},{"t":"Frozen Bubble","p":["Linux"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Frozen_Bubble","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9b2w.jpg","s":"Frozen Bubble is a puzzle game that started out on Linux and has later been ported to other systems."},{"t":"G1 Jockey 3","p":["PlayStation 2"],"d":"Koei","u":"Koei, THQ","g":"Horse racing","r":"December 21, 2002","l":"https://en.wikipedia.org/wiki/G1_Jockey_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/roy4xoonsbpyusii3c0e.jpg","s":"Fancy hats, oval turf tracks and people waving tiny bits of paper on the stands. Welcome to the world of horse racing. While most other racing games have the player controlling a motorized vehicle (such as a car or a powerboat), or using physics to move closer to the goal (skiing, sailing and so on), in G1 Jockey the player is controlling an animal, which makes it slightly different from other racing games in the market. \n \nThe player has to balance four things - the overall speed of the horse, the stamina, horse motivation, and the potential, which affects for how long the horse can keep the speed high after all stamina was lost - crucial for the last stretch sprint. It's impossible to raise all four at once, so players must have a well defined strategy to succeed. \n \nDepending on their abilities, each horse might be better suited for a particular strategy or type of race, and each must be treated differently to achieve the best possible result. The game features a large roster of horses, and many tracks to choose from, including flat track and steeplechase races. Game modes include race training, a tutorial, two player mode, and the career mode, where the player starts as a rookie jockey, and must complete races and training sessions to attract the attention of better stables."},{"t":"Gakuen Toshi Vara Noir","p":["PlayStation 2"],"g":"Role-playing (RPG), Adventure","l":"https://en.wikipedia.org/wiki/Gakuen_Toshi_Vara_Noir","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6tu3.jpg","s":"The threat of demonic invasion gives impetus to the fledgling Simba Empire to found a school of magic called Vara Noir. With the world recovering after a devastating war, the Empire uses the school to train students in the ways of battle and magic to prepare for any imminent and far-off threats. Enter 13-year old chimney sweeper Myu who cleans smokestacks and other debris laden orifices. One day, her grandpappy hands her a mighty sword and a few ducats and commands her to apply to Vara Noir for an education in the mystic arts. Myu takes the entrance examination and passes with flying colors. As such, she enters Vara Noir academy and goes on an adventure where she will eventually help save the kingdom.\n\nIdea Factory's latest game in the Kingdom of Chaos series features dungeon exploration, character interaction and an Megami-Tensei-esque item synthesis system where special items found in dungeons may be bonded with weapons to increase attack power, imbue properties, etc. Interaction sequences are of the point 'n click sort where questions and answers are rattled off in routine fashion.\n\nOriginally released on the PS2, Gakuen Toshi Vara Noir joins the Gamecube library with new animation sequences and graphical updates which freshen up the adventure for old and new gamers to enjoy."},{"t":"Galerians: Ash","p":["PlayStation 2"],"d":"Polygon Magic","u":"Enterbrain, Sammy Studios, Sammy Europe","g":"Survival horror","r":"April 25, 2002","l":"https://en.wikipedia.org/wiki/Galerians:_Ash","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2zjp.jpg","s":"Survival horror and science fiction come together in the sequel to Galerians. In Galerians: Ash, you reprise the role of Rion as he fights the Last Galerians and their evil leader Ash, who wants to destroy all organic life on Earth. Joined once again by Lilia, you must battle your enemies with all-new psychic attacks and neural enhancers across new and expansive environments. In this game, a strong psyche, puzzle-solving skills, and quick reflexes are most valuable to success."},{"t":"Galidor: Defenders of the Outer Dimension","p":["Game Boy Advance"],"g":"Platform, Adventure","l":"https://en.wikipedia.org/wiki/Galidor:_Defenders_of_the_Outer_Dimension","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9rzq.jpg","s":"Taking on the role of the hero Nick Bluetooth -- straight out of the hit Fox Kids TV series, GALIDOR: Defenders of the Outer Dimension -- players find themselves in an Outer Dimension on an action-packed quest to free friends who have fallen into the clutches of the evil tyrant Gorm.\n\nWith the ultimate goal of finding the portal to GALIDOR and ridding the Outer Dimension of its wicked ruler, Nick encounters many challenges and menacing creatures along the way. Armed with the awe-inspiring ability to \"glinch\" or absorb the attributes of enemies he defeats, Nick can fly, jump, grapple and navigate through his adventures."},{"t":"Gallop Racer 2003: A New Breed","p":["PlayStation 2"],"d":"Tecmo","u":"Tecmo, ZOO Digital","g":"Alternative sports","r":"December 12, 2002","l":"https://en.wikipedia.org/wiki/Gallop_Racer_2003:_A_New_Breed","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yg4.jpg","s":"Gallop Racer 2003 (known as \"Gallop Racer 6: Revolution\" in Japan) is an update of it's previous incarnations with the standard modes (exhibition and season mode) and has six different jockeys to choose for the players character in the season mode as well as 32 different tracks and over 3000 different horses.\n\nPlayers can breed horses using a series of mini-games, the outcome, either good or bad, will determine the type of horse, the better the player is at the mini-games, the more powerful the breed will be. Also the player can bet on races in the season mode, using the proceeds to buy better facilities to train their stable. It also features an extensive training program for new players to the Gallop series."},{"t":"Game & Watch Gallery 4","p":["Game Boy Advance"],"d":"Tose","u":"Nintendo","g":"Various","r":"October 25, 2002","l":"https://en.wikipedia.org/wiki/Game_&_Watch_Gallery_4"},{"t":"Gauntlet: Dark Legacy","p":["Game Boy Advance"],"r":"November 25"},{"t":"Gekido Advance: Kintaro's Revenge","p":["Game Boy Advance"],"d":"NAPS team","u":"Zoo Digital Publishing, DSI Games, Naps Team","g":"Beat 'em up","r":"November 8, 2002","l":"https://en.wikipedia.org/wiki/Gekido_Advance:_Kintaro's_Revenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2w76.jpg","s":"It's Time to Fight! \n \nA year has passed since the epic battle that decided the fate of mankind and claimed the life of the beloved Angela. Dark omens once again tell of the return of an evil presence. Ushi is the last remaining master of the ancient art of Shin-Ken, and he calls upon Tetsuo, his disciple and adopted son, to investigate some strange happenings in a faraway farming village outside the city."},{"t":"GioGio's Bizarre Adventure","p":["PlayStation 2"],"d":"Capcom","u":"Capcom","g":"Action-adventure","r":"July 25, 2002","l":"https://en.wikipedia.org/wiki/GioGio's_Bizarre_Adventure"},{"t":"Gitaroo Man","p":["PlayStation 2"],"r":"February 19","l":"https://en.wikipedia.org/wiki/Gitaroo_Man"},{"t":"Global Operations","p":["Windows"],"d":"Barking Dog Studios","u":"Crave Entertainment, Electronic Arts","g":"First-person shooter, tactical shooter","r":"March 25, 2002","l":"https://en.wikipedia.org/wiki/Global_Operations","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rqh.jpg","s":"Global Operations is a first-person tactical shooter computer game developed by Barking Dog Studios and published by both Crave Entertainment and Electronic Arts. It was released in March 2002. (Wikipedia)"},{"t":"Global Touring Challenge: Africa","p":["PlayStation 2"],"r":"June 14"},{"t":"Glove on Fight","p":["Windows"],"d":"Watanabe Seisakujo","u":"Watanabe Seisakujo","g":"Versus fighting game","r":"May 12, 2002","l":"https://en.wikipedia.org/wiki/Glove_on_Fight","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9b6s.jpg","s":"A super-deformed parody fighting game from Soft Circle French-Bread."},{"t":"Go! Go! Beckham! Adventure on Soccer Island","p":["Game Boy Advance"],"d":"Denki","u":"Rage Software","g":"Platformer","l":"https://en.wikipedia.org/wiki/Go!_Go!_Beckham!_Adventure_on_Soccer_Island","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co52dd.jpg","s":"Go! Go! Beckham! Adventure on Soccer Island is an Action game, developed by Denki and published by Rage Software, which was released in Europe in 2002."},{"t":"GoDai: Elemental Force","p":["PlayStation 2"],"d":"The 3DO Company","u":"The 3DO Company","g":"Action","r":"January 21, 2002","l":"https://en.wikipedia.org/wiki/GoDai:_Elemental_Force","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ovk.jpg","s":"Hiro was orphaned shortly after being born; his parents the king and queen killed by the evil Element Master Akunin. Now fully grown, Hiro sets out to best the four element trials and become an Element Master himself, while Akunin waits for the chance to finish what he started years ago. The elemental trial of Earth is the first Hiro must complete, but after that the three remaining trials, as well as the stages leading up to them, may be attempted in any order. On his quest Hiro will find many weapons of different classes, such a short swords and spears. These weapons will become damaged over time and eventually break, but they can be repaired with an item Hiro can find. After having completed an elemental trial Hiro gains the ability to cast magic of that element, increasing his effectiveness against enemies weak to that element.\n\nIn multiplayer mode two players can face off against each other in deathmatch arenas with special rules, such as tag, survival, and time attack."},{"t":"Godzilla: Destroy All Monsters Melee","p":["GameCube"],"r":"October 8"},{"t":"Godzilla: Domination!","p":["Game Boy Advance"],"r":"November 11"},{"t":"Gore: Ultimate Soldier","p":["Windows"],"d":"4D Rulers","u":"DreamCatcher Interactive","g":"First-person shooter","r":"June 3, 2002","l":"https://en.wikipedia.org/wiki/Gore:_Ultimate_Soldier","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25od.jpg","s":"New technology has led to the development of an advanced combat training emulator, where the weak have died and the best become even better. Known as the Meat Machine, this device takes Marines where they have never been, shows them enemies they have never faced, and trains them with both existing and advanced weaponry. As one of a variety of characters, you'll explore expansive levels with many ladders and basements, pick up or destroy items, and conserve your ammo and stamina for intense firefights."},{"t":"Gothic II","p":["Windows"],"d":"Piranha Bytes","u":"JoWooD Productions, Infogrames Europe, Atari, THQ Nordic","g":"Action role-playing","r":"November 29, 2002","l":"https://en.wikipedia.org/wiki/Gothic_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25ag.jpg","s":"Gothic II is a role-playing video game and the sequel to Gothic, by the German developer Piranha Bytes. It was first released on November 29, 2002 in Germany, with North America following almost one year later on October 28, 2003. The game was published by JoWooD Entertainment and Atari."},{"t":"GP Challenge","p":["PlayStation"],"d":"Midas Interactive Entertainment","u":"Midas Interactive Entertainment","g":"Formula One racing","r":"April 12, 2002","l":"https://en.wikipedia.org/wiki/GP_Challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8ho1.jpg","s":"GP Challenge puts the player in the role of a GP driver and allow him to compete in 4 different circuits."},{"t":"Gran Turismo Concept","p":["PlayStation 2"],"d":"Polyphony Digital","u":"Sony Computer Entertainment","g":"Racing simulation","r":"January 1, 2002","l":"https://en.wikipedia.org/wiki/Gran_Turismo_Concept"},{"t":"Grand Prix 4","p":["Windows"],"d":"Simergy","u":"Infogrames","g":"Racing simulation","r":"June 14, 2002","l":"https://en.wikipedia.org/wiki/Grand_Prix_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q9o.jpg","s":"Grand Prix 4 also known as GP4 is the fourth game in the \"Geoff Crammond Grand Prix\" series based on the 2001 F1 Grand Prix series and was the last version of the game released by Geoff Crammond and MicroProse."},{"t":"Grand Prix Challenge","p":["PlayStation 2"],"d":"Infogrames Melbourne House","u":"Infogrames","g":"Racing simulation","r":"November 22, 2002","l":"https://en.wikipedia.org/wiki/Grand_Prix_Challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/g98oqt1i1vhnuzppcnrc.jpg","s":"Whip through tight hairpin turns. Overtake competitors with inches to spare. Heat up the brakes after a blazing straightaway run. Experience for yourself the adrenaline rush of F1 racing. It's real F1 racing with all the drivers, cars, teams, sponsors and tracks."},{"t":"Grand Theft Auto III","p":["Windows"],"u":"Rockstar Games","r":"May 21, 2002","l":"https://en.wikipedia.org/wiki/Grand_Theft_Auto_III"},{"t":"Grand Theft Auto: Vice City","p":["PlayStation 2"],"u":"Rockstar Games","r":"October 29, 2002"},{"t":"Grandia II","p":["PlayStation 2","Windows"],"r":"January 28","l":"https://en.wikipedia.org/wiki/Grandia_II"},{"t":"Grandia Xtreme","p":["PlayStation 2"],"r":"September 30","l":"https://en.wikipedia.org/wiki/Grandia_Xtreme"},{"t":"Gravity Games Bike: Street Vert Dirt","p":["PlayStation 2","Xbox"],"r":"June 27"},{"t":"Gremlins: Stripe vs Gizmo","p":["Game Boy Advance"],"r":"November 27","l":"https://en.wikipedia.org/wiki/Gremlins"},{"t":"Gridrunner++","p":["macOS","Windows"],"d":"Llamasoft","u":"Llamasoft","g":"Shoot 'em up","l":"https://en.wikipedia.org/wiki/Gridrunner++","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8ktn.jpg","s":"Gridrunner++ is a retro style shooter game by Jeff Minter."},{"t":"Grom: Terror in Tibet","p":["Windows"],"d":"Rebelmind","u":"CDV Software Entertainment","g":"Action-adventure","r":"November 25, 2002","l":"https://en.wikipedia.org/wiki/Grom:_Terror_in_Tibet","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ov3.jpg","s":"During World War II, Hitler's Third Reich sought out and pilfered art and wealth, hording their stolen booty in secret strongholds. This game takes place during that time. In 1942, special German forces have invaded Tibet and are searching for more to add to their Führer's arsenal - the 12 \"miracle\" weapons of King Arunja in an undiscovered \"Lost City\". One of these weapons, according to legend, could obliterate major cities, wiping them off the face of the earth. The player takes the part of Colonel Grom, a member of the Polish army fighting the Nazis during World War II. Grom is a seasoned and shrewd commander who has his own personal score to settle with the Germans.\n\nGROM: Terror in Tibet is a predominantly role-playing game with elements of stealth and emphasis on tactical combat. The player controls a party of characters, navigating them through towns and other locations in a fairly linear fashion, often engaging in conversations with multiple dialogue choices. Travelling between the various locations is handled by way of a country map. Combat system has similarities to that of Baldur's Gate, with real-time management and the ability to pause in order to issue commands. Unlike in most RPGs, the characters themselves do not level up in this game; their only growing attribute is weapon proficiency, which plays an important role in combat."},{"t":"Guilty Gear X2","p":["Arcade","PlayStation 2"],"d":"Arc System Works","u":"Sammy Studios","g":"Fighting game","r":"May 23, 2002","l":"https://en.wikipedia.org/wiki/Guilty_Gear_X2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaw8s.jpg","s":"Guilty Gear X2, also known as Guilty Gear XX and subtitled The Midnight Carnival in Japan, is a fighting game developed by Arc System Works and published by Sammy Studios. The third installment of the Guilty Gear series, Guilty Gear X2 furthered the plot of the series, as well as introduced new characters and gameplay mechanics. A sequel to Guilty Gear X, it was first announced in January 2002, and was released on May 23, 2002, for the arcades, in Japan. It was later ported to the PlayStation 2 and published in North America and Europe."},{"t":"Gun Metal","p":["Xbox"],"d":"Rage Games","u":"Rage Games, Majesco, Zoo Digital, Strategy First","g":"Shooting, flight simulator","r":"June 28, 2002","l":"https://en.wikipedia.org/wiki/Gun_Metal_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coau8n.jpg","s":"Gun Metal is a futuristic action-packed experience where you take control of the fully transformable prototype combat vehicle known as the Havoc Suit.\n\nThe Havoc Suit, a prototype combat vehicle, remains the only hope to save civilization from a tireless enemy. Standing 10 meters tall, with an arsenal of devastating weaponry and the ability to transform instantly into an agile jet, only this formidable battle machine has the potential to halt the invaders!\n\nUse the Havoc Suit to battle-ground-based enemies, or transform in the blink of an eye into an agile jet and take on aircraft in high-speed dogfights. Either way, get ready for mind-blowing action and out-of-this world graphics.\n\nKey Features:\nFight hordes of enemies through 14 incredible missions\nScorch the earth, crush rocks under foot, fell trees\nTear chunks out of towering buildings and raze entire settlements to the ground!\nTool-up with an extensive armoury of devastating weaponry."},{"t":"Gunbound","p":["Windows"],"d":"Softnyx","u":"GOA, HanGame, Softnyx, Asiasoft","g":"Artillery","r":"May 2002","l":"https://en.wikipedia.org/wiki/Gunbound","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48y9.jpg","s":"GunBound has turn-based artillery gameplay, bearing properties of two-dimensional games and ballistics-simulation games. In GunBound, players are assigned to two opposing teams which take turns firing at each other with vehicles called \"Mobiles\" in GunBound parlance. Each Mobile has three unique weapons, labeled \"1\", \"2\", and \"SS\" (Special Shot).\n\nFactors like terrain condition, wind currents and elemental phenomena force players to continuously change their aim and trajectory power setting while rethinking their strategy at the same time. GunBound also implements a \"delay\" turn system which is influenced by the Mobile, the weapon and/or item a player uses—using items or taking time with actions results in a longer wait before the player's next turn."},{"t":"Gundam: Battle Assault 2","p":["PlayStation"],"d":"Natsume Co., Ltd.","u":"Bandai, D3 Publisher","g":"Fighting, Mecha Sci Fi","r":"July 18, 2002","l":"https://en.wikipedia.org/wiki/Gundam:_Battle_Assault_2"},{"t":"Gungrave","p":["PlayStation 2"],"r":"September 16","l":"https://en.wikipedia.org/wiki/Gungrave"},{"t":"Gunvalkyrie","p":["Xbox"],"d":"Smilebit","u":"Sega","g":"Third-person shooter","r":"March 19, 2002","l":"https://en.wikipedia.org/wiki/Gunvalkyrie","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7jvd.jpg","s":"Gunvalkyrie is an alternate history/science fiction video game developed by Smilebit and published by Sega for the Microsoft Xbox.\n\nOriginally developed for the Sega Dreamcast, its visual style was very similar to the final Xbox version. The Dreamcast version's distinguishing feature was that during the game's development, GunValkyrie utilized a unique control scheme using both a light gun and a controller. This control scheme was dropped when development shifted to the Xbox version.\n\nThe gameplay is very different from most third-person shooters, due to a unique dual analog control scheme, which is the main contributor to the steep learning curve of the game. Players travel to various worlds investigating the disappearance of several colonies, with only giant mutated insect creatures left behind. These insects comprise the bulk of the enemies you face along the way.\n\nPlayers control Kelly or Saburouta with both analog sticks, the left controlling forward/backward movement and turning, while the right aims their weapons, and when clicked, allows quick-turns. Clicking in the left stick while pointing in a direction causes the character to boost. The left trigger is a boost/jump, and when combined with the left analog boost, can be strung together into combos to keep the player off the ground entirely, which is a necessity for some levels. Face buttons are used to select weapons, and the right trigger fires the selected weapon.\n\nThe game comprises ten levels, the story unfolding via text between levels, or the occasional in-game cutscene. At the beginning of most levels, excluding boss battles, you have the choice of picking either Kelly or Saburouta. Kelly's primary weapon is fast but weaker, and she's overall faster and more maneuverable. Saburouta is slower, has more limited maneuverability in the air, and carries a stronger primary weapon, the Matchlock Cannon. Basically the two characters make up the two difficulty settings, with Kelly being the \"Normal\", and Saburouta being the \"Advanced\" setting. The real difference being that Kelly's style allowed several lock-on targets, while Saburouta's weapon splashed and was aimed at specific targets. Because of this, Kelly's gameplay is more frantic and requires less direct focus, while Saburota required specific aiming and direct attacks to be effective. Kelly is also the only character to upgrade her gearskin.\n\nThe artistic style of the game is similar to the steampunk subgenre of fiction, but the game's designers prefer to call it \"elec-punk,\" described as a step even further, with the harnessing of electricity for imaginative new uses. The game's stages are divided into indoor mechanical looking levels, with lots of gears and ornate metalwork, and outdoor stages, set in very organic looking valley's, craters, and other fantastic otherworldly locations."},{"t":"Guruguru Onsen 3","p":[],"l":"https://en.wikipedia.org/wiki/Guruguru_Onsen_3"},{"t":"Haegemonia: Legions of Iron","p":["Windows"],"d":"Digital Reality, Microïds","u":"DreamCatcher Interactive, Wanadoo Edition, Microïds","g":"Real-time strategy","r":"November 12, 2002","l":"https://en.wikipedia.org/wiki/Haegemonia:_Legions_of_Iron","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co298k.jpg","s":"From the makers of the award-winning Imperium Galactica 1 and 2 games, discover a powerful space-opera like RTS game."},{"t":"Hamepane Tokyo Mew Mew","p":["Game Boy Advance"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Hamepane_Tokyo_Mew_Mew","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5uez.jpg","s":"Hamepane Tokyo Mew Mew is a Puzzle game, developed by WinkySoft and published by Takara, which was released in Japan in 2002."},{"t":"Hamepane Tōkyō Myū Myū","p":[],"l":"https://en.wikipedia.org/wiki/Hamepane_T%C5%8Dky%C5%8D_My%C5%AB_My%C5%AB"},{"t":"Hamtaro: Ham-Ham Heartbreak","p":["Game Boy Advance"],"d":"Pax Softnica","u":"Nintendo","g":"Adventure","r":"May 31, 2002","l":"https://en.wikipedia.org/wiki/Hamtaro:_Ham-Ham_Heartbreak","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qao.jpg","s":"All the hamsters are bickering, and there's little wonder why! Spat, a meddling troublemaker, is telling fibs and causing heartache everywhere. It's up to Hamtaro and best-girl Bijou to follow Spat, stop the squabbling, and get everyone back on talking terms again."},{"t":"Hamtaro: Ham-Hams Unite!","p":["Game Boy Color"],"r":"October 28"},{"t":"Hard Hitter Tennis","p":["PlayStation 2"],"d":"Magical Company","u":"Magical Company, Atlus USA, Midas Interactive Entertainment","g":"Sports","r":"February 7, 2002","l":"https://en.wikipedia.org/wiki/Hard_Hitter_Tennis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ehv.jpg","s":"Hard Hitter Tennis challenges you to become the best in the world. Choose one of 14 athletes or make your own, and grow your character's stats over the course of a year. Playing well during the game will increase the mentality meter, giving your player a better chance of making tough shots. The mentality meter can also be expended to make a shot that will be difficult to hit back. Whichever player has won the most money from tournaments by the end of the year is crowned champion."},{"t":"Hard Truck 2: King of the Road","p":["Windows"],"g":"Racing, Simulator","l":"https://en.wikipedia.org/wiki/Hard_Truck_2:_King_of_the_Road","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocb7w.jpg","s":"Hard Truck II: King of the Road is truck simulation and racing game. In this game you can test your driving skills in different European cities. In this game you will race with the other truck driver. But you have also keep in mind the supply of the goods which is the main goal. You have to go through different weather conditions and you have to be skilled enough to keep your truck on the road during all circumstances.\nFrom time to time you are invited to circuit racing with other truck. Where you can earn money in order to open your own company. The cash you earned from the race can be utilized in repairing your trucks or to buy a new one. Some of the money is spent in your truck services and refueling. So you have to go through wisely as the first company to get 51% share in the market will win the game. The ob and police is always behind you and you have to tackle with them as well. The sound track of King of the Road game has been created by Russian heavy metal band called Aria."},{"t":"Hard Truck: 18 Wheels of Steel","p":["Windows"],"d":"SCS Software","u":"ValuSoft","g":"Simulation game","r":"August 16, 2002","l":"https://en.wikipedia.org/wiki/Hard_Truck:_18_Wheels_of_Steel","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7qpy.jpg","s":"Be your own boss behind the wheel of your big rig. Bid on jobs, then hit the road to deliver faster than the competition.\n\nRoad hazards, low fuel and even the police can affect the timeliness and condition of your deliveries - and impact your bottom line. It's all in a day's work when you're driving the big rigs."},{"t":"Harry Potter and the Chamber of Secrets","p":["Windows","PlayStation","PlayStation 2","Xbox","GameCube","Game Boy Color","Game Boy Advance"],"r":"November 15","l":"https://en.wikipedia.org/wiki/Harry_Potter_and_the_Chamber_of_Secrets_(video_game)"},{"t":"Haven: Call of the King","p":["PlayStation 2"],"r":"November 17"},{"t":"He-Man: Power of Grayskull","p":["Game Boy Advance"],"d":"Taniko","u":"TDK Mediactive","g":"Action","r":"October 29, 2002","l":"https://en.wikipedia.org/wiki/He-Man:_Power_of_Grayskull","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9uha.jpg","s":"Eternia was once a place of beauty and safety. Protected by the Masters of the Universe and the Mystic Wall, this sacred land could never be touched by the evil of the outside world. But one dark day Skeletor and his evil warriors were able to breach the Mystic Wall. Their relentless attacks have pushed the Masters of the Universe to their edge-and now, yet another wave of attacks. It's clear only one man can protect this land and keep its people safe - He-Man, the most powerful man in the universe! Can you, as He-Man, push back the evil beasts to the Dark Hemisphere? Test your skills and discover if you are worthy of being He-Man."},{"t":"Headhunter","p":["PlayStation 2"],"r":"May 9","l":"https://en.wikipedia.org/wiki/Headhunter_(video_game)"},{"t":"Heart de Roommate","p":["Windows","macOS","Linux"],"d":"AngelSmile","u":"AngelSmile, G-Collections, Jast USA","g":"Visual novel, eroge","r":"January 24, 2002","l":"https://en.wikipedia.org/wiki/Heart_de_Roommate"},{"t":"Hearts of Iron","p":["Windows"],"d":"Paradox Development Studio","u":"Strategy First, Atari SA, PAN Vision AB, Koch Media, Virtual Programming","g":"Grand strategy","r":"November 27, 2002","l":"https://en.wikipedia.org/wiki/Hearts_of_Iron","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qbj.jpg","s":"Hearts of Iron is the first ever World War II PC game of true Grand Strategic scope. The game map spans the entire world and allows players to take part in any front they choose. You can play any nation in the world, but the game focuses on the epic struggle between the great alliances of the world orders - Fascism, Communism and Democracy."},{"t":"Herdy Gerdy","p":["PlayStation 2"],"r":"March 4","l":"https://en.wikipedia.org/wiki/Herdy_Gerdy"},{"t":"Hero X","p":["Windows"],"d":"Amazing Games","u":"Infogrames","g":"Action role-playing game","r":"June 29, 2002","l":"https://en.wikipedia.org/wiki/Hero_X","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4tgs.jpg","s":"Hero X is an isometric third-person game strongly influenced by the aesthetics and theme of comic books. The objectives of the game are to complete missions in the open free-roaming area around Smalltown. The game's action involves direct combat and the use of 50 superpowers selected by the player, including force fields, freeze rays, mind control and super strength. Players select the appearance of their chosen hero and an initial three powers, with further powers unlocked by completing missions throughout the game."},{"t":"Heroes of Might and Magic IV","p":["Windows","macOS"],"d":"New World Computing","u":"The 3DO Company","g":"Turn-based strategy","r":"March 28, 2002","l":"https://en.wikipedia.org/wiki/Heroes_of_Might_and_Magic_IV","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co218u.jpg","s":"Heroes of Might and Magic IV is a turn-based strategy game developed by Gus Smedstad through New World Computing and published by the 3DO Company for Microsoft Windows-based personal computers in 2002.\nThe fourth installment of the popular Heroes of Might and Magic franchise, it is the sequel to Heroes of Might and Magic III, and was the last to be developed by New World Computing."},{"t":"Hey Arnold! The Movie","p":["Game Boy Advance"],"r":"May 29","l":"https://en.wikipedia.org/wiki/Hey_Arnold!_The_Movie"},{"t":"High Heat Major League Baseball 2003","p":["PlayStation 2","Game Boy Advance"],"r":"February 9","l":"https://en.wikipedia.org/wiki/High_Heat_Major_League_Baseball_2003"},{"t":"Higurashi When They Cry","p":[],"l":"https://en.wikipedia.org/wiki/Higurashi_When_They_Cry"},{"t":"Hitman 2: Silent Assassin","p":["Windows","PlayStation 2","Xbox"],"g":"Action","r":"October 1","l":"https://store.steampowered.com/app/6850","i":"images/steam-6850.jpg","s":"Enter the realm of a retired assassin, forced back into action by treason. You may be a hired killer but you still have a sense of loyalty and justice. Visit the dark recesses of a world corrupted by crime, greed, degradation and dishonor. And a past that catches up with you."},{"t":"Home Run King","p":["GameCube"],"d":"WOW Entertainment","u":"Sega","g":"Sports","r":"March 19, 2002","l":"https://en.wikipedia.org/wiki/Home_Run_King","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6tur.jpg","s":"Home Run King is a baseball game exclusively for the GameCube"},{"t":"Hooligans: Storm Over Europe","p":["Windows"],"d":"Darxabre","u":"Darxabre, Hip Games","g":"Real-time tactics","l":"https://en.wikipedia.org/wiki/Hooligans:_Storm_Over_Europe","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6kej.jpg","s":"A real-time strategy (RTS) game in which you take command of a rowdy gang of football (soccer) enthusiasts, striving to create havoc and disruption within the rival team's fanbase and the surroundings of the football stadium."},{"t":"Hooters Road Trip","p":["PlayStation"],"r":"March 25","l":"https://en.wikipedia.org/wiki/Hooters_Road_Trip"},{"t":"Hot Shots Golf 3","p":["PlayStation 2"],"r":"March 11","l":"https://en.wikipedia.org/wiki/Everybody%27s_Golf_3"},{"t":"Hot Wheels: Velocity X","p":["PlayStation 2"],"r":"November 11"},{"t":"Hotel Giant","p":["Windows"],"d":"Enlight Software","u":"JoWooD Productions","g":"Business simulation game","r":"May 17, 2002","l":"https://en.wikipedia.org/wiki/Hotel_Giant","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co43dc.jpg","s":"Our Hotels. Your Rules. In Hotel Giant, you call the shots as you direct every aspect of hotel operations. You control the construction of your hotel – from site selection to building type – to personalized room features. Build up to 19 different hotel complexes, ranging from romantic get-away hotels to skyscraper business hotels to luxury 5-star hotels with exquisite spa and entertainment facilities.\n\nYou’ll also get the chance to satisfy your inner voyeur by observing your guests’ every move and reacting to their feedback."},{"t":"Hourglass of Summer","p":["Windows","PlayStation 2"],"d":"Princess Soft","u":"Hirameki International","g":"Bishōjo, Visual novel, Dating sim","r":"May 30, 2002","l":"https://en.wikipedia.org/wiki/Hourglass_of_Summer"},{"t":"Hoyle Casino Empire","p":["Windows"],"d":"Sierra Entertainment","u":"Sierra Entertainment","g":"Business simulation game","r":"September 23, 2002","l":"https://en.wikipedia.org/wiki/Hoyle_Casino_Empire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2efr.jpg","s":"The goal of Hoyle Casino Empire is to create a thriving casino. There are two modes in the game; Empire Mode and Sandbox Mode. Empire Mode sends the player to one of eight casinos starting with a small one and working up to the biggest casino. In each casino the player will have specific objectives to meet in a limited time in order turn the casino into a successful place. Not meeting the objectives in time will end the game. Sandbox mode allows the player to build whatever casino desired without any objectives to follow or limited time. In this mode, the player is limited to one kind of casino, but can unlock more upon winning them from the Empire Mode."},{"t":"Hugo: The Evil Mirror","p":["PlayStation","Windows","Game Boy Advance","Game Boy Color","Mobile phone"],"d":"ITE Media","u":"ITE Media, XS Games, Namco","g":"Platform","r":"May 2, 2002","l":"https://en.wikipedia.org/wiki/Hugo:_The_Evil_Mirror","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2tfb.jpg","s":"The evil witch Scylla has trapped Hugo in a mirror, and now it's up to you to rescue him. In Hugo and the Evil Mirror, you must save Hugo in three different worlds, each guarded by dangerous monsters. Use the freeze gun to turn enemies into ice cubes, and then push them over the edge of the levels or combine them with other frozen monsters to gain power-ups."},{"t":"Hunter: The Reckoning","p":["Xbox","GameCube"],"d":"High Voltage Software","u":"Interplay Entertainment","g":"Hack and slash, third-person shooter","r":"May 21, 2002","l":"https://en.wikipedia.org/wiki/Hunter:_The_Reckoning_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5g9b.jpg","s":"Set in White Wolf's World of Darkness, Hunter: The Reckoning lets you take the role of one of four different hunters--Deuce, a biker ex-con; Father Cortez, a prison chaplain; Kassandra, a raver chick; and Samantha, a tough ex-cop. Armed with a variety of fearsome weaponry--ranging from axes to shotguns--you'll battle it out with hordes of supernatural enemies. Intense action combined with multiplayer support brings the true spirit of Hunter: The Reckoning to life."},{"t":"Ice Age","p":["Game Boy Advance"],"d":"Artificial Mind and Movement","u":"Ubi Soft","g":"Platform","r":"March 19, 2002","l":"https://en.wikipedia.org/wiki/Ice_Age_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d1b.jpg","s":"Ice Age makes the jump to the small screen in this Game Boy Advance platformer. Based on events depicted in the motion picture, Ice Age tasks players with guiding both Manny the Mammoth and Sid the Sloth through ten levels of platform-oriented action. Starting out, players control Manny who, along with the human baby Roshan, must navigate a myriad of environments while keeping saber-tooth tigers, hedgehogs, and bees at bay. To do so, Manny is capable of hurling large nuts as makeshift projectiles at any on-screen enemies. Wild animals aren't the only obstacle players will encounter, as they'll need to move a sleeping rhinoceros to advance and inhale skunk fumes to float over dangerous chasms."},{"t":"Icewind Dale II","p":["Windows"],"r":"August 27","l":"https://en.wikipedia.org/wiki/Icewind_Dale_II"},{"t":"IHRA Drag Racing 2","p":["PlayStation 2"],"d":"Bethesda Softworks","u":"Bethesda Softworks","g":"Racing","l":"https://en.wikipedia.org/wiki/IHRA_Drag_Racing_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4zrr.jpg"},{"t":"Incoming Forces","p":["Windows"],"d":"Rage Software","u":"Hip Interactive","g":"Shooter","r":"March 8, 2002","l":"https://en.wikipedia.org/wiki/Incoming_Forces","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ai2.jpg","s":"Prepare for one of the most action packed-shooters in PC gaming history! Every level is full of enemies and targets for you to destroy! You will become a soldier of the alien species and protect your home world from the forces of the Human armada."},{"t":"Industry Giant II","p":["Windows"],"d":"JoWooD Productions","u":"JoWooD Productions","g":"Business simulation","r":"June 28, 2002","l":"https://en.wikipedia.org/wiki/Industry_Giant_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co43k8.jpg","s":"Economic booms, stock market crashes, oil crises, upswings, triumphs... Now you can become the greatest power in industry! Begin in the year 1900 with little money but large ambitions and through skilfull decision-making you can build up an enormous business empire. Make critical decisions which products you should manufacture, where to gather the best raw materials, where to sell them and how to effectively transport them there.\n\nIt's your choice whether you start out as a small-time fruit-growing framer with a little orchard and retire as the owner of the biggest foodstuff empire around, or end up owning a multinational conglomerate with a vast portfolio of products."},{"t":"Inquisition","p":["Windows"],"d":"4X Studios","u":"Wanadoo Edition","g":"Action-adventure","r":"November 29, 2002","l":"https://en.wikipedia.org/wiki/Inquisition_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2tol.jpg","s":"Inquisition is a third-person 3D real time action/adventure game. It offers a blend of action, infiltration and adventure in a medieval universe. Sneaking between homes and past sleeping guards, players will need to keep themselves from being spotted, hopping from ledge to ledge and from roof to roof, picking locks, striking the enemy, gleaning and stealing information without the enemy knowing : these are the kind of actions that will bring players closer to discovering the hiding place of the Templar knights’ treasure. Players are also given different means of exploring and moving around in total secrecy: creeping silently and hiding in shadows. There are riddles closely linked to the scenario which they will need to solve over the course of their adventure: finding and opening passageways, gathering objects and using them wisely."},{"t":"International Superstar Soccer 2","p":["GameCube","Xbox","PlayStation 2"],"d":"Konami","u":"Konami","g":"Sports","r":"March 14, 2002","l":"https://en.wikipedia.org/wiki/International_Superstar_Soccer_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5u3e.jpg","s":"ISS 2 is the latest offering from the creators of Konami's successful International Superstar Soccer series. Its arcade style gameplay is based on realistic and intuitive football action, and ISS 2's fluid and detailed style allows the gamer greater scope for their flexing virtual football talent, with the open gameplay ensuring that no two goals or build-up play will be the same. With more than 50 international teams and a wealth of game modes, ISS 2 is huge. Featuring real player names thanks to the FIFPro licence, the game allows players to step into the boots of their favorite players to tackle, dribble and score their way to glory on every next generation platform."},{"t":"Inuyasha: A Feudal Fairy Tale","p":["PlayStation"],"d":"Dimps","u":"Bandai","g":"Fighting","r":"December 5, 2002","l":"https://en.wikipedia.org/wiki/Inuyasha:_A_Feudal_Fairy_Tale","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coar84.jpg","s":"Inuyasha: A Feudal Fairy Tale is a 2D fighting game starring characters from Rumiko Takahashi's manga and animé series, Inuyasha. The story centers around 15-year old high school student Kagome Higure, who inadvertently slips back in time to feudal Japan, where she becomes embroiled in a quest to locate shards of the Sacred Jewel of the Four Souls. \"Feudal Fairy Tale,\" the game's main mode of play, follows this escapade and requires players to engage in a series of battles and mini-games in order to obtain the coveted shards. Initially, only Kagome and her half-demon companion Inuyasha are playable, but as players journey through the game, acquiring shards, more characters become available.\n\nEach character is able to perform both strong and weak attacks, as well as throws and counter attacks. Players can also execute more powerful combination maneuvers, including special and super attacks, which can only be initiated when the Spiritual meter is filled. Additionally, specific attacks can cause opponents to drop shards that, once claimed, will fill the Spiritual meter more quickly."},{"t":"Iron Storm","p":["Windows"],"d":"4X Studio, Rebellion Developments, Reef Interactive","u":"Wanadoo Edition, Dreamcatcher Interactive, Ubisoft, Reef Interactive","g":"First-person shooter","r":"October 21, 2002","l":"https://en.wikipedia.org/wiki/Iron_Storm_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24o2.jpg","s":"This atrocious war began in August 1914. It is now March 1964 and believe it or not, it is still being waged. Occidental and American troops are fighting against the armies of a latter-day Genghis Khan, who has already put a bloody end to the Bolshevik Revolution. He is planning to create a Russo-Mongol Empire, stretching from the Atlantic to Vladivostok.\n\nWhile some aspects of this world seem to be true to 1914, such as the trenches and bunkers, you will also find that several decades of concerted war effort have led to the development of some very modern types of weapons, transportation and other technology."},{"t":"Island Xtreme Stunts","p":["Game Boy Advance","Windows","PlayStation 2"],"d":"Silicon Dreams Studio","u":"Electronic Arts, Lego Interactive","g":"Action-adventure","r":"November 27, 2002","l":"https://en.wikipedia.org/wiki/Island_Xtreme_Stunts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4fgf.jpg","s":"Island Xtreme Stunts is a mixture of different genres in a single game. The player explores a LEGO-based environment in an open world format: ride a skateboard, drive, fly and pilot a range of vehicles all whilst performing stunts and tricks while taking on the bad guy, Brickster. The player is cast as Pepper Roni, a lead stuntman in a big movie production set on LEGO Island.\n\nEven though the player is free to go wherever he wants, there is a story behind the game divided over 25 missions. All the missions are stunt-based. Running around the world in 3rd-person view, the controls are pretty basic and do not offer the trick combinations of other stunt/trick-based games. It is easy to pick up and play, even for the younger players, without worrying too much about what button combination will do what trick. Instead the player can focus on the missions by only having to complete basic tricks with a few button presses."},{"t":"James Bond 007: Nightfire","p":["GameCube","PlayStation 2","Xbox","Windows"],"d":"Eurocom, Gearbox Software, JV Games","u":"Electronic Arts","g":"First-person shooter","r":"November 19, 2002","l":"https://en.wikipedia.org/wiki/James_Bond_007:_Nightfire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26dt.jpg","s":"007: Nightfire is a first-person shooter featuring the character of the British secret agent James Bond and a sequel to Agent Under Fire. The game marked Pierce Brosnan's fourth appearance as James Bond before the release of his fourth and final Bond film Die Another Day. His likeness was featured in the game, but not his voice, which was provided by Maxwell Caulfield. Overall there are many weapons that the player can carry including grenades of various sorts and other types of explosives. In addition, there are numerous amounts of mounted weapons found throughout the game. As with previous James Bond games, the weapons that appear are based on actual weapons, but with the names changed. Some weapons appear in the console version but not the PC version, and vice-versa."},{"t":"James Cameron's Dark Angel","p":["PlayStation 2"],"r":"November 18","l":"https://en.wikipedia.org/wiki/James_Cameron%27s_Dark_Angel"},{"t":"Jane's Attack Squadron","p":["Windows"],"d":"Looking Glass Studios, Mad Doc Software","u":"Xicat Interactive","g":"Air combat simulation","r":"March 2002","l":"https://en.wikipedia.org/wiki/Jane's_Attack_Squadron"},{"t":"Jazz Jackrabbit","p":["Game Boy Advance"],"d":"Game Titan","u":"Jaleco","g":"Side-scrolling platformer","r":"December 20, 2002","l":"https://en.wikipedia.org/wiki/Jazz_Jackrabbit_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8mo4.jpg","s":"A platformer released for the Game Boy Advance. It is a reboot of the franchise and was developed by Game Titan, rather than Epic Games, the developer of the previous Jazz Jackrabbit games."},{"t":"Jerusalem: The Three Roads to the Holy Land","p":["Windows"],"d":"Arxel Tribe","u":"Cryo Interactive","g":"Adventure","l":"https://en.wikipedia.org/wiki/Jerusalem:_The_Three_Roads_to_the_Holy_Land","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/pi7nrdo3ygltneot1bou.jpg","s":"Jerusalem: The Three Roads to the Holy Land is a 2002 historical adventure game. It is a sequel to the game Pompei: The Legend of Vesuvius. \n \nWhen a Scottish cartographer by the name of Adrien Blake returns from an expedition he discovers that his fiancée, Sophia, has disappeared. He must travel to Jerusalem to search for her. The story unfolds in the year 1552."},{"t":"Jet Set Radio Future","p":["Xbox"],"u":"Sega","r":"February 22, 2002","l":"https://en.wikipedia.org/wiki/Jet_Set_Radio_Future"},{"t":"Jet X2O","p":["PlayStation 2"],"r":"October 28","l":"https://en.wikipedia.org/wiki/Jet_X2O"},{"t":"Jim Henson's Bear in the Big Blue House","p":["Game Boy Color","PlayStation"],"d":"Ubi Studios UK, DC Studios","u":"Ubi Soft","g":"Action, educational","r":"March 21, 2002","l":"https://en.wikipedia.org/wiki/Jim_Henson's_Bear_in_the_Big_Blue_House","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co91rt.jpg","s":"A child-friendly adventure game for Game Boy Color that invites young players to explore the Big Blue House with Bear and friends through simple mini-games and educational activities. With bright sprites, approachable controls, and bite-sized tasks focused on shapes, colors, and memory, it’s designed to teach basic skills while recreating the show’s warm, interactive atmosphere."},{"t":"Jimmy Neutron vs. Jimmy Negatron","p":["Game Boy Advance"],"r":"September 25","l":"https://en.wikipedia.org/wiki/Jimmy_Neutron_vs._Jimmy_Negatron"},{"t":"JumpStart Advanced 1st Grade","p":["Windows","macOS"],"d":"Knowledge Adventure","u":"Knowledge Adventure","g":"Educational","l":"https://en.wikipedia.org/wiki/JumpStart_Advanced_1st_Grade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co52do.jpg","s":"In this game, the player participates in the JumpStartville Scooter Tournament. The player can collect power-ups to add to any of the seven main characters' scooters by playing activities around JumpStartville. Once the player has gathered enough power-ups, they can move to the arena to compete against the other racers."},{"t":"JumpStart Advanced 2nd Grade","p":["Windows","macOS"],"d":"Knowledge Adventure","u":"Knowledge Adventure","g":"Educational","l":"https://en.wikipedia.org/wiki/JumpStart_Advanced_2nd_Grade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co52dn.jpg","s":"JumpStart Advanced 2nd Grade is a game originally released in 2002. It has since then been re-released alongside other various JumpStart Advanced 2nd Grade products."},{"t":"Justice League: Injustice For All","p":["Game Boy Advance"],"r":"November 17"},{"t":"K-1 World Grand Prix","p":["PlayStation 2"],"d":"Konami","u":"Konami","g":"Sports, fighting","r":"November 28, 2002","l":"https://en.wikipedia.org/wiki/K-1_World_Grand_Prix_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/o27orljxtw6yjrh1l6f7.jpg","s":"The new breed of sport fighting games has entered the ring. K-1 World Grand Prix combines the tactical barrage of boxing with the powerful ferocity of no-holds-barred fighting to deliver the ultimate sport fighting experience. With greater depth, more strategy and the fiercest knockouts around, K-1 World Grand Prix puts all other sport fighting games on the canvas! .Over 20 real K-1 fighters, each with signature moves & combos. Body-region-specific damage allows for tactical weakening the opponent. Endless offensive and defensive moves to employ. 7 game modes including Grand Prix, Trial, Revival & Head-to-head."},{"t":"Kaan: Barbarian's Blade","p":["Windows"],"d":"Eko Software","u":"DreamCatcher Interactive","g":"Platform, Adventure","r":"November 1, 2002","l":"https://en.wikipedia.org/wiki/Kaan:_Barbarian's_Blade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4d8r.jpg","s":"Asaquan, the realm of Queen Xithanna, is being attacked by the troops of Tothum Siptet, the evil sorcerer of Syrkonia. As soon as Kaan arrives on the scene, he applies all his fighting energy into attempting to repel the attack. But he is already too late: the town has been pillaged, put to fire and sword by the sorcerer's troops."},{"t":"Kakuto Chojin: Back Alley Brutal","p":["Xbox"],"r":"November 11"},{"t":"Kamaitachi no Yoru 2","p":["PlayStation 2","Mobile phone"],"d":"Chunsoft","u":"Chunsoft, Sega","g":"Visual novel","r":"July 18, 2002","l":"https://en.wikipedia.org/wiki/Kamaitachi_no_Yoru_2"},{"t":"Karnaaj Rally","p":["Game Boy Advance"],"r":"November 21","l":"https://en.wikipedia.org/wiki/Karnaaj_Rally"},{"t":"Kaze no Uta","p":["MS-DOS","Windows"],"d":"Milk Soft","u":"Milk Soft","g":"Visual novel, Eroge","r":"August 23, 2002","l":"https://en.wikipedia.org/wiki/Kaze_no_Uta"},{"t":"Kelly Slater's Pro Surfer","p":["PlayStation 2"],"r":"September 16","l":"https://en.wikipedia.org/wiki/Kelly_Slater%27s_Pro_Surfer"},{"t":"Kikokugai: The Cyber Slayer","p":[],"l":"https://en.wikipedia.org/wiki/Kikokugai:_The_Cyber_Slayer"},{"t":"King's Field: The Ancient City","p":["PlayStation 2"],"r":"March 25"},{"t":"King's Quest II: Romancing the Stones","p":["Windows","macOS"],"d":"AGD Interactive/Himalaya Studios","g":"Adventure","l":"https://en.wikipedia.org/wiki/King's_Quest_II:_Romancing_the_Stones","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4bun.jpg","s":"King's Quest II: Romancing the Stones is a remake of King's Quest II: Romancing the Throne and a follow-up to AGD Interactive's (formerly Tierra Entertainment) earlier remake of the first game. Similar to its predecessor, it has VGA graphics reminiscent of Sierra's adventure games of the early 1990's and a new musical score. The remake retains the general outlines of the original story and the gameplay system, however contains additional locations, expanded dialogue, and new characters. Some of these characters are original, while others are taken from various installments of the series to present a more cohesive view of its overarching story."},{"t":"Kingdom Hearts","p":["PlayStation 2"],"r":"September 17","l":"https://en.wikipedia.org/wiki/Kingdom_Hearts_(video_game)"},{"t":"Kirby: Nightmare in Dream Land","p":["Game Boy Advance"],"g":"Platform, Adventure","l":"https://en.wikipedia.org/wiki/Kirby:_Nightmare_in_Dream_Land","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1wcd.jpg","s":"A remake of the original Kirby's Adventure for the NES."},{"t":"Klonoa 2: Dream Champ Tournament","p":["Game Boy Advance"],"d":"Now Production","u":"Namco, Namco Hometek","g":"Platform","r":"August 6, 2002","l":"https://en.wikipedia.org/wiki/Klonoa_2:_Dream_Champ_Tournament","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3zgr.jpg","s":"Floppy-eared hero Klonoa returns in another fast-paced, colorful side-scrolling adventure for the Game Boy Advance. In his latest challenge, Klonoa must race against time and other dream travelers in the Dream Champ Tournament to collect stars, sun and moon stones to become the ultimate Dream Champion. Combining platform, puzzle and adventure elements, Klonoa 2: Dream Champ Tournament is just the adventure fans of the series have been anticipating. Explore the intricate and puzzle-packed worlds where you’ll meet a wide variety of interesting creatures! Solve Fiendishly-Designed Puzzles\n\n- Use Boxes, Bomb Boxes, Switches, Pressure Switches, Goomis, Springs and Scales in your quest for glory. Hoverboard Races\n- Each world contains a fast-paced thrill ride of gem collecting fun! Master your Skills to Win\n- Klonoa must prove his skills against other dream travelers in the Dream Champ Tournament."},{"t":"Klonoa Beach Volleyball","p":["PlayStation"],"d":"Namco","u":"Namco, Sony Computer Entertainment","g":"Sports","r":"April 25, 2002","l":"https://en.wikipedia.org/wiki/Klonoa_Beach_Volleyball","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ek1.jpg","s":"Klonoa Beach Volleyball is a spin-off of the Klonoa game series. Its release was limited to Japan and Europe only with the characters speaking in English in the latter."},{"t":"Klonoa Heroes: Densetsu no Star Medal","p":["Game Boy Advance"],"d":"Namco","u":"Namco","g":"Action role-playing","r":"December 13, 2002","l":"https://en.wikipedia.org/wiki/Klonoa_Heroes:_Densetsu_no_Star_Medal","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5b66.jpg","s":"This entry in the Klonoa series sees the floppy-eared hero training to become a true hero in a new RPG system.\n\nKlonoa Heroes: Densetsu no Star Medal is a spin-off of the Klonoa franchise, released only in Japan on December 13, 2002. Klonoa Heroes was developed by Namco and published by Namco for the Game Boy Advance. Klonoa Heroes is a twist on the traditional Klonoa games, putting Klonoa in a more action role playing game along the lines of Legend of Zelda or Beyond Oasis. The game does have voice acting, as well. Kumiko Watanabe plays Klonoa, Takahiro Sakurai plays Guntz, Shouzou Iizuke plays Pango, and Yutaka Shimaka plays Garlen.\n\nKlonoa Heroes' gameplay is very similar to the gameplay of The Legend of Zelda. Players can control one of three characters (Klonoa, Guntz, and Pango) in a top-down perspective, hitting enemies with various attacks (Klonoa with the Wind Ring seen in the platforming games, albeit with a few differences). Guntz uses a handgun, while Pango throws bombs. In addition, these characters can collect more weapons as the game progresses. Every enemy in the game is given a color (either blue or red), and the player must attack that enemy with the corresponding attack (as each weapon has a blue and red attack).\n\nKlonoa Heroes also has role playing aspects. Experience points are gathered by picking up Dream Shards after defeating enemies (failure to pick them up results in no experience). Enemies also drop coins, which can be spent on items and weapons. These items can be found in chests scattered throughout the levels, as well. Most items can be used to restore health, but there are various other uses (such as stat benefits). Leveling up also allows the player to distribute points in several different areas (traditional role playing game stats, such as attack, defense, and agility). These changes are not permanent, and can be changed at any time (when not in the middle of a level)."},{"t":"Knight Online","p":["Windows"],"d":"Mgame Corporation, Noahsystem","u":"MGame, eGames, X-legend, NTTGame","g":"Fantasy MMORPG","r":"July 15, 2002","l":"https://en.wikipedia.org/wiki/Knight_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coab5m.jpg","s":"Knight Online is a PvP-centric Massively Multiplayer Online Role Playing Game that has been under continuous development for almost a decade. Two nations: El Morad and Karus - or more colloquially, humans and orcs - are locked in an eternal struggle for dominance of the Adonis Continent. The PvP in Knight Online is fast-paced, action-packed, and oftentimes frantic. Dozens of players can be seen clashing in PvP zones during all hours of the day. With events such as Lunar War and Castle Seige War, the action becomes massive!\n\nWhile PvP may be the beating heart of Knight Online, much of the game is spent embarking on quests, killing monsters, and - of course - collecting loot. The Upgrade System lets players tempt fate in an effort to improve their existing weapons, armor, or accessories (or lose them in the process!). With its unique ability to let players refine their skills and build their characters and equipment, Knight Online is able to entertain and excite its fans even after many years. Pick a side, build up your warrior, and join the fray!"},{"t":"Knights of the Cross","p":["Windows"],"d":"Free Mind","u":"Cenega","g":"Strategy","l":"https://en.wikipedia.org/wiki/Knights_of_the_Cross_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gy3.jpg","s":"Based on the Polish novel by Henryk Sienkiewicz. It's a turn-based strategy game where players take on the role of a knight of either side and must engage in a series of tactical missions, manoeuvring your forces and defeating your enemies in typical fashion.\n\nThere are over 100 battles to take part in, with new units, weapons and upgrades available as you complete each one, while environmental conditions such as rain, snow and storms have an impact on the battles"},{"t":"Knockout Kings 2002","p":["PlayStation 2"],"r":"March 4","l":"https://en.wikipedia.org/wiki/Knockout_Kings_2002"},{"t":"Knockout Kings 2003","p":["GameCube"],"g":"Sport","l":"https://en.wikipedia.org/wiki/Knockout_Kings_2003","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5yoh.jpg","s":"Knockout Kings is a series of boxing video games that were produced by EA Sports for the PlayStation, Nintendo 64, PlayStation 2, Xbox, Game Boy Color and GameCube yearly between 1998 and 2003.\n\nBefore releasing the first Knockout Kings, Electronic Arts released its first 3D boxing game, Foes of Ali, for the 3DO in 1995. While there are a few similarities between the two games, Foes of Ali was developed by a different team, Gray Matter and as such, is not regarded as a true prequel.\n\nThe Knockout Kings game series gives the user a chance to compete against numerous real fighters, such as Muhammad Ali, Eric Esch, Marvin Hagler, Sugar Ray Leonard, Oscar De La Hoya, Larry Holmes, Jake LaMotta, Roberto Durán, Alexis Argüello, and Ray Mancini. The duration of a round can be adjusted to either 90 seconds or 3 minutes. In the game's \"slugfest\" mode, fighters can knock each other out at any given moment of the fight, or suffer 6 or 7 knockdowns and still last for the whole fight. There are several differences between Knockout Kings, Knockout Kings 2000, and Knockout Kings 2001 in particular, the most notable being the graphics.\n\nIn Knockout Kings, the boxer sprites, although distinctive, are not facially representative of their real-life counterparts. Championship bouts can last only up to 10 rounds and not for 12 as in real life or 15 as in the past. In between rounds, all that is seen is a ring-card girl. In Career Mode, a fighter is made to retire right after winning the title and defending it for only the first time. A created boxer can fight in Career Mode and Slugfest Mode, but not in Exhibition mode. Although there is a training mode within Career Mode, it is extremely basic. However, 2 aspects that Knockout Kings has which the sequels lack is that the referee does a mandatory eight-count when a fighter is knocked down whereas in the sequels the referee stops the count immediately after a fighter gets up from a knockdown, and, in Career Mode, the result of a fight is afterwards seen on the screen as front-page newspaper headlines.\n\nIn Knockout Kings 2000 for the PS1, the boxer sprites are for the first time facially representative of their real-life counterparts. Championship bouts can last up to 15 rounds. Sound and Music volume can also be adjusted in Option Mode. In between rounds, you may see either a ring-card girl, a replay of a part of the previous round, or your boxer sitting at his corner together with the statistics so far of the bout. Injury to the face of boxers can also be recognized, as well as his mouth-piece flying out if he is hit by a hard punch. A created boxer in Career Mode can now fight in all Modes. The training mode within Career Mode is more specific. You can now control your boxer while he is training and, in the PS1 version, you can also choose the location of your gym. Each boxer in the PS1 version can also be seen entering into the ring just before the bout takes place. There is also a new Mode where the player can see the statistics and biography of all the real-life boxers in the game, and another Mode in which the player can re-live famous classic bouts. The user-interface and intro-theme of the PS1 version is different to the N64 version and there are also more boxers, while the graphics on each version are similar.\n\nKnockout Kings 2001 contains the same improvements as Knockout Kings 2000 and adds more. Whereas fighters in KO Kings and KO Kings 2000 are either \"boxer\" or \"slugger\" style fighters, the styles of fighters in KO Kings 2001 are either \"boxer\", \"slugger\", \"freestyle\", or \"crab\", and these differences of style are very noticeable during bouts. Commentary in KO Kings 2001 is also far more vocal than its predecessors. During Career Mode, your trainer will occasionally talk and give you advice in between rounds as you progress through the bout. A fighter in Career Mode is made to retire after winning the title and defending it for several times. KO Kings 2001 is also the first game of the series to introduce CPU vs CPU bouts and \"fantasy match-ups\" between famous boxers of different eras, and the first to introduce women's boxing, which is accessible in Exhibition Mode. The PS1 and PS2 versions of Knockout Kings 2001 are virtually identical.\n\nKnockout Kings 2002 changes many concepts of its predecessors, e.g. you have to progress through a number of bouts in order to unlock new fighters.\n\nAfter Knockout Kings 2003, the name of the series was replaced by Fight Night (EA video game series)."},{"t":"Konami Collector's Series: Arcade Advanced","p":["Game Boy Advance"],"d":"Konami","u":"Konami, Majesco, Konami Digital Entertainment","g":"Action, Multicart","r":"March 2002","l":"https://en.wikipedia.org/wiki/Konami_Collector's_Series:_Arcade_Advanced"},{"t":"Koro Koro Puzzle Happy Panechu!","p":["Game Boy Advance"],"d":"Nintendo R&D2, Mobile21","u":"Nintendo","g":"Puzzle game","r":"March 8, 2002","l":"https://en.wikipedia.org/wiki/Koro_Koro_Puzzle_Happy_Panechu!"},{"t":"Kowai Shashin","p":["PlayStation"],"u":"Media Entertainment","g":"Action","r":"July 25, 2002","l":"https://en.wikipedia.org/wiki/Kowai_Shashin"},{"t":"Kururin Paradise","p":["Game Boy Advance"],"d":"Eighting","u":"Nintendo","g":"Puzzle","r":"December 6, 2002","l":"https://en.wikipedia.org/wiki/Kururin_Paradise","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3kcc.jpg","s":"Kururin Paradise revolves around avoiding collisions as the player maneuver a robot through levels. The robot is shaped like a stick, and constantly spins.\n\nThe second in the Kururin franchise, Paradise involves navigating complex levels with a constantly-rotating robot. Spring objects within levels change the direction of rotation when collided with, and an unlockable ability allows for increasing the speed of rotation. The player has three hit points. After three collisions with objects in the level (discounting the aforementioned springs), the level is re-started. Some levels have intermediate points that replenish health fully. However, they do not save progress. If the player loses all of his or her hit points, they still restart the level from the beginning.\n\nAlmost all of the game is in Japanese."},{"t":"La Pucelle: Tactics","p":["PlayStation 2"],"d":"Nippon Ichi Software","u":"Nippon Ichi Software, Mastiff, Koei","g":"Tactical role-playing","r":"January 31, 2002","l":"https://en.wikipedia.org/wiki/La_Pucelle:_Tactics","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobsv3.jpg","s":"Prier and her brother, Culotte, are novices in the demon-hunting organization La Pucelle. They've just passed their final exams and are ready to do real work fighting demons and zombies, but quickly find themselves embroiled in a series of plots orchestrated by a rival church with dark intentions. The gameplay is played on a tactical map, as teams of up to six characters work to clear boards of enemies and dark energy. The unique \"purify\" command allows players to recruit monsters to their team and execute complex \"miracle\" energy attacks.\n\nThe game was ported to the PlayStation Portable in Japan on November 26, 2009, as La Pucelle Ragnarok."},{"t":"Largo Winch: Empire Under Threat","p":["GameCube","Xbox","PlayStation 2","Windows"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Largo_Winch:_Empire_Under_Threat","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6tx8.jpg","s":"Abandoned at birth, an orphan for the first few years of his life. That's how it all began with Largo Winch. Based off the comic series of the same name that's sold in excess of 2.3 million copies, Largo Winch follows Largo Winch, a 26-year-old who, after his adopted father dies, inherits a fortune that surpasses anything seen before. After falling through the cracks of the corporate world Largo finds himself in a place with more evil and corruption than he ever suspected to find."},{"t":"Laser Squad Nemesis","p":["Windows"],"d":"Codo Technologies","u":"Codo Technologies, Just Play, Got Game, Merscom","g":"Turn-based tactics","r":"February 1, 2002","l":"https://en.wikipedia.org/wiki/Laser_Squad_Nemesis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coauvy.jpg","s":"A turn-based strategy game, and sequel to the original 1988 Laser Squad."},{"t":"Law & Order: Dead on the Money","p":["Windows"],"d":"Legacy Interactive","u":"Legacy Interactive, The Adventure Company, Aspyr","g":"Adventure","r":"September 24, 2002","l":"https://en.wikipedia.org/wiki/Law_&_Order:_Dead_on_the_Money","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/fxfozpdlvettmk1cgrb3.jpg","s":"Law & Order: Dead on the Money is an adventure game based on the popular television show of the same name. The game is split into two segments, field work and courtroom drama. The actors lend their voices to the game."},{"t":"Legaia 2: Duel Saga","p":["PlayStation 2"],"r":"October 1"},{"t":"Legends of Wrestling II","p":["Game Boy Advance","PlayStation 2"],"r":"November 25","l":"https://en.wikipedia.org/wiki/Legends_of_Wrestling_II"},{"t":"Legion","p":["Windows"],"d":"Slitherine Software, Paradox Interactive","u":"Strategy First, Koch Media, Virtual Programming, Freeverse Inc.","g":"Computer wargame","r":"June 4, 2002","l":"https://en.wikipedia.org/wiki/Legion_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qjy.jpg","s":"Legion is a game of conquest, battle, diplomacy and economics. As ruler of your own nation, you will strive to outmaneuver, out-fight, out-talk and out-produce up to 20 enemies in an intense struggle to rule the boot of Italy, Britannia or Gaul.\n\nGrow your cities by collecting resources such as wood and ore to increase your armies in numbers and types like building a Fletcher provides archers to your troops. Once you amass your troops you can declare war on your neighbors and proceed to capture cities to claim as your own. Combat is purely tactical in the sense you only select the type of troops, how many, in what formation and how to attack (hold for a few seconds then advance, advance for a little then hold, etc.). Once the battle begins you have no control of your armies. Combat is not the only option as you can form alliances with other nations and offer peace to a nation at war with you. Once you have conquered 40% of the map and it is at least 25% bigger than the next largest nation you are victorious.\n\nLegion is a single player game only. Some of the unique features include: historical accuracy in maps, uniforms and weapons that reflect the country you play in and large numbers of AI opponents with their own strengths and weaknesses."},{"t":"Legion: The Legend of Excalibur","p":["PlayStation 2"],"r":"June 18"},{"t":"Lego Soccer Mania","p":["PlayStation 2","Game Boy Advance"],"r":"June 18","l":"https://en.wikipedia.org/wiki/Lego_Soccer_Mania"},{"t":"Lemonade Tycoon","p":["Windows","Mobile phone","Windows Mobile","Browser"],"d":"Hexacto, Jamdat","u":"Airborne, MacPlay, EA Mobile, Broderbund","g":"Business simulation game","r":"May 2002","l":"https://en.wikipedia.org/wiki/Lemonade_Tycoon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2n39.jpg","s":"Lemonade Tycoon, first released as Lemonade Inc., is a Shockwave-based game. A free, limited version is available for online play at many sites or the full version with no time restrictions can be purchased online. The goal of Lemonade Tycoon is to sell lemonade for profit.\n\nWhile selling lemonade, players must look over many aspects of their business. Players decide on a recipe, set prices, and sell lemonade in a variety of locations. The game includes changing weather and news, which the player must compensate for. To overcome some factors, such as long lines and stock, players can buy upgrades. The packaged version included versions for PC, Mobile Phones, Windows Mobile Professional devices, and Palm devices. Lemonade Tycoon employs a concept called \"Game-On\" which allows users to transfer game saves from a Windows PC to a Palm handheld or Windows Mobile Professional device and back again to continue.\n\nWhile Lemonade Tycoon is compatible with multiple platforms, the game differs slightly on each. The Windows version allows more details and info because of a larger screen. Locations had a much bigger view and other versions had to deal with a smaller screen. They did not include as much information as the PC. Areas would be cut down so only a portion could be seen. Each platform, however, is not limited in usability and functionality. Lemonade Tycoon 2: New York Edition is also available on Mac OS X, published by MacPlay.\n\nThe last update (1.1.9) was called Lemonade Tycoon Deluxe because it included some new levels and a slightly better UI. In 2009 Electronic Arts published an iPhone version of Lemonade Tycoon.\n\nGAMEPLAY:\n\nGame Modes\nLemonade Tycoon includes three game modes; Career, Challenge and Champion. Career mode lets the player have a stand for as long as they want. Challenge mode had a 30-day limit to see how fast your stand can grow within the period of time.\n\nStocks/Supplies\nIn order to be able to sell lemonade, players have to buy supplies, which include ice, lemons, sugar, and cups.\n\nSales and Advertisement\nThe player has the option to advertise in Lemonade Tycoon. Every day, the player can pay an advertising fee with different choices in advertising being available. Advertising increases the number of potential customers.\n\nUpgrades\nLemonade Tycoon features many upgrades that are available at different prices. Some reduce wait times, some improve visibility, some make ice, etc. Stand upgrades allow more storage and customer capacity. There are also employees, a cashier, and a clown, which charge daily for reducing wait times and increasing patience, respectively.\n\nLocations\nThere are five different locations where one can move your stand. Some places are more popular than others. Each location has a different rent. Each location has satisfaction and popularity. Popularity changes as the player's stand gets more popular. Good satisfaction and advertising bring more customers. Satisfaction ensures that customers will come back to the stand. If there are short lines, there are good prices, the player serves all customers rather than them leaving, and the player has a good recipe, the player's customer satisfaction will go up. With the increase of satisfaction, customers will come back to a player's stand. Satisfaction and popularity are location based. They do not travel with you as you move from location to location.\n\nGame Factors\nThere are many News Headlines that change how well lemonade is sold. Some headlines can improve your business and some that can hurt your business. Headlines change every game day and can sometimes only affect a single location. Weather affects how well lemonade is sold as well. Warm and hot days bring more customers to stand than on cold, rainy days. The weather changes each day and does not seem to follow predictable patterns.\n\nLemonade Stock Exchange (LSX)\nThe Lemonade Stock Exchange was an online feature that let one see how one's stand compared to others.\n\nRECEPTION:\n\nAwards\nBest Pocket PC Strategy Game (2002 Pocket PC Magazine's Best Products Awards)\nApplied uses\nLearning Planet, an educational website, created the original version of the game for teaching economics and resource management for its students. The LearningPlanet.com version of Lemonade Tycoon is visually different but functionally identical to the other iterations of the game."},{"t":"Lethal Skies Elite Pilot: Team SW","p":["PlayStation 2"],"r":"May 31"},{"t":"Lilo & Stitch Pinball","p":["Windows"],"r":"October 8","l":"https://en.wikipedia.org/wiki/Lilo_%26_Stitch_(franchise)#Video_games"},{"t":"Lilo & Stitch: Trouble in Paradise","p":["Windows"],"r":"June 14","l":"https://en.wikipedia.org/wiki/Lilo_%26_Stitch_(franchise)#Video_games"},{"t":"Lime-iro Senkitan","p":[],"l":"https://en.wikipedia.org/wiki/Lime-iro_Senkitan"},{"t":"Links 2003","p":["Windows"],"d":"Microsoft","u":"Microsoft Game Studios","g":"Sports","r":"September 19, 2002","l":"https://en.wikipedia.org/wiki/Links_2003","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8hzl.jpg","s":"The newest version for the Links golf series featuring new swing types like the real time swing, ultimate realistic graphics, career play playing with real golf players or created ones, a strong multiplayer community increases the online play experience and a practice facility for the new players."},{"t":"Live for Speed","p":["Windows"],"d":"Scawen Roberts, Eric Bailey and Victor van Vlaardingen","u":"Scawen Roberts, Eric Bailey and Victor van Vlaardingen","g":"Racing simulation","r":"August 18, 2002","l":"https://en.wikipedia.org/wiki/Live_for_Speed","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2f99.jpg","s":"Live for Speed (LFS) is a racing simulator developed by a three-person team comprising Scawen Roberts, Eric Bailey, and Victor van Vlaardingen. The main focus is to provide a realistic racing experience for the online multiplayer game and to allow single player races against AI cars."},{"t":"Looney Tunes: Space Race","p":["PlayStation 2"],"r":"May 27"},{"t":"Loons: The Fight for Fame","p":["Xbox"],"d":"Warthog Games","u":"Infogrames","g":"Fighting","r":"September 24, 2002","l":"https://en.wikipedia.org/wiki/Loons:_The_Fight_for_Fame","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5rcn.jpg","s":"Every once in awhile a game comes along that whether you love or hate it ? you'll love something about it. Loons: The Fight For Fame is one of those games. Coming from the fine folks as Infogrames, Loons: The Fight For Fame lets you play as one of the classic characters from Warner Brothers as they battle for the spotlight. If you love the franchise you'll enjoy playing as your favorite Looney Tune and, if you don't, you're sure to get a kick out of killing them hundreds of times over. The game makes use of the increasingly popular cell-shade animation in addition to multiplayer modes supporting 1-4 players."},{"t":"Lost Kingdoms","p":["GameCube"],"r":"May 27","l":"https://en.wikipedia.org/wiki/Lost_Kingdoms"},{"t":"Lowrider","p":["PlayStation 2"],"d":"Pacific Century Cyber Works","u":"Pacific Century Cyber Works, Jaleco Entertainment","g":"Music video game","r":"December 19, 2002","l":"https://en.wikipedia.org/wiki/Lowrider_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6poe.jpg"},{"t":"Lufia: The Ruins of Lore","p":["Game Boy Advance"],"d":"Atelier Double","u":"Taito, Atlus","g":"Role-playing video game","r":"March 8, 2002","l":"https://en.wikipedia.org/wiki/Lufia:_The_Ruins_of_Lore","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49os.jpg","s":"This exciting new chapter in the Lufia saga follows the adventures of Eldin, Torma, and Rami, a group of friends and would-be hunters as they set out in search of treasure, only to discover that fate has much more in store for them! Will they be able to solve the mysteries of the ancient ruins and stop the power-hungry leader Ragule from resurrecting the ancient beast, or will Ragules ambitions be realized at the expense of mankind? Prepare for the Adventure of a Lifetime!"},{"t":"Lunar Legend","p":["Game Boy Advance"],"r":"December 10","l":"https://en.wikipedia.org/wiki/Lunar_Legend"},{"t":"Lupin the 3rd: Treasure of the Sorcerer King","p":["PlayStation 2"],"d":"Banpresto","u":"Banpresto, Bandai, 505 Games","g":"Action, Stealth","r":"November 28, 2002","l":"https://en.wikipedia.org/wiki/Lupin_the_3rd:_Treasure_of_the_Sorcerer_King","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1owp.jpg","s":"Treasure of the Sorcerer King is a stealth action game putting players in the role of anime legend Lupin the 3rd. Together with Jigen and Goemon, Lupin seeks to steal valuable treasures out from under Inspector Zenigata's nose. Players have access to Lupin's wide array of gadgets and disguises, which allow him to pass by guards unnoticed or to get close enough to pick their pockets. \n \nAs a stealth game, Lupin the 3rd: Treasure of the Sorcerer King plays like an arcade answer to Metal Gear Solid or Splinter Cell. The game also has puzzles in the classic Resident Evil mode. Lupin plays out from a third-person perspective with a first-person free look option."},{"t":"Lux","p":["Windows","Linux","macOS"],"d":"Sillysoft Games","u":"Sillysoft Games","g":"Strategy","r":"November 25, 2002","l":"https://en.wikipedia.org/wiki/Lux_(video_game)"},{"t":"Mad Maestro!","p":["PlayStation 2"],"r":"March 12","l":"https://en.wikipedia.org/wiki/Mad_Maestro!"},{"t":"Madden NFL 2003","p":["PlayStation 2","GameCube","Xbox","Windows"],"u":"EA Sports","r":"August 12, 2002","l":"https://en.wikipedia.org/wiki/Madden_NFL_2003"},{"t":"Mafia","p":["Windows"],"u":"Gathering of Developers","r":"August 27, 2002","l":"https://en.wikipedia.org/wiki/Mafia_(video_game)"},{"t":"Mafia: The City of Lost Heaven","p":["Windows"],"r":"August 28"},{"t":"Magic: The Gathering Online","p":["Windows"],"d":"Leaping Lizard Software, Wizards of the Coast, Daybreak Game Company","u":"Wizards of the Coast","g":"Digital collectible card game","r":"June 2002","l":"https://en.wikipedia.org/wiki/Magic:_The_Gathering_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaokw.jpg","s":"Magic: The Gathering Online is a video game adaptation of Magic: The Gathering, utilizing the concept of a virtual economy to preserve the collectible aspect of the card game. It supports a variety of game formats in casual and competitive modes and almost all tournament-legal cards are available."},{"t":"Mahjong Fight Club","p":["Arcade"],"d":"Konami","u":"Konami, Konami Digital Entertainment","g":"Mahjong video game","r":"March 2002","l":"https://en.wikipedia.org/wiki/Mahjong_Fight_Club","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob2rk.jpg","s":"Mahjong Fight Club is a series of Mahjong Games developed by Konami primarily for Arcade machines."},{"t":"Mall Tycoon","p":["Windows"],"d":"Holistic Design","u":"Take-Two Interactive","g":"Business simulation","r":"February 6, 2002","l":"https://en.wikipedia.org/wiki/Mall_Tycoon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co281y.jpg","s":"Mall Tycoon is a business simulation game, released in 2002 for Windows 95/98/ME. It was developed by Holistic Designs and published by Take-Two Interactive.\n\nThe game begins as an empty plot of land upon which the player develops his or her mall. Players can build shops, customize decorations, organize special events such as fashion shows, and manage mall employees. It is important for the player to work out what is profitable and what is not to ensure the survival of the fledgling mall. The mall may become overrun with zombies or aliens which can be eradicated when the player calls upon the Men in Black."},{"t":"Mambo a Go Go","p":[],"l":"https://en.wikipedia.org/wiki/Mambo_a_Go_Go"},{"t":"Marble Blast","p":["Xbox","Windows","macOS","Linux"],"d":"GarageGames, Monster Studios","u":"GarageGames, Monster Studios, eGames","g":"Puzzle-platformer","r":"December 13, 2002","l":"https://en.wikipedia.org/wiki/Marble_Blast","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5aze.jpg"},{"t":"Mario Party 4","p":["GameCube"],"r":"October 21","l":"https://en.wikipedia.org/wiki/Mario_Party_4"},{"t":"Marvel vs. Capcom 2","p":["PlayStation 2"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Marvel_vs._Capcom_2"},{"t":"Mary-Kate and Ashley: Sweet 16 – Licensed to Drive","p":["Game Boy Advance","GameCube","PlayStation 2"],"d":"n-Space, Powerhead Games","u":"Acclaim Entertainment","g":"Party","r":"October 2002","l":"https://en.wikipedia.org/wiki/Mary-Kate_and_Ashley:_Sweet_16_%E2%80%93_Licensed_to_Drive"},{"t":"Mat Hoffman's Pro BMX 2","p":["PlayStation 2"],"r":"August 12","l":"https://en.wikipedia.org/wiki/Mat_Hoffman%27s_Pro_BMX_2"},{"t":"Matt Hayes' Fishing","p":["Windows"],"d":"Electronic Arts Seattle","u":"Electronic Arts","g":"Fishing","l":"https://en.wikipedia.org/wiki/Matt_Hayes'_Fishing"},{"t":"Maximo: Ghosts to Glory","p":["PlayStation 2"],"r":"February 11"},{"t":"Maximum Chase","p":["Xbox"],"d":"Genki","u":"Microsoft Game Studios, Majesco","g":"Action, vehicular combat","r":"September 26, 2002","l":"https://en.wikipedia.org/wiki/Maximum_Chase","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6pxp.jpg","s":"An action game with alternating driving and shooting levels."},{"t":"MechAssault","p":["Xbox"],"r":"November 11","l":"https://en.wikipedia.org/wiki/MechAssault"},{"t":"MechWarrior 4: Mercenaries","p":["Windows"],"d":"Cyberlore, FASA Studio, Studio MekTek","u":"Microsoft Game Studios, Studio MekTek","g":"Vehicle simulation","r":"November 8, 2002","l":"https://en.wikipedia.org/wiki/MechWarrior_4:_Mercenaries","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co23rv.jpg","s":"The sequel to Mechwarrior 4: Vengeance. When you're a 'Mech Mercenary, you call the shots. You don't fight for honor - you fight for cold hard cash, a fierce reputation, and the heart-pounding thrill of the kill. Your allegiance goes to the highest bidder. You answer only to the call of fortune. Your fate is in your hands alone. Select from 4 of the most notorious mercenary units, Kell Hounds, Wolf's Dragoons, Northwind Highlanders, and Gray Death Legion, to alter your missions, with different outcomes based on your victories. Choose from over 35 different 'Mechs, including 10 new ones. And for the first time ever, your secondary lance allows you to muster 8 'Mechs into battle simultaneously. Or make a killing in the infamous Solaris VII arenas, where fighting dirty can make you filthy rich. Includes 'Mechs from the Black Knight expansion for Mechwarrior 4, and is fully compatible with Mechwarrior 4 'Mech Packs. Fight for fame. Fight for fortune. Fight as a Mech Mercenary!"},{"t":"Medabots AX: Metabee and Rokusho","p":["Game Boy Advance"],"d":"Natsume Co., Ltd.","u":"Natsume Inc.","g":"Fighting","r":"June 25, 2002","l":"https://en.wikipedia.org/wiki/Medabots_AX:_Metabee_and_Rokusho"},{"t":"Medabots: Metabee and Rokusho","p":["Game Boy Advance"],"d":"Natsume Co., Ltd.","u":"Natsume Co., Ltd., Natsume Inc., Rocket Company","g":"Role-playing","r":"November 22, 2002","l":"https://en.wikipedia.org/wiki/Medabots:_Metabee_and_Rokusho"},{"t":"Medal of Honor: Allied Assault","p":["Windows"],"u":"Electronic Arts","r":"January 22, 2002"},{"t":"Medal of Honor: Frontline","p":["PlayStation 2","Xbox","GameCube"],"u":"Electronic Arts","r":"May 29, 2002"},{"t":"Medieval: Total War","p":["Windows"],"u":"Activision","r":"August 19, 2002"},{"t":"Mega Man Battle Network 2","p":["Game Boy Advance"],"r":"June 12","l":"https://en.wikipedia.org/wiki/Mega_Man_Battle_Network_2"},{"t":"Mega Man Zero","p":["Game Boy Advance"],"r":"September 10","l":"https://en.wikipedia.org/wiki/Mega_Man_Zero_(video_game)"},{"t":"MegaRace 3","p":["Windows","PlayStation 2"],"d":"Cryo Interactive","u":"Cryo Interactive, DreamCatcher Interactive","g":"Racing, Vehicular combat","r":"January 9, 2002","l":"https://en.wikipedia.org/wiki/MegaRace_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3nsc.jpg","s":"Forget about car races. Now, encouraged by a cheering crowd and the wild commentaries of Lance Boyle, you will be piloting vessels specially conceived for speed and combat, in environments that change with each race. Instead of a being given a low-powered shotgun, the player is provided with a lean machine built for speed and war at their fingertips..\nIn a totally wild virtual universe, the hallucinogenic projection of what TV will be showing in the future, it's a unique game that re-creates both a spectacular race, and a great first person shooter. Cynical presenter Lance Boyle is at the helm of sending out brave drivers in a daredevil challenges. All the ships are modular and according to your results, you will be able to personalise them. Different modules are available to improve the engine characteristics, including the battle armour and the weapons.\nFasten your seat belts..."},{"t":"Men in Black II: Alien Escape","p":["PlayStation 2"],"r":"June 27"},{"t":"Metal Dungeon","p":["Xbox"],"d":"Panther Software","u":"Panther Software, Xicat Interactive","g":"Role-playing video game","r":"February 28, 2002","l":"https://en.wikipedia.org/wiki/Metal_Dungeon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9u5h.jpg","s":"Metal Dungeon (メタルダンジョン?) is a turn-based role-playing video game developed by Panther Software for Microsoft's Xbox game system.\n\nThe game takes place in a fictional alternate reality where countries have access to highly advanced magitechnology. In the process of creating monsters with this technology using an ancient creature named \"The Gods of Magic\"; it broke free of its bonds and took control of the secret facility and proceeded to slay all of the research team and arm the compounds defenses. The player is a commander in charge of the Cyborg Enforcer Teams sent into the dungeon to reclaim it. The game featured 100 levels of randomly generated maps, the first ten being the games main story mode. The other 90 were extended play for players wanting to continue playing with their strong characters.\n\nGame play[edit]\nAs the game starts, you create a team of Enforcers for your expeditions into the dungeon, with the option to create over 40 total. When creating your characters you are given the ability to alter height, sex, ethnicity, weight and hair style as well as given a choice between the Fencer, Caster, Analyzer, Striker, or Broader classes; Each falling into a Dungeons and Dragons styled role. Several Advanced classes were available by finding Class Chips in the dungeon and applying them to your characters. Once inside the dungeon, the players team must move around, find monsters and equipment while leveling up. A major point unsaid in game is that you are not expected to be able to beat a level's boss on the first time entering the level; as you could only allocate level up points while out of the dungeon.\n\nDungeons were randomly generated, most adhering to a typical design that made the map seem less random then it was. Each level has a control room that could possibly be locked, holding a boss monster that must be defeated to win the level and unlock the next one.\n\nFencer Fighter class that could use Hammers or Swords and had the rare chance of performing a move like a Final Fantasy \"Limit Break\" that would damage all enemies at once.\n\nAnalyzer Ranged class. Without an Analyzer in the party, the player is unable to know how much health enemies have and their current HP amount. Analyzers used firearms ranging from laser beams, to machine guns, to rocket launchers that all shared the same in game model.\n\nCaster Basic Spell Caster that could be wired with a variety of Spell Chips either bought from the in-game shop or found in the dungeon. Each spell had a number of charges that had to be refilled by visiting the surface. Casters automatically blocked until the player told them what spell to use.\n\nBroader The Jack-Of-All-Trades class that had a flat rate for all skill gains at the expense of leveling up extremely slowly and was reserved for advanced players that foresaw spending a large time grinding.\n\nStriker A barbarian class that used combat gloves as their weapon. Each strike had a rare chance of instantly killing a non-boss enemy.\n\nReception[edit]\nMetal Dungeon was rated very poorly for its simple game play, transparent story, and character creation system. The game's setting turned it into a cult classic near instantly for its magic-punk stylized world. The only two male African American skins available looked exactly like"},{"t":"Metal Gear Solid 2: Substance","p":["Xbox"],"r":"November 4"},{"t":"Metal Slug 4","p":["Arcade","Windows","Neo Geo AES"],"d":"Mega Enterprise, Noise Factory, SNK Playmore","u":"Playmore, MEGA, BrezzaSoft, Sun Amusement","g":"Run and gun","r":"March 27, 2002","l":"https://en.wikipedia.org/wiki/Metal_Slug_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ox7.jpg","s":"One year after the events of Metal Slug 3, the world is trembling under the new threat of a mysterious but deadly cyber virus that threatens to attack and destroy any nation's military computer system. With Tarma and Eri unable to help due to their own assignments in the matter, Marco and Fio are called in to investigate the situation and are joined by two newcomers, Nadia and Trevor. In their investigation, the group discovers that a terrorist organization known as Amadeus is behind the nefarious plot and that they head into battle against Amadeus' forces, hoping to destroy the cyber virus before it gets the chance to wipe out the entire world's military computer system"},{"t":"Metal Wolf","p":["Dreamcast"],"g":"Adventure, Visual Novel","l":"https://en.wikipedia.org/wiki/Metal_Wolf","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co74d0.jpg","s":"Metal Wolf is an Adventure game, developed and published by Princess Soft, which was released in Japan in 2002."},{"t":"Metroid Fusion","p":["Game Boy Advance"],"u":"Nintendo","r":"November 18, 2002","l":"https://en.wikipedia.org/wiki/Metroid_Fusion"},{"t":"Metroid Prime","p":["GameCube"],"u":"Nintendo","r":"November 17, 2002","l":"https://en.wikipedia.org/wiki/Metroid_Prime"},{"t":"Michael Schumacher Racing World Kart 2002","p":["Windows","PlayStation"],"d":"Radon Labs","u":"JoWooD Productions","g":"Racing","r":"June 28, 2002","l":"https://en.wikipedia.org/wiki/Michael_Schumacher_Racing_World_Kart_2002","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2io9.jpg","s":"Choose your racing outfit, the color of your Kart, your driver's name and more. Customize the appearance of the upcoming Number One Kart Driver. Learn to drive a Kart and follow the footsteps of the incredibly famous Michael Schumacher. Advance through the different race classes and difficulty levels and win the worldwide championship in the Internet, involving players from all over the World."},{"t":"Micro Commandos","p":["Windows"],"d":"Monte Cristo","u":"Monte Cristo, Strategy First","g":"Real-time strategy","r":"June 28, 2002","l":"https://en.wikipedia.org/wiki/Micro_Commandos","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2iob.jpg","s":"Micro Commandos is a real time strategy game where you control tiny aliens from another planet look for a so called \"Ultimate Weapon\". Lead your aliens through 14 missions in the world of the big people. Explore unusual settings like a museum, subway, pizzeria....Collect resourse's of food and material to feed and construct vehicles and buildings for your aliens. Fight off another alien race looking for the Ultimate Weapon as well as bugs hamsters and the family cat."},{"t":"Might and Magic IX","p":["Windows"],"d":"New World Computing","u":"The 3DO Company","g":"Role-playing","r":"March 28, 2002","l":"https://en.wikipedia.org/wiki/Might_and_Magic_IX","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21cn.jpg","s":"This episode in the fantasy Might & Magic series built around a new LithTech-powered, 3D game engine. Improvements include overland maps, branching conversations, a new class system, more flexible spell casting, and twenty-three unique skills. The adventure begins with a player's adventure party voyages from Cheh'dian to Mendossus to gather fresh supplies. The boat they are traveling on crashes into the Isle of Ashes in the middle of the Verhoffin Sea. You and the rest of the survivors are scattered amongst the wreckage. Once you have re-assembled what is left of your team your fate soon unravels and you must reunite the 6 clans of the Cheh'dian against invading hordes from the west. Ten continents and forty dungeons must be explored."},{"t":"Mike Tyson Heavyweight Boxing","p":["PlayStation 2"],"r":"June 23","l":"https://en.wikipedia.org/wiki/Mike_Tyson_Heavyweight_Boxing"},{"t":"Miniconomy","p":[],"l":"https://en.wikipedia.org/wiki/Miniconomy"},{"t":"Minority Report: Everybody Runs","p":["GameCube","PlayStation 2","Xbox"],"r":"November 19"},{"t":"Mister Mosquito","p":["PlayStation 2"],"r":"March 12","l":"https://en.wikipedia.org/wiki/Mister_Mosquito"},{"t":"MLB 2003","p":["PlayStation"],"d":"989 Sports","u":"Sony Computer Entertainment America","g":"Sports","r":"June 18, 2002","l":"https://en.wikipedia.org/wiki/MLB_2003","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/rgljnu1exsxvjaotfi2q.jpg","s":"The MLB (Year#) series, is a series of Major League Baseball video games by Sony Computer Entertainment published under their 989 Sports label. The series was originally developed by Sony Interactive Studios America, who later became 989 Studios until eventually merging into Sony Computer Entertainment America. Following the merge the games were released under the 989 Sports brand up until 2006. Following that, MLB games from SCEA were released by SCEA San Diego under the MLB: The Show series."},{"t":"MLB Slugfest 20-03","p":["PlayStation 2"],"r":"June 23","l":"https://en.wikipedia.org/wiki/MLB_Slugfest_20-03"},{"t":"Mobile Forces","p":["Windows"],"d":"Rage Games","u":"Majesco, Sold Out software","g":"First-person shooter","r":"May 31, 2002","l":"https://en.wikipedia.org/wiki/Mobile_Forces","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3jid.jpg","s":"Mobile Forces is a first-person shooter computer game developed by Rage Software using the first generation of the Unreal Engine and published by Majesco . It is possible to play single player and multiplayer (via LAN or via Internet).\n\nThe game features eight different game modes, all are team based except Deathmatch: Team Deathmatch, Captains, Capture the Flag, Holdout (also known as Domination), Detonation, Safecracker and Trailer (custom game modes are available for a download at various sites). The game is notable for its reasonably successful inclusion of vehicles integrated with standard First Person Shooter gameplay, a rarity when the game was released."},{"t":"Mobile Suit Gundam: Lost War Chronicles","p":["PlayStation 2"],"l":"https://en.wikipedia.org/wiki/Mobile_Suit_Gundam:_Lost_War_Chronicles","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9dbp.jpg","s":"A side-story based on Mobile Suit Gundam. It follows a team of grunts fighting during the iconic One Year War."},{"t":"Mobile Suit Gundam: Zeonic Front","p":["PlayStation 2"],"r":"January 15"},{"t":"Monster Force","p":["Game Boy Advance"],"r":"August 22","l":"https://en.wikipedia.org/wiki/Monster_Force_(video_game)"},{"t":"Monster Rancher Advance 2","p":["Game Boy Advance"],"d":"Tecmo","u":"Tecmo","g":"Life simulation","r":"October 25, 2002","l":"https://en.wikipedia.org/wiki/Monster_Rancher_Advance_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48w2.jpg","s":"Monster Rancher Advance 2 lets players create, train, and fight with monsters of their own choosing. Monsters are generated by inputting key phrases to create different monsters. Each phrase entered will create a unique monster, which will always appear when that specific phrase is entered. Players can experiment with many different phrases for unexpected results. Two separate monsters can also be combined with special items to form an entirely new monster. Certain combinations will lead to hidden, rare monsters which can not be obtained through the normal monster generation process.\n\nThe Coaching System from Monster Rancher Advance has been dramatically improved for added depth in the sequel. Depending on the monster type, certain coaches will offer unique training sessions which other monster coaches will not be able to provide. These special training sessions can be very difficult and dangerous, yet have potential to yield major results. A monster's charisma and skills will also be crucial factors in deciding whether it is suitable to be a good coach or not. Coaches will now recognize and alert you to certain warnings which your breeding assistant may not notice."},{"t":"Monsters, Inc.","p":["PlayStation 2"],"r":"March 19","l":"https://en.wikipedia.org/wiki/Monsters,_Inc._(video_game)"},{"t":"Monsters, Inc. Scream Arena","p":["GameCube"],"r":"September 14","l":"https://en.wikipedia.org/wiki/Monsters,_Inc._Scream_Arena"},{"t":"MoonBase Commander","p":["Windows"],"d":"Humongous Entertainment","u":"Infogrames","g":"Turn-based strategy","r":"August 13, 2002","l":"https://en.wikipedia.org/wiki/MoonBase_Commander","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2izc.jpg","s":"In the far future, Mankind has nearly exhausted all of earth’s natural resources. Fragile alliances between nations are tested to their limits as fierce wars ignite across land and space.\n\nMoonBase Commander puts you in charge of your own lunar territory in a quest to build the most powerful empire in space. Find, exploit and utilize valuable energy pools to eliminate rival factions. Choose the best strategies to accomplish your goals by using weapons, surveillance or shields to fortify your defenses.\n\nMoonBase Commander is a simple to learn but difficult to master turn-based strategy game. Featuring multiple and unique opposing factions, bright graphics, a tight narrative and a variety of customizable terrains. Battle against the challenging AI or your friends via LAN multiplayer."},{"t":"Moop and Dreadly in the Treasure on Bing Bong Island","p":["Windows","macOS"],"d":"Hulabee Entertainment","u":"Plaid Banana Entertainment","g":"Adventure, Edutainment","r":"March 18, 2002","l":"https://en.wikipedia.org/wiki/Moop_and_Dreadly_in_the_Treasure_on_Bing_Bong_Island","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/ujb4f49ekz4naedjkbnl.jpg","s":"Moop and Dreadly is a point & click adventure game aimed more towards a younger crowd."},{"t":"Mortal Kombat: Deadly Alliance","p":["PlayStation 2","GameCube","Xbox","Game Boy Advance"],"r":"November 16"},{"t":"Moto Racer Advance","p":["Game Boy Advance"],"d":"Adeline Software International, Delphine Software International","u":"Ubi Soft","g":"Racing","r":"October 4, 2002","l":"https://en.wikipedia.org/wiki/Moto_Racer_Advance","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3ho4.jpg","s":"The player controls a motorcyclist and must try to win races on various terrain and settings. Each motorcycle in the game handles differently with some performing better on paved roads and others working better on rougher terrain.[1]\n\nThere are a number of different modes: Grand Prix (GP), Motocross, and Traffic. GP takes place at a number of different locations across the world on paved tracks in places such as San Francisco and Russia. The paved tracks require the player to learn how to effectively use their brakes around corners. The GP courses contain small differences between them, giving more variety to the courses in the game. Motocross requires the player to drive on off-road terrain and to master the act of \"powersliding\" on corners. The courses found in Motocross races are less hospitable and often take place in arid and unkept locales and with obstacles. Traffic mixes both GP and Motocross, having mixed pavement courses and traffic on roads that serve as obstacles."},{"t":"Motocross Maniacs Advance","p":["Game Boy Advance"],"d":"Konami Computer Entertainment Hawaii","u":"Konami","g":"Racing","r":"March 21, 2002","l":"https://en.wikipedia.org/wiki/Motocross_Maniacs_Advance","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/v6by3kwcwxyxqfy5extk.jpg","s":"Explosive Motocross Racing! Motocross Maniacs rides onto the Game Boy Advance with cool courses, explosive weapons and furious gameplay. Race together with friends to see who is riding champ!"},{"t":"MotoGP 2","p":["PlayStation 2"],"r":"January 22","l":"https://en.wikipedia.org/wiki/MotoGP_2"},{"t":"MotoGP: Ultimate Racing Technology","p":["Game Boy Advance","Xbox","Windows"],"d":"Visual Impact, Climax Brighton, Cybiko, THQ","u":"THQ","g":"Racing","r":"February 15, 2002","l":"https://en.wikipedia.org/wiki/MotoGP:_Ultimate_Racing_Technology"},{"t":"Mr. Driller A","p":["Game Boy Advance"],"d":"Namco","u":"Namco","g":"Puzzle","r":"August 23, 2002","l":"https://en.wikipedia.org/wiki/Mr._Driller_A","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5v2y.jpg"},{"t":"Mr. Driller Drill Land","p":["GameCube"],"d":"Namco","u":"Namco, Bandai Namco Entertainment","g":"Puzzle","r":"December 20, 2002","l":"https://en.wikipedia.org/wiki/Mr._Driller_Drill_Land"},{"t":"Muppet Pinball Mayhem","p":["Game Boy Advance"],"r":"May 29"},{"t":"Mutsu to Nohohon","p":["GameCube"],"d":"Tomy","u":"Tomy","g":"Simulation","r":"July 19, 2002","l":"https://en.wikipedia.org/wiki/Mutsu_to_Nohohon"},{"t":"MX Superfly","p":["PlayStation 2"],"r":"June 18","l":"https://en.wikipedia.org/wiki/MX_Superfly"},{"t":"My Disney Kitchen","p":["Windows","PlayStation"],"d":"Disney Interactive","u":"Disney Interactive, Atlus, BAM! Entertainment","g":"Edutainment","r":"February 7, 2002","l":"https://en.wikipedia.org/wiki/My_Disney_Kitchen","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ryx.jpg","s":"In My Disney Kitchen kids can whip up culinary delights using tons of wacky appliances and gadgets. Using the recipe box as their guide, youngsters can select from an assortment of tasty treats. Kids can bake and decorate cakes, or try out their griddle skills as a short order cook. Joining in on the fun are the neighbors from across the street, Mickey and Minnie Mouse, who love to stop by and visit the budding chefs in the kitchen. The art and voices are reminiscent of Disney's classic cartoons."},{"t":"MyCoke","p":["Browser"],"g":"Music, Role-playing (RPG), Simulator","l":"https://en.wikipedia.org/wiki/MyCoke","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/xqkslo8matdh4filh70f.jpg","s":"An MMO browser chatroom, lasting from 2002 to 2007, with properties akin to Habbo Hotel. Though a majority of this title's purpose was for promotional reasons, the focus of the game was to socialize, mix music, and decorate various interiors."},{"t":"Mystic Heroes","p":["GameCube"],"r":"September 30","l":"https://en.wikipedia.org/wiki/Mystic_Heroes"},{"t":"Namco Super Wars","p":["WonderSwan Color"],"d":"Namco","u":"Bandai","g":"Tactical role-playing game","r":"October 31, 2002","l":"https://en.wikipedia.org/wiki/Namco_Super_Wars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8nst.jpg","s":"Namco Super Wars is a tactical role-playing game developed by Namco and published by Bandai for the Wonderswan Color. It is a crossover game, featuring characters from several classic Namco titles.\n\nThe game is played on a square grid, on which both the player's and computer's units are placed. Each side takes turns moving and making actions with their units. Every character has a variety of attacks and special moves that can be selected when performing an action. Some of these consume Spirit Points, which slowly regenerate each turn. The game is divided into stages. Between each stage, the player is able to visit a shop and prepare his units before starting the next stage. Unlike most RPGs, characters do not gain levels for directly defeating opponents. Instead, completion of a map will reward the players with a number of level ups, which they can then distribute among their units as they wish."},{"t":"Nancy Drew: Ghost Dogs of Moon Lake","p":["Windows"],"g":"Adventure","r":"November 1","l":"https://store.steampowered.com/app/31850","i":"images/steam-31850.jpg","s":"Hunt for Clues on the Trail of a Pack of Phantom Hounds!"},{"t":"Nancy Drew: Secret of the Scarlet Hand","p":["Windows"],"g":"Action","r":"August 12","l":"https://store.steampowered.com/app/31890","i":"images/steam-31890.jpg","s":"Expose Buried Secrets and Catch a Thief Red-handed!"},{"t":"NASCAR Racing 2002 Season","p":["Windows"],"u":"Sierra Entertainment","r":"February 14, 2002","l":"https://en.wikipedia.org/wiki/NASCAR_Racing_2002_Season"},{"t":"NASCAR Thunder 2003","p":["PlayStation","PlayStation 2","Xbox","GameCube"],"r":"September 18","l":"https://en.wikipedia.org/wiki/NASCAR_Thunder_2003"},{"t":"NASCAR: Dirt to Daytona","p":["PlayStation 2","GameCube"],"d":"Monster Games","u":"Infogrames","g":"Sim racing","r":"November 12, 2002","l":"https://en.wikipedia.org/wiki/NASCAR:_Dirt_to_Daytona","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ydr.jpg","s":"Can you survive in the world of NASCAR? NASCAR: Dirt to Daytona challenges you to become the ultimate racer in four different NASCAR racing series. Racing to win is the key for drivers hoping to advance from small town dirt tracks to modified cars, trucks, and eventually the highly prized NASCAR Winston Cup cars. Learn the harsh realities of the racing world where losing can cost drivers not only points in the standings but loss of money from a sponsor."},{"t":"NationStates","p":["Browser"],"g":"Simulator","l":"https://en.wikipedia.org/wiki/NationStates","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4gic.jpg","s":"A browser-based geopolitical simulation."},{"t":"Natural Selection","p":["Windows"],"d":"Unknown Worlds Entertainment","g":"First-person shooter, real-time strategy","r":"October 31, 2002","l":"https://en.wikipedia.org/wiki/Natural_Selection_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co31pn.jpg","s":"Natural Selection is a change of the video game Half-Life. The concept is a mix of first-person shooter and real-time strategy game genres. The game was made by Charlie \"Flayra\" Cleveland, who later founded the company Unknown Worlds Entertainment. Natural Selection v1 was publicly released on Halloween 2002 for the first time and is now on version 3.2. Natural Selection 2 was released in autumn 2012."},{"t":"Naval Ops: Commander","p":["Windows"],"d":"Microcabin","u":"Koei","g":"Vehicle simulation game","l":"https://en.wikipedia.org/wiki/Naval_Ops:_Commander"},{"t":"NBA 2K2","p":["GameCube","Xbox","PlayStation 2"],"u":"Sega","r":"March 20, 2002","l":"https://en.wikipedia.org/wiki/NBA_2K2"},{"t":"NBA 2K3","p":["PlayStation 2"],"u":"Sega","r":"October 8, 2002","l":"https://en.wikipedia.org/wiki/NBA_2K3"},{"t":"NBA Courtside 2002","p":["GameCube"],"r":"January 12","l":"https://en.wikipedia.org/wiki/NBA_Courtside_2002"},{"t":"NBA Jam 2002","p":["Game Boy Advance"],"d":"DC Studios","u":"Acclaim Entertainment","g":"Sports","r":"February 21, 2002","l":"https://en.wikipedia.org/wiki/NBA_Jam_2002","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cnvkwfsll6qm4yipgtoa.jpg","s":"This Game Boy Advance version of NBA Jam (not based on the SNES assets) features several modes of play with familiar, over-the-top basketball action. Players can choose from any of the 29 NBA teams in the league, each having several key players to take control of during the action...more than 140 superstars in all. Each professional in the game has his own playing attributes, from ball handling to dunking styles, so if you're looking to strut your stuff on the courts, it's best to know which players are the ones to grab. The game features the series' trademark alley-oops and skypasses, as well as the always-extreme \"on fire\" mode that's activated when a player sinks three baskets in a row. The game only fouls on Goaltending, so make sure you're not snagging the ball when it's coming down..."},{"t":"NBA Live 2003","p":["PlayStation 2"],"r":"October 8","l":"https://en.wikipedia.org/wiki/NBA_Live_2003"},{"t":"NBA ShootOut 2003","p":["PlayStation 2"],"r":"September 25","l":"https://en.wikipedia.org/wiki/NBA_ShootOut_2003"},{"t":"NBA Street","p":["GameCube"],"u":"EA Sports","r":"February 5, 2002","l":"https://en.wikipedia.org/wiki/NBA_Street"},{"t":"NCAA College Basketball 2K3","p":["PlayStation 2","GameCube","Xbox"],"d":"Kush Games, Visual Concepts","u":"Sega","g":"Sports","r":"December 3, 2002","l":"https://en.wikipedia.org/wiki/NCAA_College_Basketball_2K3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ue1.jpg","s":"NCAA College Basketball 2K3 is an American college basketball video game which was initially released on December 2, 2002 for the Xbox, PS2 and GameCube. It is to this day the only title in the series that uses the \"College Basketball\" designation rather than \"College Hoops\". It is also the only title for the series to appear on the GameCube and the GameCube's only college basketball game. It features former Duke Blue Devils guard Jay Williams on the cover. This game was released in very limited quantities and is one of the more difficult GameCube titles to find."},{"t":"NCAA College Football 2K3","p":["GameCube","PlayStation 2","Xbox"],"d":"Visual Concepts, Avalanche Software","u":"Sega of America","g":"Sports football","r":"August 6, 2002","l":"https://en.wikipedia.org/wiki/NCAA_College_Football_2K3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6udq.jpg","s":"It's time to hit the turf and get ready for another round of NCAA football action. NCAA College Football 2k3 is here and it's full of updated rosters, teams and stadiums to fulfill all of your college football needs. Play as your favourite up-and-comers with a friend to see who's the best. NCAA College Football 2k3 is here for the Microsoft Xbox and it's go time. Hut, hut!"},{"t":"NCAA Final Four 2003","p":["PlayStation 2"],"r":"November 27","l":"https://en.wikipedia.org/wiki/NCAA_Final_Four_2003"},{"t":"NCAA Football 2003","p":["PlayStation 2","GameCube","Xbox"],"u":"EA Sports","r":"July 20, 2002","l":"https://en.wikipedia.org/wiki/NCAA_Football_(video_game_series)"},{"t":"NCAA GameBreaker 2003","p":["PlayStation 2"],"r":"August 14","l":"https://en.wikipedia.org/wiki/NCAA_GameBreaker_2003"},{"t":"NCAA March Madness 2003","p":["PlayStation 2"],"d":"NuFX","u":"EA Sports","g":"Sports","r":"November 21, 2002","l":"https://en.wikipedia.org/wiki/NCAA_March_Madness_2003","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/whicpuaz0gdidcyxl9cj.jpg","s":"Do you dream of cutting down the net in New Orleans? Now you can experience the thrill of being the National Champ with NCAA? March Madness? 2003 -- the ultimate college basketball experience. From the crazed fans in the stands, to the mascots on the court and the fight songs played in the arenas, NCAA March Madness 2003 captures the spirit, excitement and rivalry that is college basketball."},{"t":"Necromania: Trap of Darkness","p":["Windows"],"d":"Darksoft Game Development Studio, Cinemax","u":"Strategy First","g":"Role-playing video game","r":"October 23, 2002","l":"https://en.wikipedia.org/wiki/Necromania:_Trap_of_Darkness","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6qa7.jpg","s":"In the dark fantasy world of Necromania: Trap of Darkness, players are thrust into an isometric action-tactical adventure reminiscent of the iconic Diablo series. Set in four distinct and treacherous realms, the game introduces a refreshing twist by allowing players to assume the roles of seven sinister anti-heroes, deviating from the typical \"good heroes\" seen in other games. Developed by the Slovakian team Darksoft Game Development Studio and the Czech company Cinemax, Necromania challenges players to navigate labyrinthine environments and overcome various enemies and creatures to acquire fragments of a powerful magic key.\n\nThe story centers around the fallen dark lord, Ragnar, who finds himself imprisoned by the forces of the Absurdian king, Bill Cocoton. In a bid to set Ragnar free and seize control of the realm, seven of Ragnar's loyal minions awaken from their slumber, each vying to obtain the magic keys that can unlock their master's prison. However, only one of them can ultimately lead the army of darkness to victory. As players progress through the game's numerous levels, they must strategize, laying traps and leveraging the intricacies of the environments to outsmart their adversaries.\n\nWhile Necromania: Trap of Darkness received mixed reviews, critics praised its multiplayer mode, even though finding opponents proved challenging. However, the game faced criticism for its unrefined gameplay mechanics and notable difficulty. The title offered an interesting blend of puzzle-like elements and combat, with an emphasis on trap utilization rather than direct confrontation. The lack of balance among the character classes and dated visuals added to the overall underwhelming experience. Despite its attempts to innovate, Necromania: Trap of Darkness fell short of leaving a lasting impression in the gaming landscape."},{"t":"Need for Speed: Hot Pursuit 2","p":["PlayStation 2","Windows","Xbox","GameCube"],"u":"Electronic Arts","r":"October 2, 2002"},{"t":"Neocron","p":["Windows"],"r":"October 30","l":"https://en.wikipedia.org/wiki/Neocron"},{"t":"Neverwinter Nights","p":["Windows"],"u":"Infogrames","r":"June 18, 2002","l":"https://en.wikipedia.org/wiki/Neverwinter_Nights_(2002_video_game)"},{"t":"New Legends","p":["Xbox"],"d":"Infinite Machine","u":"THQ","g":"Action-adventure, Hack and slash","r":"February 19, 2002","l":"https://en.wikipedia.org/wiki/New_Legends","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6qcd.jpg","s":"New Legends is a third-person action game setting man against militia, in a world of tomorrow where both technology and tradition blend to create a rich, and threatening world. It's a thrilling combination of mysticism and machines, of religion and aggression, of blades and bullets."},{"t":"New World Order","p":["Windows"],"d":"Termite Games","u":"Project Three Interactive, Strategy First","g":"First-person shooter","r":"December 5, 2002","l":"https://en.wikipedia.org/wiki/New_World_Order_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3zhk.jpg","s":"New World Order is a team based FPS, similarly tactical to Counter Strike. Released in 2003 it was negatively recieved by critics as a \"poorly made CS clone\"."},{"t":"NFL 2K3","p":["PlayStation 2","GameCube","Xbox"],"u":"Sega","r":"August 21, 2002","l":"https://en.wikipedia.org/wiki/NFL_2K"},{"t":"NFL Blitz 20-02","p":["PlayStation 2"],"r":"February 6","l":"https://en.wikipedia.org/wiki/NFL_Blitz#Installments"},{"t":"NFL Blitz 20-03","p":["PlayStation 2"],"r":"August 12","l":"https://en.wikipedia.org/wiki/NFL_Blitz_20-03"},{"t":"NFL Fever 2003","p":["Xbox"],"d":"Microsoft Game Studios","u":"Microsoft Game Studios","g":"Sports","r":"August 6, 2002","l":"https://en.wikipedia.org/wiki/NFL_Fever_2003","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/fykzc0s19tmlaga2z8ce.jpg","s":"NFL Fever 2003 is an American football video game published and developed by Microsoft Game Studios. It was originally released on August 6, 2002 for the Xbox video game console. The game, which was also used for beta testing for Xbox Live, was preceded by NFL Fever 2002 and followed by NFL Fever 2004."},{"t":"NFL GameDay 2003","p":["PlayStation 2"],"r":"August 12","l":"https://en.wikipedia.org/wiki/NFL_GameDay_2003"},{"t":"NHL 2003","p":["PlayStation 2"],"r":"September 30","l":"https://en.wikipedia.org/wiki/NHL_2003"},{"t":"NHL 2K2","p":["Dreamcast"],"r":"February 14","l":"https://en.wikipedia.org/wiki/NHL_2K2"},{"t":"NHL 2K3","p":["Xbox","GameCube","PlayStation 2"],"u":"Sega","r":"November 19, 2002","l":"https://en.wikipedia.org/wiki/NHL_2K3"},{"t":"NHL FaceOff 2003","p":["PlayStation 2"],"r":"November 5","l":"https://en.wikipedia.org/wiki/NHL_FaceOff_2003"},{"t":"NHL Hitz 20-03","p":["PlayStation 2"],"r":"September 16","l":"https://en.wikipedia.org/wiki/NHL_Hitz_20-03"},{"t":"Nickelodeon Party Blast","p":["PlayStation 2"],"r":"December 6","l":"https://en.wikipedia.org/wiki/Nickelodeon_Party_Blast"},{"t":"NickToons Racing","p":["Game Boy Advance"],"r":"June 14","l":"https://en.wikipedia.org/wiki/Nicktoons_Racing"},{"t":"NightCaster","p":["Xbox"],"d":"VR1 Entertainment","u":"Microsoft Game Studios","g":"Action-adventure","r":"January 22, 2002","l":"https://en.wikipedia.org/wiki/NightCaster","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co87pg.jpg","s":"NightCaster is a third-person, single-player, action-adventure game for the Xbox, developed by VR1 Entertainment and published by Microsoft. Players take the role of Arran, a novice wizard whose magical power grows as he ages throughout his quest to collect spells and rid the world of eternal night. NightCaster was released on December 26, 2001 and its ESRB rating is Teen.\n\nIn December 2002, the sequel, NightCaster II: Equinox, was released, with two-player compatibility.\n\nThe game received generally middling reviews with a Metacritic average of 61"},{"t":"NightCaster II: Equinox","p":["Xbox"],"d":"Jaleco","u":"Jaleco","g":"Action role-playing","r":"December 2002","l":"https://en.wikipedia.org/wiki/NightCaster_II:_Equinox","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co87pi.jpg","s":"A fast-paced action game where you play as either Madelyn, the warrior, or Arran, the hero of the first game. You'll battle hordes of enemies using powerful spells and melee attacks in a dark fantasy world. The game features a unique control system that allows you to move and aim spells independently."},{"t":"Nijiiro Dodge Ball: Otome Tachi no Seishun","p":["PlayStation"],"d":"Million Co. Ltd.","u":"Atlus","g":"Sports game, social simulation","r":"December 12, 2002","l":"https://en.wikipedia.org/wiki/Nijiiro_Dodge_Ball:_Otome_Tachi_no_Seishun"},{"t":"Ninja Assault","p":["PlayStation 2"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Ninja_Assault"},{"t":"No One Lives Forever 2: A Spy in H.A.R.M.'s Way","p":["Windows"],"u":"Sierra Entertainment","r":"September 30, 2002"},{"t":"O.R.B: Off-World Resource Base","p":["Windows"],"d":"Strategy First","u":"Strategy First, Mindscape","g":"Space simulation, Strategy game","r":"November 8, 2002","l":"https://en.wikipedia.org/wiki/O.R.B:_Off-World_Resource_Base"},{"t":"OGame","p":["Browser"],"d":"Gameforge AG","g":"Real-time browser-based MMO","r":"October 3, 2002","l":"https://en.wikipedia.org/wiki/OGame","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3dfi.jpg","s":"OGame is a strategy game set in space, with thousands of players from across the world competing at the same time. You only need a regular web browser to play.\n\nYou start out with just one undeveloped world and turn that into a mighty empire able to defend your hard earned colonies.\n\nCreate an economic and military infrastructure to support your quest for the next greatest technological achievements.\n\nWage war against other empires as you struggle with other players to gain the materials.\nNegotiate with other emperors and create an alliance or trade for much needed resources.\n\nBuild an armada to enforce your will throughout the universe.\nHoard your resources behind an impregnable wall of planetary defences.\nWhatever you wish to do, OGame can let you do it.\n\nWill you terrorize the area around you? Or will you strike fear into the hearts of those who attack the helpless?"},{"t":"Ollo in the Sunny Valley Fair","p":["Windows","macOS","Linux"],"d":"Hulabee Entertainment","u":"Plaid Banana Entertainment","g":"Adventure, Edutainment","l":"https://en.wikipedia.org/wiki/Ollo_in_the_Sunny_Valley_Fair","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1q6f.jpg","s":"This pre-schooler title is done in a form of painted backgrounds with either 3D or clay characters and items. The interface even looks like clay. While the main character does not talk, the game includes an off-screen narrator. Most other characters do talk, however. \n \nLike most kids adventure games, there are things to click on but this game has more of an undercurrent of trying to teach and encourages exploring by the acquiring of marbles to play a pachinko game."},{"t":"Omoide ni Kawaru Kimi: Memories Off","p":["Dreamcast","PlayStation 2"],"g":"Adventure, Visual Novel","l":"https://en.wikipedia.org/wiki/Omoide_ni_Kawaru_Kimi:_Memories_Off","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2wl4.jpg","s":"The third game in the Memories Off franchise."},{"t":"Onimusha 2: Samurai's Destiny","p":["PlayStation 2"],"r":"August 28"},{"t":"Operation Blockade","p":["Windows"],"d":"ScreamingGames","u":"Infogrames","g":"First-Person Shooter","r":"May 29, 2002","l":"https://en.wikipedia.org/wiki/Operation_Blockade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3xti.jpg"},{"t":"Operation Flashpoint: Red Hammer","p":["Windows","Linux"],"d":"Codemasters","u":"Codemasters","g":"Tactical shooter","r":"February 1, 2002","l":"https://en.wikipedia.org/wiki/Operation_Flashpoint:_Red_Hammer"},{"t":"Operation Flashpoint: Resistance","p":["Windows"],"d":"Bohemia Interactive Studio","u":"Codemasters","g":"Tactical shooter","r":"June 28, 2002","l":"https://en.wikipedia.org/wiki/Operation_Flashpoint:_Resistance"},{"t":"Outlaw Golf","p":["Xbox"],"r":"June 10","l":"https://en.wikipedia.org/wiki/Outlaw_Golf"},{"t":"Pac-Man All-Stars","p":["Windows"],"d":"Creature Labs","u":"Infogrames","g":"Maze","r":"May 14, 2002","l":"https://en.wikipedia.org/wiki/Pac-Man_All-Stars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7yjr.jpg","s":"Pac-Man All-Stars is a PC game released by Infogrames in 2002. It is an enhanced version of the multiplayer mode found in Ms. Pac-Man Maze Madness (as well as in Pac-Man: Adventures in Time), which was released a few years prior."},{"t":"Pac-Man Fever","p":["GameCube","PlayStation 2"],"d":"Mass Media Inc.","u":"Namco Hometek","g":"Party","r":"September 3, 2002","l":"https://en.wikipedia.org/wiki/Pac-Man_Fever_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dz7.jpg"},{"t":"Pac-Man World 2","p":["PlayStation 2","GameCube","Xbox"],"r":"February 26","l":"https://en.wikipedia.org/wiki/Pac-Man_World_2"},{"t":"Panzer Dragoon Orta","p":["Xbox"],"u":"Sega","r":"December 19, 2002","l":"https://en.wikipedia.org/wiki/Panzer_Dragoon_Orta"},{"t":"Paradise Cracked","p":["Windows"],"d":"MiST Land South","g":"Turn-based tactics","l":"https://en.wikipedia.org/wiki/Paradise_Cracked","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/nhgwedmigesdxjqn3hzp.jpg","s":"For many years the world had suffered from overpopulation and ecological destruction, until the leading scientists created CyberBrain - a supercomputer that solved all the global problems and turned the overpopulated and polluted Earth into Paradise. You are a young hacker. Once, while in cyberspace you managed to break into a secured area and came across a series of strange data packets. You hurriedly copied these to disk, not even having the time to read their contents. Only a few minutes later you hear a police siren, followed by banging on the door and demands to open up..."},{"t":"PaRappa the Rapper 2","p":["PlayStation 2"],"r":"January 23","l":"https://en.wikipedia.org/wiki/PaRappa_the_Rapper_2"},{"t":"Peter Pan: Adventures in Never Land","p":["PlayStation","Windows","Game Boy Advance"],"d":"Doki Denki, Crawfish Interactive","u":"Sony Computer Entertainment, Disney Interactive, Ubi Soft","g":"Action","r":"February 13, 2002","l":"https://en.wikipedia.org/wiki/Peter_Pan:_Adventures_in_Never_Land"},{"t":"Peter Pan: The Legend of Never Land","p":[],"l":"https://en.wikipedia.org/wiki/Peter_Pan:_The_Legend_of_Never_Land"},{"t":"Phantasy Star Collection","p":["Game Boy Advance"],"r":"November 24","l":"https://en.wikipedia.org/wiki/Phantasy_Star_Collection"},{"t":"Phantasy Star Online Episode I & II","p":["GameCube"],"r":"October 29","l":"https://en.wikipedia.org/wiki/Phantasy_Star_Online_Episode_I_%26_II"},{"t":"Phantom Crash","p":["Xbox"],"r":"November 4","l":"https://en.wikipedia.org/wiki/Phantom_Crash"},{"t":"Phase Zero","p":["Atari Jaguar"],"d":"Hyper Image Productions","u":"B&C ComputerVisions, Songbird Productions","g":"Shooter","r":"June 2002","l":"https://en.wikipedia.org/wiki/Phase_Zero"},{"t":"Phoenix Wright: Ace Attorney – Justice for All","p":["Game Boy Advance"],"d":"Capcom Production Studio 4","u":"Capcom","g":"Adventure, visual novel","r":"October 18, 2002","l":"https://en.wikipedia.org/wiki/Phoenix_Wright:_Ace_Attorney_%E2%80%93_Justice_for_All"},{"t":"Piece of Wonder","p":["Windows"],"d":"Studio Crossfire","u":"Studio Crossfire, Hirameki International","g":"Visual novel, Tactical role-playing game","r":"February 2002","l":"https://en.wikipedia.org/wiki/Piece_of_Wonder","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/m6zibxnceyrh0mo4fmkj.jpg","s":"A visual novel and tactical RPG hybrid."},{"t":"Pirates: The Legend of Black Kat","p":["PlayStation 2","Xbox"],"r":"February 17"},{"t":"PK: Out of the Shadows","p":["GameCube","PlayStation 2"],"d":"Ubi Soft Casablanca","u":"Ubi Soft","g":"Action-adventure, platformer","r":"October 4, 2002","l":"https://en.wikipedia.org/wiki/PK:_Out_of_the_Shadows","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1w1m.jpg","s":"The PK character may be unfamiliar to American audiences, but he is popular in Italy (and some other parts of Europe) through a series of comic books. This game is a simple 3rd person action shooter game. You control PK as he targets Evronian soldiers with his blasters, jumps through colorful environments, and rescues captured scientists."},{"t":"PlaneShift","p":["Windows","Linux","macOS"],"g":"Role-playing (RPG), Indie","l":"https://en.wikipedia.org/wiki/PlaneShift_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7sgz.jpg","s":"PlaneShift is a Massively Multiplayer Online Role Playing Game immersed into a 3D virtual fantasy world, completely made and maintained by volunteers! Passionate RPG gamers gathered to create an open and freely available game."},{"t":"Platoon","p":["Windows"],"d":"Digital Reality","u":"Monte Cristo, Strategy First","g":"Real-time strategy","r":"November 19, 2002","l":"https://en.wikipedia.org/wiki/Platoon_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co907e.jpg","s":"Strategy game which takes place in vietnam. You control a platoon of GIs through a campaign with 14 missions.\nPlatoon is the second video game adaptation of the 1986 war film of the same title, following the 1987 game by Ocean Software"},{"t":"Platypus","p":["Windows","Windows Mobile"],"d":"Squashy Software","u":"Idigicon","g":"Horizontally scrolling shooter","r":"May 14, 2002","l":"https://en.wikipedia.org/wiki/Platypus_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ejm.jpg","s":"Platypus is a fast, frantic and fun arcade-style shoot-em-up.\n\nThe vast continent-spanning city of Collosatropolis has finally reached the limits of its expansion. Tall buildings cover every available space. The air is thick with smoke and poisonous chemicals. Parking is a nightmare.\n\nThe Collosotropolan leaders have decided the simplest solution is to invade the neighbouring country of Mungola. They don't anticipate much of a struggle - Mungolans are simple, earthy types without much love for industry. In fact, Mungola's entire defence force consists of a single squadron of fighter planes - the venerable F-27 \"Platypus\".\n\nWhat possible threat could a few antique aircraft be to the mighty Collosotropolan Battle Fleet...?\n\nTo the Mungolan people the venerable F-27 \"Platypus\" is their last best hope for freedom!"},{"t":"Pocket Music","p":["Game Boy Advance","Game Boy Color"],"d":"Jester Interactive","u":"Rage Games","g":"Music","r":"April 26, 2002","l":"https://en.wikipedia.org/wiki/Pocket_Music","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9i0r.jpg"},{"t":"Pokémon Ruby and Sapphire","p":["Game Boy Advance"],"r":"November 21","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Ruby_and_Sapphire"},{"t":"Pool Edge","p":["GameCube"],"g":"Sport","l":"https://en.wikipedia.org/wiki/Pool_Edge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ued.jpg"},{"t":"Popotan","p":[],"l":"https://en.wikipedia.org/wiki/Popotan"},{"t":"Port Royale: Gold, Power and Pirates","p":["Windows"],"d":"Ascaron Entertainment","u":"Ascaron Entertainment, Tri Synergy, CAPCOM","g":"Business simulation game","r":"June 5, 2002","l":"https://en.wikipedia.org/wiki/Port_Royale:_Gold,_Power_and_Pirates","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e0h.jpg","s":"Port Royale is an economic trading sim set in the Caribbean in the 17th century. Gameplay includes trading, naval combat, town construction and questing."},{"t":"Post Mortem","p":["Windows"],"d":"Microids","u":"Microids, The Adventure Company, DreamCatcher Interactive","g":"Adventure","r":"November 13, 2002","l":"https://en.wikipedia.org/wiki/Post_Mortem_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jjk.jpg","s":"After returning to the quiet streets of Paris to pursue a life of painting, Gus Macpherson could not escape his true art…\n\nThe former New York detective finds himself walking the beat once again, when hired by a sensuous woman to investigate the gruesome beheadings of her sister and brother-in-law. In the dark and mysterious streets of Paris and plagued by his clairvoyant sixth sense, Gus will uncover a conspiracy written in blood, with rituals and artifacts as old as time itself."},{"t":"Power Rangers Wild Force","p":["Game Boy Advance"],"d":"Natsume Co., Ltd.","u":"THQ","g":"Action video game","r":"August 19, 2002","l":"https://en.wikipedia.org/wiki/Power_Rangers_Wild_Force_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3fe7.jpg","s":"In Power Rangers Wild Force for Game Boy Advance, young gamers will play as their favorite Power Ranger, this time armed with the strength and characteristics of the Power Animals including the Bison, Tiger, Shark, Eagle and Lion. The top-down, 3D exploration adventure allows players to take on the Org, an ancient race of villains who are out to destroy the balance of nature."},{"t":"Premier Manager 2002/2003 Season","p":["PlayStation 2"],"d":"Runecraft, Tuna Technologies","u":"Zoo Digital Publishing","g":"Sports","r":"November 22, 2002","l":"https://en.wikipedia.org/wiki/Premier_Manager_2002/2003_Season"},{"t":"Prince of Qin","p":["Windows"],"d":"Object Software","u":"Strategy First, GMX Media","g":"Action role-playing","r":"August 20, 2002","l":"https://en.wikipedia.org/wiki/Prince_of_Qin_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9074.jpg","s":"Action-RPG set in the last years of the Qin Dynasty in China 2,200 years ago -- a real historical setting with a number of characters who actually lived at the time. The game balances team-fighting, with up to five heroes per team, with various strategies and tactics. You will be challenged by many enemies in more than 100 unique scenes accurately depicting society and architecture as it existed at the time. The game's novel features include multi-scenario and multi-ending systems, randomly created weapons, items and enemies, an equipment creating system and a sophisticated fighting system rooted in the ancient philosophy of the Five Elements. The Great Wall of China and the Terracotta Warriors Tomb are some of the world-renowned locations the game highlights."},{"t":"Princess Holiday","p":[],"l":"https://en.wikipedia.org/wiki/Princess_Holiday"},{"t":"Prisoner of War","p":["PlayStation 2","Xbox","Windows"],"d":"Wide Games","u":"Codemasters","g":"Stealth","r":"July 19, 2002","l":"https://en.wikipedia.org/wiki/Prisoner_of_War_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5via.jpg","s":"Prisoner of War captures the intrigue, danger and heroism of Allied escape attempts from prisoner of war camps during World War II, including Colditz - the Germans highest security \"escape-proof\" camp. Gameplay delivers a tense 3rd person stealth adventure game where bravery, stealth and cunning will win the day."},{"t":"Pro Evolution Soccer 2","p":["PlayStation 2"],"u":"Konami","r":"April 25, 2002","l":"https://en.wikipedia.org/wiki/Pro_Evolution_Soccer_2"},{"t":"Pro Race Driver","p":["PlayStation 2"],"r":"December 6","l":"https://en.wikipedia.org/wiki/Pro_Race_Driver"},{"t":"Pro Rally 2002","p":["PlayStation 2","GameCube"],"d":"Ubi Soft Barcelona","u":"Ubi Soft","g":"Racing","r":"March 28, 2002","l":"https://en.wikipedia.org/wiki/Pro_Rally_2002","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6uek.jpg","s":"Pro Rally 2002 is a rally racing video game developed by Ubi Soft in 2002. The game features 20 licensed vehicles and 48 racing courses across international locations, offering gameplay modes including Time trial, Arcade, Trophy, Challenge and Professional."},{"t":"Progress Quest","p":["Windows","Linux"],"d":"Eric Fredricksen","u":"Eric Fredricksen, pkunk","g":"Parody of MMORPGs","l":"https://en.wikipedia.org/wiki/Progress_Quest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2z9k.jpg","s":"Progress Quest is a video game developed by Eric Fredricksen as a parody of EverQuest and other massively multiplayer online role-playing games. It is loosely considered a zero-player game, in the sense that once the player has set up their artificial character, there is no user interaction at all; the game \"plays\" itself, with the human player as spectator."},{"t":"Project Earth: Starmageddon","p":["Windows"],"d":"Lemon Interactive","u":"DreamCatcher Interactive Inc.","g":"RTS","r":"April 26, 2002","l":"https://en.wikipedia.org/wiki/Project_Earth:_Starmageddon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7n26.jpg"},{"t":"Project Nomads","p":["Windows"],"r":"November 5","l":"https://en.wikipedia.org/wiki/Project_Nomads"},{"t":"Pryzm: Chapter One - The Dark Unicorn","p":["PlayStation 2"],"d":"Digital Illusions Canada","u":"TDK Mediactive","r":"June 11, 2002","l":"https://en.wikipedia.org/wiki/Pryzm:_Chapter_One_-_The_Dark_Unicorn"},{"t":"Punch King","p":["Game Boy Advance"],"d":"Full Fat","u":"Acclaim Entertainment","g":"Sports video game","r":"May 30, 2002","l":"https://en.wikipedia.org/wiki/Punch_King","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/fnmlwzi3lzwywqcipzas.jpg","s":"The Ring Has A New King! Climb into the squared circle and go head-to-head with the baddest bunch of boxers around. Duck, jab and clobber your way to the championship title!"},{"t":"Quantum Redshift","p":["Xbox"],"d":"Curly Monsters","u":"Microsoft Game Studios","g":"Futuristic racing","r":"September 17, 2002","l":"https://en.wikipedia.org/wiki/Quantum_Redshift","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2y9s.jpg","s":"Set 100 years in the future, Quantum Redshift lets players take to the track in a no-holds-barred combat pod racing tournament with the chance of reaching speeds up to 900 miles per hour. You can bet it'll be hard to see any stop signs going that fast."},{"t":"Quest for the Code","p":["Windows"],"d":"Starbright","u":"Starbright","g":"Educational","r":"May 28, 2002","l":"https://en.wikipedia.org/wiki/Quest_for_the_Code"},{"t":"R/C Helicopter","p":["Windows","PlayStation 2","Xbox"],"d":"Arc System Works, Sonic Powered, AquaSystem","u":"AquaSystem","r":"May 30, 2002","l":"https://en.wikipedia.org/wiki/R/C_Helicopter"},{"t":"Racing Simulation 3","p":["Windows"],"d":"Ubi Soft Paris","u":"Ubi Soft","g":"Sim racing","r":"December 5, 2002","l":"https://en.wikipedia.org/wiki/Racing_Simulation_3"},{"t":"Rage of the Dragons","p":["Arcade","Neo Geo AES","Windows"],"d":"Evoga, Noise Factory","u":"Playmore, QUByte Interactive, SNK, Piko Interactive","g":"Fighting","r":"June 6, 2002","l":"https://en.wikipedia.org/wiki/Rage_of_the_Dragons","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ek0.jpg","s":"In a town ruled by an evil religious cult, the battle to decide the strongest dragon begins! Each Contestant is a champion who contends with the power of mighty dragons: Black Dragon, Red Dragon, Blue Dragon, and White Dragon. Go head to head in a tag-team partnership to test your attack and defense in the heat of battle."},{"t":"Ragnarok Online","p":["Windows"],"d":"Gravity","u":"Gravity","g":"Massively multiplayer online role-playing","r":"August 31, 2002","l":"https://en.wikipedia.org/wiki/Ragnarok_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocs4e.jpg","s":"Ragnarok Online is a Korean MMORPG inspired by the manhwa Ragnarok by Lee Myung-jin. While rooted in Norse Mythology, the game also draws from influences of Christianity and Asian Cultures. Player characters inhabit a dynamic world where features and history evolve over time, reflecting the ongoing episodes in the RO timeline."},{"t":"RalliSport Challenge","p":["Xbox","Windows"],"d":"Digital Illusions CE","u":"Microsoft Game Studios","g":"Racing","r":"March 7, 2002","l":"https://en.wikipedia.org/wiki/RalliSport_Challenge","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaph8.jpg","s":"You want real rally racing? Try strapping yourself in for the four play modes of RalliSport Challenge. Twenty-five licensed vehicles participate in Conventional Rally, RallyCross, Hill Climb and Ice Racing. Tracks are taken from the real world, with matching terrains and environments. Particle and weather effects heighten the realism. RalliSport Challenge's unique AI engine delivers drivers with their own individual personalities and driving habits, and effective graphics and animations bring it all to life."},{"t":"Rally Championship","p":["PlayStation 2"],"d":"Warthog","u":"SCi Games, Conspiracy Entertainment","g":"Racing","r":"May 31, 2002","l":"https://en.wikipedia.org/wiki/Rally_Championship_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6m58.jpg","s":"Mud! Sweat! Gears!\nDirt! Snow! Rain!\n\n-25 officially licensed rally racing cars.\n-33 races in 6 prestigious rallies over 4 global regions.\n-4-Player simultaneous split-screen intense action.\n-Real car physics simulate all wheel & 2-wheel drive.\n-Extreme weather conditions test your driving skills."},{"t":"Rally Fusion: Race of Champions","p":["PlayStation 2"],"r":"November 11"},{"t":"Ratchet & Clank","p":["PlayStation 2"],"u":"Sony Computer Entertainment","r":"November 4, 2002","l":"https://en.wikipedia.org/wiki/Ratchet_%26_Clank_(2002_video_game)"},{"t":"RC Cars","p":["Windows"],"d":"Creat Games","u":"1C Company, Whiptail Interactive, Metro3D, TikGames","g":"Vehicular combat game","r":"November 15, 2002","l":"https://en.wikipedia.org/wiki/RC_Cars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3yb0.jpg","s":"R.C. Cars is an exciting arcade racing game featuring the world of highly realistic toy radio controlled cars. Jump, accelerate, perform acrobatic feats in the air, and bounce on big hummocks, pits and bumps while contending with opponents for victory. Win prize money for placing in the race, purchase car upgrades and participate on further tracks!"},{"t":"Real Pool 2","p":["Windows"],"d":"Groove Alliance","u":"Infogrames","g":"Sports video game","r":"February 24, 2002","l":"https://en.wikipedia.org/wiki/Real_Pool_2"},{"t":"Red Faction II","p":["PlayStation 2"],"r":"October 15","l":"https://en.wikipedia.org/wiki/Red_Faction_II"},{"t":"RedCard 20-03","p":["PlayStation 2"],"r":"April 16","l":"https://en.wikipedia.org/wiki/RedCard_20-03"},{"t":"Reign of Fire","p":["PlayStation 2","Xbox","GameCube","Game Boy Advance"],"r":"October 22","l":"https://en.wikipedia.org/wiki/Reign_of_Fire_(video_game)"},{"t":"Resident Evil","p":["GameCube"],"u":"Capcom","r":"March 22, 2002","l":"https://en.wikipedia.org/wiki/Resident_Evil_(2002_video_game)"},{"t":"Resident Evil 0","p":["GameCube"],"r":"November 12","l":"https://en.wikipedia.org/wiki/Resident_Evil_0"},{"t":"Resident Evil Remake","p":["GameCube"],"r":"April 30","l":"https://en.wikipedia.org/wiki/Resident_Evil_(2002_video_game)"},{"t":"Resident Evil Zero","p":["GameCube"],"d":"Capcom Production Studio 3","u":"Capcom","g":"Survival horror","r":"November 12, 2002","l":"https://en.wikipedia.org/wiki/Resident_Evil_Zero","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2w3w.jpg","s":"Resident Evil Zero is a third-person survival horror video game and a prequel to the first Resident Evil. The gameplay remains largely the same as previous entries in the series but also introduces what it calls a partner zapping system, which allows you to switch between the two characters Rebecca and Billy at any time. This feature must be used at times, as the game requires both characters to work together to solve some puzzles. New to the game are a bunch of terrifying enemies, like the mutant centipede, new areas to explore, and the ability to drop items on the ground instead of having to find an item box."},{"t":"Reveal Fantasia","p":["PlayStation 2"],"d":"Infinity Co., Ltd.","u":"Victor Interactive Software","g":"Role playing, Fantasy","r":"February 20, 2002","l":"https://en.wikipedia.org/wiki/Reveal_Fantasia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co99rg.jpg","s":"Reveal Fantasia Is a Fantasy role playing video game released in 2002 for the PlayStation 2 console by Victor Interactive Software, Inc. in Japan. The game involved an innovative concept of a role playing game involving no battles or fighting. Its game play shows some influence from dating simulation games."},{"t":"Rez","p":["PlayStation 2"],"r":"January 7","l":"https://en.wikipedia.org/wiki/Rez_(video_game)"},{"t":"RHEM","p":["Windows"],"d":"Knut Müller","u":"Got Game Entertainment, Micro Application","g":"Graphic adventure","r":"August 2002","l":"https://en.wikipedia.org/wiki/RHEM","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8hed.jpg","s":"Rhem is an adventure game in which the player explores a barren, maze-like landscape of water ponds, walkways, and brick buildings with the aid of a partial map. The game has several puzzles involving machines and symbols."},{"t":"Rhino Rumble","p":["Game Boy Color"],"d":"Lost Boys Games","u":"Telegames","g":"Platform","r":"March 28, 2002","l":"https://en.wikipedia.org/wiki/Rhino_Rumble","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48zv.jpg","s":"It's amazing what some animals will do just to get a drink of water. Take Rocky the Rhino, for instance: Positively parched (he ate way too many peppers at a local jungle party), the little fellow is willing to traverse 19 enormous levels in the hope of quenching his mighty thirst. Help the adorable Rocky get through seven unique worlds, fending off all who would stand in his way. Many of the jungle's inhabitants are convinced that Rocky will drink up the water supply, you see, so they're all working against you from the outset. Make your way through forests and caves, using unique artillery like fireball breath and belly jumps to squelch the attempts of your foes and get to the magical spring. In addition to your weaponry, you'll have the assistance of various boats, planes, trampolines, and wagons to reach the end of each level."},{"t":"Riding Spirits","p":["PlayStation 2"],"r":"August 31","l":"https://en.wikipedia.org/wiki/Riding_Spirits"},{"t":"Riviera: The Promised Land","p":["WonderSwan Color"],"d":"Sting Entertainment","u":"Sting Entertainment, Atlus, 505 Games","g":"Role-playing","r":"July 12, 2002","l":"https://en.wikipedia.org/wiki/Riviera:_The_Promised_Land","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2nz4.jpg","s":"In Riviera: The Promised Land, you'll follow two fierce warriors--each armed with godly weapons--in a mission to defeat demons once and for all. The adventure included lets you experience more than 30 hours of role-playing gameplay, complete with minigames, multiple endings, and secret paths and items. The game's unique item system allows items to function differently depending on which characters equip them."},{"t":"RLH: Run Like Hell","p":["PlayStation 2"],"r":"September 27"},{"t":"Road Trip Adventure","p":["PlayStation 2"],"d":"E-Game Inc.","u":"Takara, Conspiracy Entertainment, Play It","g":"Racing / Adventure","r":"January 10, 2002","l":"https://en.wikipedia.org/wiki/Road_Trip_Adventure"},{"t":"Road Trip: The Arcade Edition","p":["GameCube"],"d":"Hudson Soft","u":"Takara, Zoo Digital Publishing, Conspiracy Entertainment","g":"Racing","r":"December 19, 2002","l":"https://en.wikipedia.org/wiki/Road_Trip:_The_Arcade_Edition"},{"t":"Robin Hood: The Legend of Sherwood","p":["Windows"],"d":"Spellbound Entertainment","u":"Strategy First, Mindscape, Freeverse Inc., Wanadoo Edition","g":"Real-time tactics, stealth","r":"November 12, 2002","l":"https://en.wikipedia.org/wiki/Robin_Hood:_The_Legend_of_Sherwood","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3yly.jpg","s":"Prince John Lackland has stolen the throne from King Richard Lionheart and put him to jail. You play as Robin Hood and his band of Merry Men, fighting Prince John and the Sheriff of Nottingham.\n\nUse the different skills of your Merry Men to either fight or sneak your way through levels to complete your objectives."},{"t":"Robot Alchemic Drive","p":["PlayStation 2"],"r":"November 4","l":"https://en.wikipedia.org/wiki/Robot_Alchemic_Drive"},{"t":"Robot Wars: Extreme Destruction","p":["Game Boy Advance","Windows","Xbox"],"d":"Warthog Games, Climax Development","u":"Gamezlab","g":"Action","r":"October 25, 2002","l":"https://en.wikipedia.org/wiki/Robot_Wars:_Extreme_Destruction","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co99p8.jpg","s":"Robot Wars: Extreme Destruction is an Action game, developed by Gamezlab and published by BBC Multimedia, which was released in Europe in 2002."},{"t":"Robotech: Battlecry","p":["PlayStation 2"],"r":"September 25"},{"t":"Robotech: The Macross Saga","p":["Game Boy Advance"],"d":"Lucky Chicken Games","u":"TDK Mediactive","g":"Shoot 'em up","r":"October 16, 2002","l":"https://en.wikipedia.org/wiki/Robotech:_The_Macross_Saga","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co50mk.jpg","s":"A classic 2D shooter that artfully mixes side-scrolling and forced perspective gameplay. Play as a mighty fighter from the hit Robotech series as you battle to save planet Earth from total destruction. Auto cannon fire lights up the skies in this epic intergalactic war with the Zentradi legions. The best defense that Earth has is the Veritech Valkyrie, a fast-changing fighter that moves through the air with the grace of a dancer and packs the punch of an armored division!"},{"t":"Rocket Power: Beach Bandits","p":["PlayStation 2","GameCube"],"r":"September 20"},{"t":"Rocky","p":["PlayStation 2"],"r":"November 18","l":"https://en.wikipedia.org/wiki/Rocky"},{"t":"RollerCoaster Tycoon 2","p":["Windows"],"r":"October 15","l":"https://en.wikipedia.org/wiki/RollerCoaster_Tycoon_2"},{"t":"Rugrats: I Gotta Go Party","p":["Game Boy Advance"],"r":"November 8"},{"t":"Rugrats: Royal Ransom","p":["PlayStation 2","GameCube"],"d":"Avalanche Software","u":"THQ","g":"Action-adventure, platformer","r":"November 26, 2002","l":"https://en.wikipedia.org/wiki/Rugrats:_Royal_Ransom","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wm3.jpg","s":"Rugrats Royal Ransom is an action-adventure game released in 2002 by THQ for the PlayStation 2 and the Nintendo GameCube. The game is based on the Rugrats television series on Nickelodeon. The game's plot is loosely based on Rugrats: Castle Capers."},{"t":"Run Like Hell","p":["PlayStation 2"],"d":"Digital Mayhem","u":"Interplay Entertainment","g":"Third-person shooter","r":"September 30, 2002","l":"https://en.wikipedia.org/wiki/Run_Like_Hell_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5tsu.jpg","s":"Run Like Hell (also known as RLH) is a third-person shooter video game designed by Digital Mayhem and released by Interplay for the PlayStation 2 in late 2002 and for Xbox in early 2003.\n\nRun Like Hell is set on a space station in the distant future. It features the voice talents of Lance Henriksen, Thomas F. Wilson, Clancy Brown, Kate Mulgrew, Michael Ironside and Brad Dourif. The game also features the music of Three Days Grace and Breaking Benjamin, including an exclusive music video of their song \"Polyamorous\".\n\nThe later Xbox version includes one new level and several new alien creatures, while several optional player character skins and additional minigames can also be downloaded via Xbox Live or the Xbox Exhibition 3 demo disc."},{"t":"Rygar: The Legendary Adventure","p":["PlayStation 2"],"r":"November 25"},{"t":"Sakura Momoko no Ukiuki Carnival","p":["Game Boy Advance"],"d":"Nintendo NSD, indieszero","u":"Nintendo","g":"Role-playing","r":"July 5, 2002","l":"https://en.wikipedia.org/wiki/Sakura_Momoko_no_Ukiuki_Carnival","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocd6f.jpg","s":"A Game Boy Advance life simulation game developed by Indies Zero and published by Nintendo exclusively in Japan."},{"t":"Sakura Wars 4: Fall in Love, Maidens","p":["Dreamcast"],"d":"Red Entertainment, Overworks","u":"Sega, Beijing Entertainment All Technology","g":"Tactical role-playing, dating sim, visual novel","r":"March 21, 2002","l":"https://en.wikipedia.org/wiki/Sakura_Wars_4:_Fall_in_Love,_Maidens","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2vtl.jpg","s":"Sakura Wars 4 was promoted as the \"Grand Finale\" of the Sakura Taisen franchise and while the series did continue after the fourth entry, Fall in Love, Maidens was the final game to feature the franchise's original cast. The game brought an end to the story of the series' hero, Ogami, and all of his relationships with the characters throughout the series were brought to a finale."},{"t":"Salammbo: Battle for Carthage","p":["Windows"],"d":"Cryo Interactive, DreamCatcher Europe","u":"The Adventure Company","g":"Adventure game","r":"November 2002","l":"https://en.wikipedia.org/wiki/Salammbo:_Battle_for_Carthage","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uyf.jpg","s":"Inspired by the novel of Gustave Flaubert and the works of Phillippe Druillet, Salammbo: Battle for Carthage puts you in the middle of two of antiquities greatest powers. Can you deliver Salammbo's message before it's too late?"},{"t":"Salt Lake 2002","p":["Game Boy Advance","Windows","PlayStation 2"],"r":"January 19","l":"https://en.wikipedia.org/wiki/Salt_Lake_2002_(video_game)"},{"t":"Sangokushi Battlefield","p":["Windows"],"d":"Koei","u":"Koei","g":"Real-time strategy","r":"September 10, 2002","l":"https://en.wikipedia.org/wiki/Sangokushi_Battlefield"},{"t":"Savage Skies","p":["PlayStation 2"],"r":"March 31","l":"https://en.wikipedia.org/wiki/Savage_Skies"},{"t":"Savoir-Faire","p":["Windows","Linux","macOS","Browser"],"g":"Adventure","l":"https://en.wikipedia.org/wiki/Savoir-Faire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/rynjrvaxd5ppovwwr2dw.jpg","s":"The beautiful life is always damned, they say. As for you, you've overexpended yourself: fifteen years of prominence, champagne, carriage rides in the Tuileries, having your name whispered behind manicured hands, getting elegant ladies out of elegant fixes - and you're in debt. Bound by oath and honor to a pack of scoundrels. Your father, old peasant that he was, could have warned you against their type. A piece of interactive fiction written by Emily Short."},{"t":"Scene It?","p":[],"l":"https://en.wikipedia.org/wiki/Scene_It%3F"},{"t":"Scooby-Doo! Night of 100 Frights","p":["PlayStation 2"],"r":"May 20","l":"https://en.wikipedia.org/wiki/Scooby-Doo!_Night_of_100_Frights"},{"t":"Scrabble Complete","p":["Windows"],"d":"Infogrames","u":"Infogrames","g":"Puzzle game","r":"September 25, 2002","l":"https://en.wikipedia.org/wiki/Scrabble_Complete","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/uj2vezdpcqptsh8bb71e.jpg","s":"Scrabble Complete is an expanded definitive release of The gameplay of Scrabble Complete is nearly identical to that of the board game. Like other computer adaptations of popular board games, Scrabble Complete has additional features which allow the game to be customized; Players have the ability to tilt the board in different directions to change the viewpoint of the game board. At the game menu, players can change the background, the board color and the music. The game offers support for the Official Scrabble Players Dictionary and a hint system for novice Scrabble players.\n\nIn addition to the main stand-alone mode, Scrabble Complete offers network play. There are also several educational word games, such as word riddles and anagram search, included with Scrabble Complete. Some copies of the game also include the 1997 Boggle computer game as a bonus."},{"t":"Sea Trader: Rise of Taipan","p":["Game Boy Advance"],"d":"Jaleco Entertainment","u":"Jaleco Entertainment","g":"Simulation","r":"December 20, 2002","l":"https://en.wikipedia.org/wiki/Sea_Trader:_Rise_of_Taipan","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co898i.jpg","s":"Raise your sails and rouse your crew. It's time to discover new lands on the first commodities trading game for GameBoy Advance. Captain your own ship, with a band of wacky sailors at your command. Become the supreme Sea Trader as you trade in silk, grain, currency and black market goods to increase your wealth. Fight off pirates when they try to steal your goods, or even attack other ships to plunder their spoils. And when you're victorious, carousing is optional."},{"t":"SeaBlade","p":["Xbox"],"d":"Vision Scape Interactive","u":"Simon & Schuster Interactive, TDK Mediactive Europe","g":"Shooter","r":"November 20, 2002","l":"https://en.wikipedia.org/wiki/SeaBlade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/jahn448ig4hjn7eg7ntz.jpg","s":"Search, Rescue, and Destroy in the air and under the sea. White-knuckle fly-and-shoot action! 39 adrenaline-pumping missions. Advanced weaponry for maximum firepower. 6 challenging apocalyptic environments. Unlock SeaBlades for Multiplay: 2-4 players."},{"t":"Season Ticket Basketball 2003","p":["Windows"],"d":"Brian Nichols","u":"Infogrames","g":"Sports, Simulation","r":"September 10, 2002","l":"https://en.wikipedia.org/wiki/Season_Ticket_Basketball_2003"},{"t":"Season Ticket Football 2003","p":["Windows"],"d":"Dave Koch Sports","u":"Infogrames","g":"Sports, simulation","r":"August 18, 2002","l":"https://en.wikipedia.org/wiki/Season_Ticket_Football_2003"},{"t":"Seek and Destroy","p":["PlayStation 2"],"d":"Barnhouse Effect","u":"Takara, Conspiracy, Play It","g":"Action","r":"June 27, 2002","l":"https://en.wikipedia.org/wiki/Seek_and_Destroy_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8pap.jpg","s":"Seek and Destroy is a vehicular combat game in which the world of \"Quewar\" is populated, not by people, but by tanks. The story follows the \"Q-Stein\" invasion of \"Proton\" and the Proton military's struggle to repel the attack."},{"t":"Sega GT 2002","p":["Xbox"],"d":"Wow Entertainment","u":"Sega","g":"Racing","r":"September 3, 2002","l":"https://en.wikipedia.org/wiki/Sega_GT_2002","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7t2h.jpg","s":"Sega GT 2002 is a sim racing video game published by Sega. It is the sequel to Wow Entertainment's Racing Game Sega GT, released in 2002. The game was originally intended to be released for the Dreamcast, but when the Dreamcast was discontinued in 2001, the game was reprogrammed for the Xbox. Following its initial release as a retail game, it was given away on a disk with Jet Set Radio Future in specially-marked Xbox console packages. Sega released Sega GT Online for the following year, with extra cars and an online facility to be used with the Xbox Live. Despite being an Xbox exclusive, the franchise would later die off and as a result, the Forza Motorsport series would later come to Xbox starting in 2005, and would later have sequels to counter the Gran Turismo franchise.\n\nSega GT 2002 introduced plenty of innovative features, many of which were later adopted by future games of its kind."},{"t":"Sega Network Taisen Mahjong MJ","p":["Arcade"],"d":"Sega AM2","u":"Sega","g":"Arcade video game","l":"https://en.wikipedia.org/wiki/Sega_Network_Taisen_Mahjong_MJ"},{"t":"Sega Soccer Slam","p":["GameCube","Xbox"],"r":"March 18","l":"https://en.wikipedia.org/wiki/Sega_Soccer_Slam"},{"t":"Sega Sports Tennis","p":["PlayStation 2"],"r":"July 31","l":"https://en.wikipedia.org/wiki/Sega_Sports_Tennis"},{"t":"Serious Sam: The Second Encounter","p":["Windows"],"r":"February 1"},{"t":"Shadow Man: 2econd Coming","p":["PlayStation 2"],"r":"March 2"},{"t":"Shadow of Memories (USA)","p":["Windows"],"r":"December 2","l":"https://en.wikipedia.org/wiki/Shadow_of_Memories"},{"t":"Shantae","p":["Game Boy Color"],"r":"June 22","l":"https://en.wikipedia.org/wiki/Shantae_(video_game)"},{"t":"Sherlock Holmes: The Mystery of the Mummy","p":["Windows"],"r":"December 29"},{"t":"Shifters","p":["PlayStation 2"],"r":"June 18","l":"https://en.wikipedia.org/wiki/Shifters"},{"t":"Shin Megami Tensei J","p":["Mobile phone"],"d":"Atlus","u":"Atlus","g":"Role-playing","r":"April 1, 2002","l":"https://en.wikipedia.org/wiki/Shin_Megami_Tensei_J","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2uga.jpg","s":"Shin Megami Tensei J is a Shin Megami Tensei cellphone game designed for early Japanese feature phones."},{"t":"Shin Megami Tensei: Nine","p":["Xbox"],"d":"Atlus, NexTech","u":"Atlus","g":"Role-playing","r":"December 5, 2002","l":"https://en.wikipedia.org/wiki/Shin_Megami_Tensei:_Nine","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2y9r.jpg","s":"Shin Megami Tensei: Nine was published by Atlus and released on Xbox, exclusively in Japan, in 2002.\n\nForming part of the Megami Tensei series, Nine takes place in the period of time between Shin Megami Tensei and its sequel, with the survivors of Tokyo's destruction sheltering in underground bunkers. Taking on the role of a debugger, the player navigates the Idea Space virtual world set up by the survivors of Tokyo's destruction, which has come under attack by demonic beings called \"noise\". The gameplay has the player navigating a customized avatar in third-person through the virtual world of Tokyo, battling enemies using a real-time command-based battle system. Despite its title, it is the eighth game in the Megami Tensei series. The game's title instead refers to the number of possible moral alignments available to players."},{"t":"Shining Soul","p":["Game Boy Advance"],"d":"Nextech, Grasshopper Manufacture","u":"Sega, Sega Europe, Atlus USA","g":"Action role-playing","r":"March 28, 2002","l":"https://en.wikipedia.org/wiki/Shining_Soul","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8kzb.jpg","s":"Enter a world of magic and mystery, where your closest allies may sometimes turn out to be your worst enemies. Shining Soul puts you in the middle of a desperate struggle between the Dark Dragon and a group of warriors known as the Shining Fleet. In the final stage of the war, you can play one of four character classes: fighter, wizard, archer, or dragonute. Customize your character's color schemes, weapons, and armor, and then explore the world of Shining Soul either alone or with three of your friends."},{"t":"Shinobi","p":["PlayStation 2"],"r":"November 10","l":"https://en.wikipedia.org/wiki/Shinobi_(2002_video_game)"},{"t":"Shiren the Wanderer Gaiden: Asuka the Swordswoman","p":["Dreamcast","Windows"],"d":"Neverland, Chunsoft","u":"Sega, Chunsoft","g":"Roguelike, role-playing","r":"February 7, 2002","l":"https://en.wikipedia.org/wiki/Shiren_the_Wanderer_Gaiden:_Asuka_the_Swordswoman"},{"t":"Shox","p":["PlayStation 2"],"r":"November 19","l":"https://en.wikipedia.org/wiki/Shox"},{"t":"Shrek Super Party","p":["PlayStation 2","Xbox"],"d":"Mass Media","u":"TDK Mediactive","g":"Party","r":"November 14, 2002","l":"https://en.wikipedia.org/wiki/Shrek_Super_Party","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dzb.jpg","s":"Shrek: Super Party is a party video game released in 2002 by Mass Media. The game is based on the Shrek movie series. This game is also similar to Pac-Man Fever (which has the same developer) and the Mario Party series of games. The characters Shrek, Fiona, Donkey, Lord Farquaad, Thelonius, and Monsieur Hood are available for play. Five realms are available for play, each with its own mini-games: The Keep, The Windmill, The Swamp, The Castle, and The Farm."},{"t":"Shrek Swamp Kart Speedway","p":["Game Boy Advance"],"d":"Prolific Publishing","u":"TDK Mediactive","g":"Racing","r":"March 19, 2002","l":"https://en.wikipedia.org/wiki/Shrek_Swamp_Kart_Speedway"},{"t":"Shrek: Hassle at the Castle","p":["Game Boy Advance"],"r":"October 10"},{"t":"Shrek: Treasure Hunt","p":["PlayStation"],"r":"October 18"},{"t":"Sid Meier's SimGolf","p":["Windows"],"d":"Firaxis Games","u":"EA Games","g":"Simulation, sports","r":"January 23, 2002","l":"https://en.wikipedia.org/wiki/Sid_Meier's_SimGolf","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2msy.jpg","s":"Build a thriving country club and beat the competition in this golf course management simulator from Sid Meier."},{"t":"Silent Scope 3","p":["PlayStation 2"],"d":"Konami","u":"Konami","g":"Rail shooter","r":"October 15, 2002","l":"https://en.wikipedia.org/wiki/Silent_Scope_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9b1z.jpg","s":"Silent Scope 3 contains an original story mode with numerous new areas created exclusively for the PlayStation2. As an added bonus, all 14 missions from the smash-hit arcade game Silent Scope EX are also included. In a Silent Scope series first, an innovative 3-D sound system can be used to help spot and target enemies. Rounding out the features, hidden options can be unlocked and multiple endings and paths add replay value."},{"t":"Silver Knights","p":["Windows"],"d":"Haruo Teshima","g":"Action, fighting, mech","r":"December 12, 2002","l":"https://en.wikipedia.org/wiki/Silver_Knights_(video_game)"},{"t":"Simon the Sorcerer 3D","p":["Windows"],"d":"Headfirst Productions","u":"Adventure Soft","g":"Adventure","r":"April 19, 2002","l":"https://en.wikipedia.org/wiki/Simon_the_Sorcerer_3D","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5vfr.jpg","s":"Simon is back and this time in 3 dimensions!\n\nThe adventure begins with Simon's soul being reunited with his body on the roof of an Aztec Temple. Slightly confused and disoriented, Simon escapes the temple with the help of his new fairy godmother.\n\nOnce again explore with Simon a vast fantastical world and help him find a way back home by uncovering the secrets of 'The Nexus'. Do this before your arch nemesis, Sordid, can use its power for more evil means.\n\nMeet up with favorite characters once more such as The Swampling, Calypso and the Woodworm! Enjoy over 40 hours of gameplay filled with ribald jokes, sly humour and 'off the cuff' quips.\n\nThis is full \"talkie\" version of the game. You can turn the subtitles on if you prefer subtitled version."},{"t":"Ski Park Manager","p":["Windows"],"d":"Lankhor","u":"Microïds","l":"https://en.wikipedia.org/wiki/Ski_Park_Manager"},{"t":"Sky Sports Football Quiz Season 02","p":["PlayStation","Windows"],"d":"Hothouse Creations","u":"THQ","g":"Quiz","r":"June 7, 2002","l":"https://en.wikipedia.org/wiki/Sky_Sports_Football_Quiz_Season_02"},{"t":"SkyGunner","p":["PlayStation 2"],"r":"June 24","l":"https://en.wikipedia.org/wiki/SkyGunner"},{"t":"Sled Storm","p":["PlayStation 2"],"r":"March 11","l":"https://en.wikipedia.org/wiki/Sled_Storm_(2002_video_game)"},{"t":"Sly Cooper and the Thievius Raccoonus","p":["PlayStation 2"],"r":"September 23","l":"https://en.wikipedia.org/wiki/Sly_Cooper_and_the_Thievius_Raccoonus"},{"t":"Smash Court Tennis Pro Tournament","p":["PlayStation 2"],"r":"March 20","l":"https://en.wikipedia.org/wiki/Smash_Court_Tennis_Pro_Tournament"},{"t":"Smuggler's Run","p":["Game Boy Advance"],"r":"July 22","l":"https://en.wikipedia.org/wiki/Smuggler%27s_Run"},{"t":"Snails","p":["Windows Mobile"],"d":"PDAmill","g":"Shooting","l":"https://en.wikipedia.org/wiki/Snails_(video_game)"},{"t":"Sneakers","p":["Xbox"],"r":"October 22","l":"https://en.wikipedia.org/wiki/Sneakers_(2002_video_game)"},{"t":"SOCOM U.S. Navy SEALs","p":["PlayStation 2"],"r":"August 27","l":"https://en.wikipedia.org/wiki/SOCOM_U.S._Navy_SEALs"},{"t":"Soldat","p":["Windows"],"g":"Shooter, Indie","l":"https://en.wikipedia.org/wiki/Soldat_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1yaw.jpg","s":"Soldat (meaning \"soldier\" in Italian, German, Russian, Norwegian, Danish, Swedish, French, Catalan and Romanian) is a Polish 2D multiplayer game for Windows. It is a side-scroller inspired by Liero and Scorched Earth, combined with elements from Counter-Strike and Worms. The game is shareware. Registration unlocks extra aesthetic options, such as colored jet flames and custom interfaces. Version 1.5.0 also includes a minimap and changeable screen resolution for registered users.\nSoldat is written and maintained by programmer Michał Marcinkowski, who started working on the game in November, 2001. It is coded in the Delphi programming language using the JEDI libraries. Though Marcinkowski is the primary developer, he works with a few others on the dedicated server and lobby, in addition to a small beta team which aids in testing prior to new releases."},{"t":"Soldier of Fortune II: Double Helix","p":["Windows"],"r":"May 20"},{"t":"Soldiers of Anarchy","p":["Windows"],"d":"Silver Style Entertainment","u":"Bigben Interactive, Simon & Schuster Interactive","g":"Real-time tactics","r":"October 23, 2002","l":"https://en.wikipedia.org/wiki/Soldiers_of_Anarchy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8z90.jpg","s":"Soldiers of Anarchy (SOA) is a 2002 squad-based real-time tactics video game released by Simon & Schuster."},{"t":"Sonic Advance","p":["Game Boy Advance"],"r":"February 3","l":"https://en.wikipedia.org/wiki/Sonic_Advance"},{"t":"Sonic Advance 2","p":["Game Boy Advance"],"r":"December 19","l":"https://en.wikipedia.org/wiki/Sonic_Advance_2"},{"t":"Sonic Adventure 2: Battle","p":["GameCube"],"r":"February 11"},{"t":"Sonic Mega Collection","p":["GameCube"],"r":"November 10","l":"https://en.wikipedia.org/wiki/Sonic_Mega_Collection"},{"t":"Space Channel 5 Part 2","p":["PlayStation 2"],"r":"November 28","l":"https://en.wikipedia.org/wiki/Space_Channel_5_Part_2"},{"t":"Space Fishermen","p":["PlayStation 2"],"d":"Land Ho!","u":"Sony Computer Entertainment","g":"Fishing","r":"October 24, 2002","l":"https://en.wikipedia.org/wiki/Space_Fishermen","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ipl.jpg","s":"\"Space Fishermen\" is a 2002 fishing video game that breaks traditional norms by offering players a quirky and innovative experience. Developed through a collaboration between Land Ho! and Spumco, the game features three eccentric characters, planet-like fishing locations, and a unique reeling mechanism. Catch over 150 bizarre and alien fish species with the use of strategic lure preferences!"},{"t":"Space Raiders","p":["PlayStation 2"],"d":"Taito","u":"Taito, Sammy Europe, Mastiff","g":"Third-person shooter","r":"December 19, 2002","l":"https://en.wikipedia.org/wiki/Space_Raiders_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1pei.jpg","s":"Space Raiders is a third-person shooter taking place after an alien invasion of Earth. The game is a spin-off of Taito's Space Invaders with similar gameplay but in a 3D destroyed city setting.\n\nThe player can take control of three characters. These are Justin, a youngster knocked out and left for dead after his friends got slaughtered while on the run from the aliens, Ashly, the camerawoman who is trying to find her boyfriend who went missing after the invasion, and Naji the policeman who lost his partner in a fight with the aliens."},{"t":"Space Rangers","p":["Windows"],"d":"Elemental Games","u":"1C Company, Micro Application","g":"Turn-based space trading and combat simulator","r":"December 20, 2002","l":"https://en.wikipedia.org/wiki/Space_Rangers_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6iia.jpg","s":"Space Rangers is a space combat strategy game where you control your own ship and eventually a fleet of ships to fight the evil alien race, Klissans. You are put in an open world to play as you please to achieve your goal."},{"t":"Space Trader (Palm OS)","p":["Mobile phone","Windows Mobile","Windows"],"d":"Pieter Spronck","l":"https://en.wikipedia.org/wiki/Space_Trader_(Palm_OS)"},{"t":"Speed Challenge: Jacques Villeneuve's Racing Vision","p":["Windows","PlayStation 2","GameCube"],"d":"Ubi Soft","u":"Ubi Soft","g":"Racing","r":"October 3, 2002","l":"https://en.wikipedia.org/wiki/Speed_Challenge:_Jacques_Villeneuve's_Racing_Vision","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6uf5.jpg"},{"t":"Spider-Man: The Movie","p":["PlayStation 2","Game Boy Advance"],"r":"April 15","l":"https://en.wikipedia.org/wiki/Spider-Man_(2002_video_game)"},{"t":"SpongeBob SquarePants: Employee of the Month","p":["Windows"],"d":"AWE Games","u":"THQ","g":"Point-and-click","r":"September 20, 2002","l":"https://en.wikipedia.org/wiki/SpongeBob_SquarePants:_Employee_of_the_Month","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2tex.jpg","s":"SpongeBob SquarePants once again wins the \"Employee of the Month\" award, which makes him \"Employee of the Year\" Mr. Krabs Gives him two tickets to Neptune's Paradise."},{"t":"SpongeBob SquarePants: Revenge of the Flying Dutchman","p":["PlayStation 2","GameCube","Game Boy Advance"],"d":"BigSky Interactive, Inc., Vicarious Visions","u":"THQ","g":"Platform, action-adventure","r":"September 12, 2002","l":"https://en.wikipedia.org/wiki/SpongeBob_SquarePants:_Revenge_of_the_Flying_Dutchman","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa0pl.jpg","s":"A treasure turns into a terror in SpongeBob Squarepants: Revenge of the Flying Dutchman. While cruising through Bikini Bottom, SpongeBob discovers several treasure chests. Ignoring the warning signs, SpongeBob opens the chests, only to discover he has released the Flying Dutchman--an angry ghost that now wants to make SpongeBob and his friends part of his crew. As you help SpongeBob stop the Dutchman from wreaking havoc in Bikini Bottom, you change costumes, collect gold coins, and interact with all your favorite characters from the TV show."},{"t":"Spyro 2: Season of Flame","p":["Game Boy Advance"],"r":"September 25"},{"t":"Spyro: Enter the Dragonfly","p":["PlayStation 2","GameCube"],"r":"November 3"},{"t":"Star Fox Adventures","p":["GameCube"],"r":"September 23","l":"https://en.wikipedia.org/wiki/Star_Fox_Adventures"},{"t":"Star Trek: Bridge Commander","p":["Windows"],"d":"Totally Games","u":"Activision","g":"Space combat simulator","r":"February 28, 2002","l":"https://en.wikipedia.org/wiki/Star_Trek:_Bridge_Commander","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e97.jpg","s":"Star Trek: Bridge Commander is a space simulation set in the Star Trek universe just after the Dominion War, but before Star Trek Nemesis. It puts you in command of your own Starfleet vessel with the ability to coordinate with your senior staff. This game was published in 2002 for Windows PCs."},{"t":"Star Trek: Starfleet Command III","p":["Windows"],"d":"Taldren","u":"Activision","g":"Space simulation, real-time tactics","r":"November 21, 2002","l":"https://en.wikipedia.org/wiki/Star_Trek:_Starfleet_Command_III","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e9q.jpg","s":"Starfleet Command III is a 3D tactical starship combat game, set in the universe of Star Trek: The Next Generation. The single-player campaign arcs are playable as Federation, Klingon, or Romulan factions. The game has customizable starship construction options (giving the player the opportunity to retrofit phasers, torpedoes, engines, and other components as he or she gains prestige points). The Dynaverse 3 feature offers persistent online gaming as up to 128 players compete to conquer the galaxy.\n\nThe single-player storyline is broken into Klingon, Romulan, and Federation segments. The plotline involves a threat to galactic peace which emerges after the Klingon-Federation alliance constructs an advanced new starbase, designated 'Unity One', near the Romulan border. Each campaign invites the player to behave in a manner suited to the character of the chosen faction, as one proceeds through a consistent plot.\n\nIn addition to the single-player campaigns, there is a single-player 'Conquest' campaign which allows the player (as Klingon, Romulan, Federation, or Borg) to attempt to dominate the galaxy without passing through campaign missions. Head-to-head multiplayer action without the grand strategic elements of Dynaverse 3 is available in multiplayer battle scenarios which can be played over Internet or LAN."},{"t":"Star Trek: Voyager – The Arcade Game","p":["Arcade"],"d":"Game Refuge Inc.","u":"Monaco Entertainment, Team Play Inc.","g":"Light gun game","l":"https://en.wikipedia.org/wiki/Star_Trek:_Voyager_%E2%80%93_The_Arcade_Game"},{"t":"Star Trigon","p":["Arcade"],"d":"Project Driller, Namco Networks","u":"Namco","g":"Puzzle","r":"July 2002","l":"https://en.wikipedia.org/wiki/Star_Trigon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/erkxguapw6onurnatexk.jpg","s":"Star Trigon is a 2002 puzzle arcade game published in Japan by Namco. Ports for iPod, iOS devices and Windows were also released.\n\nIn the game, the player controls one of three characters - Wataru Hoshi, Chuta Bigbang and Susumu Hori - the objective being to rescue creatures known as \"Uchijins\" by hopping from planet to planet to draw triangles and capture them.\nThe player will automatically circle the planet they are on, requiring timed jumps to avoid falling off the playfield."},{"t":"Star Wars Episode II: Attack of the Clones","p":["Game Boy Advance"],"r":"May 30"},{"t":"Star Wars Jedi Knight II: Jedi Outcast","p":["Windows","GameCube","Xbox"],"u":"Activision","g":"Action","r":"March 26, 2002","l":"https://store.steampowered.com/app/6030","i":"images/steam-6030.jpg","s":"The Legacy of Star Wars Dark Forces™ and Star Wars® Jedi Knight lives on in the intense first-person action of Jedi Outcast."},{"t":"Star Wars: Bounty Hunter","p":["PlayStation 2","GameCube"],"r":"November 19"},{"t":"Star Wars: Jedi Starfighter","p":["PlayStation 2","Xbox"],"r":"March 10"},{"t":"Star Wars: Racer Revenge","p":["PlayStation 2"],"r":"February 11"},{"t":"Star Wars: The Clone Wars","p":["PlayStation 2","Xbox","GameCube"],"r":"October 28"},{"t":"Star Wars: The New Droid Army","p":["Game Boy Advance"],"r":"November 14"},{"t":"Star X","p":["Game Boy Advance"],"d":"Graphic State","u":"BAM! Entertainment","g":"Rail shooter","r":"April 15, 2002","l":"https://en.wikipedia.org/wiki/Star_X","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30j5.jpg","s":"Through nine unique and extreme environments, players fly in aerial combat both in and above the atmospheres of the galaxy's planets in free roaming and land fixed play modes. Players will need to successfully complete 22 intense missions and survive fierce air-to-air and air-to-land battles with an alien race in order to save their plane. A step-by-step training mode gives the best techniques and tactics to destroy enemy aircraft and perform land-based attacks."},{"t":"State of Emergency","p":["PlayStation 2"],"r":"February 12","l":"https://en.wikipedia.org/wiki/State_of_Emergency_(video_game)"},{"t":"Steel Battalion","p":["Xbox"],"r":"November 21","l":"https://en.wikipedia.org/wiki/Steel_Battalion"},{"t":"Strange Adventures in Infinite Space","p":["Windows","macOS","Linux"],"d":"Digital Eel","u":"Cheapass Games, Astraware","g":"Roguelike","r":"March 15, 2002","l":"https://en.wikipedia.org/wiki/Strange_Adventures_in_Infinite_Space","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc2uy.jpg","s":"Strange Adventures In Infinite Space is a hybrid space roguelike computer game. In the game players explore a \"plausibly implausible\" (fictional) region of the Milky Way galaxy called The Purple Void."},{"t":"Strategic Command: European Theater","p":["Windows"],"d":"Fury Software","u":"Battlefront.com","g":"Turn based strategy","r":"July 16, 2002","l":"https://en.wikipedia.org/wiki/Strategic_Command:_European_Theater","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ykd.jpg","s":"Strategic Command: European Theater is a World War II grand strategy game. The game, that is turn-based, takes place on a map that stretches horizontally from the east coast of North America to the Ural Mountains in Russia, and vertically from just below the Arctic Circle to the North Coast of Africa. There are six campaigns, each a year in the war that are played until the end of the war, starting with the Germans attacking Poland."},{"t":"Street Fighter Alpha 3","p":["Game Boy Advance"],"r":"December 1","l":"https://en.wikipedia.org/wiki/Street_Fighter_Alpha_3"},{"t":"Street Hoops","p":["PlayStation 2"],"r":"August 12","l":"https://en.wikipedia.org/wiki/Street_Hoops"},{"t":"Street Legal","p":["Windows"],"d":"Invictus Games","u":"Activision Value","g":"Racing","r":"October 30, 2002","l":"https://en.wikipedia.org/wiki/Street_Legal_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/qtf28irkz78ljfnhbqnx.jpg"},{"t":"Strike Fighters: Project 1","p":["Windows"],"d":"Third Wire Productions","u":"Strategy First","g":"Air combat simulation","r":"October 24, 2002","l":"https://en.wikipedia.org/wiki/Strike_Fighters:_Project_1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/nl6zpumwzfjnyx4o9ddp.jpg","s":"Strike Fighters: Project 1 is a military flight sim by Third Wire Productions."},{"t":"Stronghold: Crusader","p":["Windows"],"r":"September 25"},{"t":"Stuntman","p":["PlayStation 2"],"r":"June 23","l":"https://en.wikipedia.org/wiki/Stuntman_(video_game)"},{"t":"Sub Rebellion","p":["PlayStation 2"],"r":"October 12","l":"https://en.wikipedia.org/wiki/Sub_Rebellion"},{"t":"Sudden Strike 2","p":["Windows"],"d":"Fireglow Games","u":"CDV Software, Russobit-M","g":"Real-time tactics","r":"August 30, 2002","l":"https://en.wikipedia.org/wiki/Sudden_Strike_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobzkk.jpg","s":"Sudden Strike II is a WWII themed R.T.S that lets the player choose between the British, American, Japanese and German campaigns, sometimes consisting of clearing the area of enemies or killing a general. Sudden Strike II allows you to take control of land, sea and air making for spectacular battles."},{"t":"Suikoden III","p":["PlayStation 2"],"r":"October 24","l":"https://en.wikipedia.org/wiki/Suikoden_III"},{"t":"Summoner 2","p":["PlayStation 2"],"r":"September 23","l":"https://en.wikipedia.org/wiki/Summoner_2"},{"t":"Super Bust-A-Move 2","p":["PlayStation 2"],"r":"September 24"},{"t":"Super Mario Advance 2: Super Mario World","p":["Game Boy Advance"],"r":"February 9","l":"https://en.wikipedia.org/wiki/Super_Mario_World"},{"t":"Super Mario Advance 3: Yoshi's Island","p":["Game Boy Advance"],"r":"September 24"},{"t":"Super Mario Sunshine","p":["GameCube"],"u":"Nintendo","r":"August 26, 2002","l":"https://en.wikipedia.org/wiki/Super_Mario_Sunshine"},{"t":"Super Monkey Ball 2","p":["GameCube"],"r":"August 25","l":"https://en.wikipedia.org/wiki/Super_Monkey_Ball_2"},{"t":"Super Monkey Ball Jr.","p":["Game Boy Advance"],"r":"November 19","l":"https://en.wikipedia.org/wiki/Super_Monkey_Ball_Jr."},{"t":"Super Puzzle Bobble 2","p":["PlayStation 2"],"d":"Taito","u":"Taito, Ubi Soft","g":"Puzzle","r":"September 19, 2002","l":"https://en.wikipedia.org/wiki/Super_Puzzle_Bobble_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p22.jpg","s":"Super Bust-A-Move 2 offers arcade-style action and screen-clearing puzzle solving in an immersive environment full of vivid characters. It features a single-player puzzle mode that lets you play through multiple stages and multiple game types as each of the stories behind each of the game's characters is explained, and information is gradually revealed. There is also a battle mode that lets you challenge your friends or the computer as you compete in a best-of-three match. You can also create your own mind-bending, bubble-busting puzzles, play them, and save them to a memory card to challenge your friends. There is a scalable difficulty feature that adjusts the game for players of all skill levels."},{"t":"Super Robot Taisen: Original Generation","p":["Game Boy Advance"],"d":"Banpresoft","u":"Banpresto, Atlus, 505 Games","g":"Tactical role-playing","r":"November 22, 2002","l":"https://en.wikipedia.org/wiki/Super_Robot_Taisen:_Original_Generation","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fo3.jpg","s":"It is two hundred years after the beginning of the \"Space Era\", a time period when civilization began expanding into space. However, by the start of the 21st century, two meteors struck and destroyed much of the Earth, sending humanity into chaos. By year 179 of the Space Era, secret technology, dubbed Extra-Over Technology, or EOT, was discovered by the Earth Federal Government within a third meteor that had hit Earth at the Marquesas Islands in the South Pacific. Dr. Bian Zoldark, while investigating the meteor, also found out that the creators of the Extra-Over Technology were heading to Earth to reclaim it. In order to defend earth, the government starts to develop a group of humanoid mecha, known as Personal Troopers.\nThe alien race that created Extra-Over Technology, called the Aerogaters by the Earth Federal Government, initially attacks an Earth ship sent out to investigate their presence in the far reaches of the solar system. This initial skirmish ends in a defeat for the Aerogaters, prompting them to sue for negotiations with the Earth Federation Army. Talks are arranged to take place at a secret facility in Antarctica, but the talks are targeted by a rogue faction called the Divine Crusaders.\nThe Divine Crusaders destroys the Aerogater delegation, then turn on the Federation forces. Bian Zoldark, revealing himself to be the leader of the Divine Crusaders, announces the existence of the Aerogaters to the world and rebel against the Earth Government. As Earth spins into civil war, a new Aerogater force is on the move, seeking to reclaim their lost technology..."},{"t":"Super Robot Wars R","p":["Game Boy Advance"],"d":"Banpresoft, AI","u":"Banpresto","g":"Tactical role-playing game","r":"August 2, 2002","l":"https://en.wikipedia.org/wiki/Super_Robot_Wars_R","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobvfd.jpg","s":"The second Super Robot Wars game for the Game Boy Advance, R (Reversal) follows the battles of the \"Round Knights\" as they fight against various mecha anime villains."},{"t":"Super Shot Soccer","p":["PlayStation"],"d":"Tecmo","u":"Tecmo","g":"Arcade-style traditional soccer simulation","r":"June 5, 2002","l":"https://en.wikipedia.org/wiki/Super_Shot_Soccer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co94cx.jpg","s":"Tecmo's Super Shot Soccer is a hybrid of simulation and arcade-styled soccer. Featuring over 30 teams from around the world, the game's play modes are based on international-styled soccer. The four play modes are Test Mode (exhibition play), World Tournament Play (inspired by soccer's World Cup), International League (a round-robin league) and International Cup (a 16 team tournament). Of these modes, only Test Mode allows two players to play the game at the same time.\n\nDiffering itself from typical soccer simulation titles, Super Shot Soccer provides over the top arcade-style plays. Called Super Shot Special Moves, each team has two or three special moves that tie into the team's nationality. These provide a unique twist to simulation soccer, as gameplay can be interrupted by national monuments, disaster attacks and more. Special moves can be used to affect both offensive and defensive strategies."},{"t":"Super Smash Bros. Melee","p":["GameCube"],"r":"May 24","l":"https://en.wikipedia.org/wiki/Super_Smash_Bros._Melee"},{"t":"Super Trucks","p":["PlayStation 2"],"d":"Jester Interactive","u":"Jester Interactive, XS Games","g":"Racing","r":"June 28, 2002","l":"https://en.wikipedia.org/wiki/Super_Trucks"},{"t":"Superman: Shadow of Apokolips","p":["PlayStation 2"],"r":"September 25"},{"t":"Superman: The Man of Steel","p":["Xbox"],"d":"Circus Freak Studios","u":"Infogrames","g":"Action-adventure","r":"November 12, 2002","l":"https://en.wikipedia.org/wiki/Superman:_The_Man_of_Steel_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6e43.jpg","s":"In the Xbox only Man of Steel, Players control Superman through 7 levels of 3D flying, overhead vertical scrolling and sidescrolling secitons."},{"t":"SuperPower","p":["Windows"],"d":"GolemLabs","u":"DreamCatcher Interactive, GMX Media","g":"Turn-based strategy","r":"March 27, 2002","l":"https://en.wikipedia.org/wiki/SuperPower","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/n0ok4q4s5x3rp9vt23ru.jpg","s":"Lead a country to glory, ruin or stable mediocrity in this \"geo-political world simulator\" of Earth circa 1997."},{"t":"Surveillance Kanshisha","p":["PlayStation 2"],"d":"Sony Computer Entertainment Japan","u":"Sony Computer Entertainment","g":"Adventure","r":"April 25, 2002","l":"https://en.wikipedia.org/wiki/Surveillance_Kanshisha","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8hhw.jpg","s":"Surveillance Kanshisha is a First-Party PlayStation 2 Adventure Science fiction interactive game published by Sony Computer Entertainment Japan with animation created by Production I.G.\n\nIt takes place in the 2050s where a United Nations-created special forces unit called Shadow Sword is deployed to protect the Earth-Mars travel route from anti-UN terrorists called Neo Kleit, conducting terrorist attacks to remove the UN's control of the space program. A special public security surveillance network is unveiled for the first time called Project Surveillance, which is used to assist Shadow Sword operatives in their work in apprehending and hunting down the terrorists."},{"t":"Sven Bømwøllen","p":["Windows"],"d":"Phenomedia","u":"ak tronic Software & Services GmbH","g":"Arcade video game","r":"February 18, 2002","l":"https://en.wikipedia.org/wiki/Sven_B%C3%B8mw%C3%B8llen","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gdu.jpg","s":"In Sven Bømwøllen, the player controls Sven, a black sheep, with a task to mate with all the white sheep around."},{"t":"Swingerz Golf","p":["GameCube"],"d":"Telenet Japan","u":"Eidos Interactive","g":"Sports","r":"October 23, 2002","l":"https://en.wikipedia.org/wiki/Swingerz_Golf","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ufa.jpg","s":"Tee up on 6 courses featuring diverse terrains and seasonal weather condition. Compete with 14 offbeat golfers, each with distinct personalities and golfing abilities. Experience realistic golfing physics with Ace Golf's intuitive analog swing system. Master multiple modes of play for 1-4 golfers including Tournament, Stroke, Match and Short Course. Win tournaments and beat rivals to upgrade your golf gear. Enjoy golfing action with addictive mini games."},{"t":"Sword of the Samurai","p":["PlayStation 2"],"d":"Lightweight","u":"Genki, Ubi Soft","g":"Fighting","r":"June 27, 2002","l":"https://en.wikipedia.org/wiki/Sword_of_the_Samurai_(2002_video_game)"},{"t":"Syberia","p":["Windows"],"d":"Microïds","u":"Microïds, The Adventure Company, XS Games","g":"Graphic adventure","r":"May 30, 2002","l":"https://en.wikipedia.org/wiki/Syberia_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co86zw.jpg","s":"Join Kate Walker as she travels to remote locations and time periods in this timeless voyage to discover her true destiny."},{"t":"Tactical Ops: Assault on Terror","p":["Windows"],"d":"Kamehan Studios","u":"Infogrames","g":"First-person shooter","r":"April 24, 2002","l":"https://en.wikipedia.org/wiki/Tactical_Ops:_Assault_on_Terror","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vdu.jpg","s":"Tactical Ops: Assault on Terror is a first-person shooter video game developed in 2002 by Kamehan Studios and published by Infogrames as a MicroProse title. The game is a standalone retail version of a multiplayer modification of the same name published by Kamehan Studios in 1999 for the game Unreal Tournament. The game features match-based missions in which two teams, themed as Special Forces and terrorists, battle to complete mission objectives and kill their opponents. Upon release, Tactical Ops received mixed to average reviews, with critics faulting the game's similarities to the non-commercial version and lack of defining features compared to other multiplayer first-person shooters."},{"t":"Tactics Ogre: The Knight of Lodis","p":["Game Boy Advance"],"r":"May 7"},{"t":"Tako no Marine","p":["Dreamcast"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Tako_no_Marine","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3kpe.jpg"},{"t":"Tales of Destiny 2","p":["PlayStation 2"],"d":"Telenet Japan, Wolf Team, Alfa System","u":"Namco, Sony Computer Entertainment","g":"Action role-playing game","r":"November 28, 2002","l":"https://en.wikipedia.org/wiki/Tales_of_Destiny_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p27.jpg","s":"Tales of Destiny 2 is a direct sequel to the Playstation's Tales of Destiny.\nThe game's battle system retains the same fluid, fast-paced action combat of its predecessor Tales of Eternia, but adds a range of experimental features including a stamina gauge and a fairly high level of character, equipment, and skill customisation."},{"t":"Tales of the World: Narikiri Dungeon 2","p":["Game Boy Advance"],"d":"Wolf Team & Alfa System","u":"Namco","g":"Action role-playing game","r":"October 25, 2002","l":"https://en.wikipedia.org/wiki/Tales_of_the_World:_Narikiri_Dungeon_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6sw2.jpg","s":"A crossover Tales series dungeon crawler for GBA."},{"t":"Tarzan: Return to the Jungle","p":["Game Boy Advance"],"d":"Digital Eclipse","u":"Activision","g":"Platform","r":"October 23, 2002","l":"https://en.wikipedia.org/wiki/Tarzan:_Return_to_the_Jungle"},{"t":"Taz: Wanted","p":["PlayStation 2","Xbox","Windows","GameCube"],"r":"September 17"},{"t":"TD Overdrive: The Brotherhood of Speed","p":["PlayStation 2","Xbox","Windows"],"d":"Pitbull Syndicate","u":"Infogrames","g":"Racing","r":"May 28, 2002","l":"https://en.wikipedia.org/wiki/TD_Overdrive:_The_Brotherhood_of_Speed","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ezw.jpg","s":"The game features various modes including Quick Race, Single Race and Underground, the game's main and story mode. Single Race mode includes Linear, Circuit, Cop Chase, Drag Race, and Navigation Challenge. The cars do not suffer damage and they can be painted pre-set or custom colors. There are 26 cars in total and 12 of the cars have police variations. The game has a rock, rap and techno soundtrack consisting of 10 artists and 17 songs; some are played in races and all are played on menus. The game also includes Atari's Pong as a minigame, which can be played while races are loading (though not in the European Windows version). One can play against the computer, or against the second player (during multi-player mode)."},{"t":"Tea Society of a Witch","p":["Windows"],"d":"Front Wing","u":"Front Wing, Hirameki International","g":"Bishōjo, visual novel, eroge","l":"https://en.wikipedia.org/wiki/Tea_Society_of_a_Witch"},{"t":"Technicbeat","p":["Arcade","PlayStation 2"],"d":"Arika","u":"Arika, Mastiff","g":"Music","r":"July 2002","l":"https://en.wikipedia.org/wiki/Technicbeat","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7f2y.jpg","s":"This is a game where you have to use your sense of rhythm to pass the levels with 85 different songs.\n\nYou walk around on a little stage with your character. As the music plays, markers pop up on the stage that expand in sync with the music. You have to hit those markers at the right time. This will trigger an instrument or jingle of the music (and give you points). Each characters has special abilities - some of them for example can move the markers to get them closer (or out of reach of the opponents). All characters can use a pitch-bend to change the tone of a triggered jingle for extra fun.\n\nApart from having several game modes, you can also play this game solo or with a friend, either cooperative or in a battle mode to see who's got a better sense of rhythm."},{"t":"Tekken 4","p":["PlayStation 2"],"r":"September 23","l":"https://en.wikipedia.org/wiki/Tekken_4"},{"t":"Tennis Masters Series 2003","p":["Windows","Xbox","PlayStation 2","Game Boy Advance"],"d":"Microïds Canada","u":"Microïds, Hip Interactive","g":"Sports","r":"September 14, 2002","l":"https://en.wikipedia.org/wiki/Tennis_Masters_Series_2003_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2sgw.jpg","s":"Are you ready to take on the world's best players in the Tennis Masters Series? Master the individual skills and styles of one of 67 different players, and then compete in multiplayer singles or doubles matches or single-player tournaments. The game reproduces nine Masters Series tournaments from locations including Miami, Rome, and Paris. With your four different shots--power top spin, slice, flat, and lob--you can create up to 60 different moves to use during matches."},{"t":"Test Drive","p":["PlayStation 2"],"r":"May 27"},{"t":"The Cameron Files: Pharaoh's Curse","p":["Windows"],"d":"Galilea","u":"DreamCatcher Interactive, The Adventure Company","g":"Adventure","r":"October 31, 2002","l":"https://en.wikipedia.org/wiki/The_Cameron_Files:_Pharaoh's_Curse","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2g37.jpg"},{"t":"The Elder Scrolls III: Morrowind","p":["Windows","Xbox"],"u":"Bethesda Softworks","r":"May 1, 2002"},{"t":"The Elder Scrolls III: Tribunal","p":["Windows"],"r":"November 6"},{"t":"The Fairly OddParents: Enter the Cleft","p":["Game Boy Advance"],"r":"November 4"},{"t":"The Gladiators of Rome","p":["Windows"],"d":"Cat Daddy Games","u":"Activision Value","g":"Action","r":"November 14, 2002","l":"https://en.wikipedia.org/wiki/The_Gladiators_of_Rome","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3jfw.jpg","s":"Intense action and deep strategy are at your fingertips in this real time strategy combat thriller. You are in control of a gladiator troop in ancient Rome. You must recruit slaves, refine their character and mold them into fighting machines.\n\nCollect weaponry, chariots and armor all to enhance your gladiators' ability to move up the ranks and fight in larger coliseums for higher purses, just like ancient Rome."},{"t":"The Gladiators: Galactic Circus Games","p":["Windows"],"d":"Eugen Systems","u":"Arxel Tribe, Tri Synergy","g":"Real-time strategy","r":"October 20, 2002","l":"https://en.wikipedia.org/wiki/The_Gladiators:_Galactic_Circus_Games","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25e1.jpg","s":"The Gladiators: Galactic Circus Games is a Real-Time-Strategy game developed by Eugen Systems and published by Arxel Tribe. It was released in the United States on March 1, 2003."},{"t":"The House of the Dead III","p":["Arcade"],"r":"June 1","l":"https://en.wikipedia.org/wiki/The_House_of_the_Dead_III"},{"t":"The I of the Dragon","p":["Windows"],"d":"Primal Software","u":"Akella, Deep Silver, Strategy First","g":"Role-playing video game, Strategy","r":"December 2002","l":"https://en.wikipedia.org/wiki/The_I_of_the_Dragon"},{"t":"The Invincible Iron Man","p":["Game Boy Advance"],"r":"December 15","l":"https://en.wikipedia.org/wiki/The_Invincible_Iron_Man_(video_game)"},{"t":"The King of Fighters 2002","p":["Arcade","Windows","Neo Geo AES"],"d":"Eolith, SNK Playmore, DotEmu","u":"Playmore, Sun Amusement, Ignition Entertainment, SNK","g":"Fighting","r":"October 10, 2002","l":"https://en.wikipedia.org/wiki/The_King_of_Fighters_2002","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3xw1.jpg","s":"The game brings back the team play composed by three characters each that was a tradition in previous games. The game has also several important changes in the gameplay, like the \"Free Cancel System\" or \"Max Mode System\", the \"Quick Emergency Evasion\" and \"Quick MAX Mode Activation\", aside from the countless changes in each character's special moves and their properties."},{"t":"The King of Fighters EX: Neo Blood","p":["Game Boy Advance"],"d":"Playmore, Artoon","u":"Sammy","g":"Fighting","r":"January 1, 2002","l":"https://en.wikipedia.org/wiki/The_King_of_Fighters_EX:_Neo_Blood","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4hik.jpg","s":"Invitations to the King of Fighters Tournament have been sent to the best fighters in the world by an unknown host. Despite suspicions of an evil scheme, the fighters are ready to enter the arena to determine who the true King of Fighters will be."},{"t":"The King of Route 66","p":["Arcade"],"d":"Sega AM2, Tose","u":"Sega","g":"Vehicle simulation, action","r":"February 2002","l":"https://en.wikipedia.org/wiki/The_King_of_Route_66","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co88on.jpg","s":"The King of Route 66 is the arcade racing game sequel to 18 Wheeler: American Pro Trucker. It was later brought to the PlayStation 2 by Tose. This game features a story mode in which the Evil Tornado Corporation has taken over all the trucking jobs along Route 66. You play a hero trucker who challenges Tornado drivers all along the route and puts them in their place by getting your cargo to the destination first."},{"t":"The Land Before Time","p":["Game Boy Advance"],"g":"Platform","l":"https://en.wikipedia.org/wiki/The_Land_Before_Time_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d6t.jpg","s":"The Land Before Time is a 2D platforming game developed by Full Fat for the Game Boy Advance. It was released in North America in February 2002, and Europe the following month, both published by Conspiracy Entertainment."},{"t":"The Land Before Time: Big Water Adventure","p":["Windows","PlayStation"],"g":"Platform","l":"https://en.wikipedia.org/wiki/The_Land_Before_Time:_Big_Water_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7zw8.jpg","s":"Featuring characters from the animated film series, The Land Before Time: Big Water Adventure lets young players guide Littlefoot, Ducky, Cera, and Spike through 14 levels in four worlds: Mountain Pass, Great Landbreak, New Water, and Soggy Swamp. Characters jump, run, slide, head-butt, and tail-whip as they explore levels containing obstacles such as moving logs, trees, lava, geysers, rivers, and ravines. The objective in each level is to collect 30 \"treestars\" and unlock bonus picture puzzles in Petrie's Palace.\n\nOther features include in-game movies and Mo's Big Water Racing, a bonus game that becomes available only after the main game has been completed with all four characters. In the bonus game, players have Mo jump through hoops on the river to trigger special animations. Each stage in the main game unlocks the next in sequential order, but once completed, levels can be replayed in any order in an attempt to collect all possible treestars.\n\nThe Land Before Time: Big Water Adventure is based on Universal Picture's film The Land Before Time IX: Journey to Big Water."},{"t":"The Legend of Zelda: A Link to the Past","p":["Game Boy Advance"],"r":"December 3"},{"t":"The Legend of Zelda: A Link to the Past and Four Swords","p":["Game Boy Advance"],"u":"Nintendo","r":"December 2, 2002"},{"t":"The Legend of Zelda: Ocarina of Time / Master Quest","p":["GameCube"],"u":"Nintendo","r":"December 13, 2002"},{"t":"The Legend of Zelda: The Wind Waker","p":["GameCube"],"u":"Nintendo","r":"December 13, 2002"},{"t":"The Lord of the Rings: The Two Towers","p":["PlayStation 2","Game Boy Advance","Xbox","GameCube"],"r":"October 21"},{"t":"The Lord of the Rings:The Fellowship of the Ring","p":["Xbox","Game Boy Advance","PlayStation 2","Windows"],"r":"September 24"},{"t":"The Mark of Kri","p":["PlayStation 2"],"r":"July 29","l":"https://en.wikipedia.org/wiki/The_Mark_of_Kri"},{"t":"The Mummy: The Animated Series","p":["Windows","Game Boy Advance"],"d":"Asobo Studio, Ubi Soft Milan","u":"Hip Interactive, Ubi Soft","g":"Action-adventure","r":"November 20, 2002","l":"https://en.wikipedia.org/wiki/The_Mummy:_The_Animated_Series_(video_game)"},{"t":"The Operative: No One Lives Forever","p":["PlayStation 2"],"r":"April 16"},{"t":"The Pinball of the Dead","p":["Game Boy Advance"],"r":"June 16","l":"https://en.wikipedia.org/wiki/The_Pinball_of_the_Dead"},{"t":"The Powerpuff Girls: Relish Rampage","p":["PlayStation 2","GameCube"],"d":"VIS Entertainment","u":"BAM! Entertainment","g":"Action-adventure","r":"November 25, 2002","l":"https://en.wikipedia.org/wiki/The_Powerpuff_Girls:_Relish_Rampage","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1oyb.jpg","s":"Mojo Jojo is fed up with The Powerpuff Girls. He's invented a scheme to put all of Townsville under his mind control...Radio Jojo! But Mojo doesn't know his sour signals are strong enough to summon aliens to invade Townsville! As The Powerpuff Girls, you must defeat Mojo and annihilate the aliens before the Townsville citizens become aliens forever! Battle your way through level upon level of interesting missions and outrageous clashes in a 3-D Townsville world. The survival of everyone's favorite superheroes, The Powerpuff Girls, depends on you!"},{"t":"The Real Neverending Story Part 1: Auryn Quest","p":[],"d":"Discreet Monsters, Attaction","u":"Octagon Entertainment, DreamCatcher Interactive","r":"June 12, 2002","l":"https://en.wikipedia.org/wiki/The_Real_Neverending_Story_Part_1:_Auryn_Quest"},{"t":"The Revenge of Shinobi","p":["Game Boy Advance"],"d":"3d6 Games","u":"Sega, THQ","g":"Action, platform, hack and slash","r":"November 19, 2002","l":"https://en.wikipedia.org/wiki/The_Revenge_of_Shinobi_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30in.jpg","s":"The Revenge of Shinobi is a 2002 hack-and-slash action game developed by 3d6 Games and published by THQ for the Game Boy Advance. Although both games share the same title and follow the exploits of a ninja character, the game is not a continuation or port of the Mega Drive/Genesis game of the same name."},{"t":"The Scorpion King: Rise of the Akkadian","p":["PlayStation 2"],"r":"September 10"},{"t":"The Scorpion King: Sword of Osiris","p":["Game Boy Advance"],"r":"March 31","l":"https://en.wikipedia.org/wiki/The_Scorpion_King"},{"t":"The Secret of the Nautilus","p":["Windows"],"d":"Cryo Interactive","u":"Cryo Interactive, DreamCatcher Interactive/The Adventure Company","g":"First-person fantasy adventure","r":"April 29, 2002","l":"https://en.wikipedia.org/wiki/The_Secret_of_the_Nautilus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2too.jpg","s":"This adventure game was inspired by the Jules Verne novel \"20,000 Leagues Under the Sea\".\n\nThe story begins aboard the USS Shark, a research submarine, exploring the depths of the Atlantic Ocean. The crew discovers a huge metallic object and argues whether to further examine it. During the debate, a young scientist, taking it upon himself to go without orders, steals a mini-sub and docks at the mysterious wreck. You play the scientist aboard what he learns to be Captain Nemo's vessel the \"Nautilus\". There are many rooms to explore and numerous puzzles to be solved in this 1st person point-and-click adventure game."},{"t":"The Simpsons Skateboarding","p":["PlayStation 2"],"r":"November 11","l":"https://en.wikipedia.org/wiki/The_Simpsons_Skateboarding"},{"t":"The Sims Online","p":["Windows"],"d":"Maxis","u":"EA Games","g":"Massively multiplayer online social simulation","r":"December 17, 2002","l":"https://en.wikipedia.org/wiki/The_Sims_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zo4.jpg","s":"The Sims Online was the first massively multiplayer online variation on Maxis's highly popular computer game The Sims, the second being the Online Weekend mode for The Sims Bustin' Out, and third being The Sims Social. The game was sold in retail stores in North America and Japan and could also be downloaded worldwide through the EA.com online store, though the game was English-only and had no official translations."},{"t":"The Sims: Unleashed","p":["Windows"],"d":"Maxis","u":"Electronic Arts, Aspyr Media","g":"Social simulation","r":"September 25, 2002","l":"https://en.wikipedia.org/wiki/The_Sims:_Unleashed"},{"t":"The Sims: Vacation","p":["Windows","macOS"],"d":"Maxis","u":"Electronic Arts, Aspyr Media","g":"Social simulation","r":"March 26, 2002","l":"https://en.wikipedia.org/wiki/The_Sims:_Vacation"},{"t":"The Suicide Bomber Game","p":["Browser"],"d":"fabulous999","u":"Newgrounds","r":"April 17, 2002","l":"https://en.wikipedia.org/wiki/The_Suicide_Bomber_Game"},{"t":"The Sum of All Fears","p":["Windows","Game Boy Advance","PlayStation 2","GameCube"],"d":"Red Storm Entertainment, Ubi Soft Milan","u":"Ubi Soft","g":"Tactical shooter","r":"May 28, 2002","l":"https://en.wikipedia.org/wiki/The_Sum_of_All_Fears_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wvp.jpg","s":"Lead a team of domestic counter-terrorism experts through 11 dangerous missions that span the globe. Formed from the elite of the F.B.I.'s HRT, you have been tapped to perform covert ops in the most dangerous circumstances imaginable. As the commander of this team, you'll lead your unit into the heat of battle, performing missions ranging from eliminating terrorists to planting bugs, and destroying illegal weapon caches to rescuing hostages. You'll give them orders in the field and take the point in leading them into combat."},{"t":"The Terminator: Dawn of Fate","p":["PlayStation 2"],"r":"September 16"},{"t":"The Thing","p":["Windows","Xbox","PlayStation 2"],"r":"August 20","l":"https://en.wikipedia.org/wiki/The_Thing_(video_game)"},{"t":"The Ur-Quan Masters","p":[],"l":"https://en.wikipedia.org/wiki/The_Ur-Quan_Masters"},{"t":"Thievery UT","p":["Windows"],"d":"Black Cat Games","g":"Stealth","r":"June 28, 2002","l":"https://en.wikipedia.org/wiki/Thievery_UT"},{"t":"This Is Football 2003","p":["PlayStation 2"],"d":"London Studio","u":"Sony Computer Entertainment, 989 Sports","g":"Sports","r":"October 4, 2002","l":"https://en.wikipedia.org/wiki/This_Is_Football_2003","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p34.jpg","s":"Soccer comes home as you lead your team to victory on or off the field. As a player, you'll tackle, pass, and shoot winning goals from the field. As an owner, you'll buy, sell, or trade players to create a winning team. More than 13,500 officially licensed FIFA pro players from 700 international and league teams compete in 10 stadiums around the globe. Your players can perform a variety of authentic moves, including high-flying headers, bicycle kicks, and goal-saving slide tackles."},{"t":"Thorgal: Curse of Atlantis","p":["Windows"],"d":"Cryo Interactive","u":"Le Lombard","g":"Point-and-click adventure","r":"September 20, 2002","l":"https://en.wikipedia.org/wiki/Thorgal:_Curse_of_Atlantis"},{"t":"Tiger Woods PGA Tour 2002","p":["PlayStation 2"],"r":"February 24","l":"https://en.wikipedia.org/wiki/Tiger_Woods_PGA_Tour#Games_in_the_series"},{"t":"Tiger Woods PGA Tour 2003","p":["Windows","GameCube","Xbox","PlayStation 2"],"u":"EA Sports","r":"October 31, 2002","l":"https://en.wikipedia.org/wiki/Tiger_Woods_PGA_Tour_2003"},{"t":"Time of Defiance","p":["Windows"],"d":"Nicely Crafted Entertainment","u":"Oxygen Games, Strategy First","g":"Massively multiplayer online real-time strategy","r":"August 21, 2002","l":"https://en.wikipedia.org/wiki/Time_of_Defiance"},{"t":"TimeSplitters 2","p":["PlayStation 2","GameCube","Xbox"],"u":"Eidos Interactive","r":"October 8, 2002","l":"https://en.wikipedia.org/wiki/TimeSplitters_2"},{"t":"Tiny Toon Adventures: Buster's Bad Dream","p":["Game Boy Advance"],"d":"Treasure Co. Ltd","u":"Swing! Entertainment, Conspiracy Entertainment","g":"Beat 'em up","r":"July 5, 2002","l":"https://en.wikipedia.org/wiki/Tiny_Toon_Adventures:_Buster's_Bad_Dream","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2d6x.jpg","s":"Join up with your favorite characters from the TINY TOON ADVENTURES universe for some action and excitement. Any fan of the classic cartoon series will go nuts for the near-perfect animation and familiar humor of the television show, but this game goes far beyond the call of duty. Between the long list of well-loved characters and the intense combat design, TINY TOON ADVENTURES: Buster's Bad Dream ranks among the Game Boy Advance elite. Make your way through four unique environments including Acme Forest, Haunted Mansion, Space Station, and a surprise locale partnering up with other Toons to destroy the likes of Elmyra, Montana Max, and many others. Babs Bunny, Dizzy Devil, Buster, and all the rest of the gang appear throughout, and there are plenty of hidden areas and personalities to unlock. The game's team system is such that one player can stun or distract an enemy, opening the door for the other player to inflict serious damage. The relationship between cartoon characters and violence dates back a ways, and TINY TOON ADVENTURES isn't about to break up the love affair."},{"t":"TOCA Race Driver","p":["PlayStation 2"],"r":"August 23","l":"https://en.wikipedia.org/wiki/TOCA_Race_Driver"},{"t":"ToeJam & Earl III: Mission to Earth","p":["Xbox"],"d":"ToeJam & Earl Productions, Visual Concepts Entertainment","u":"Sega","g":"Action-adventure, platform","r":"October 22, 2002","l":"https://en.wikipedia.org/wiki/ToeJam_&_Earl_III:_Mission_to_Earth","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7u7r.jpg","s":"The alien duo is back in an all-new adventure. In ToeJam & Earl III: Mission to Earth, ToeJam, Big Earl, and their new friend, Latisha, embark on a mission to retrieve the 12 sacred Albums of Funk, stolen by the inhabitantats of Earth. Across expansive environments, you must guide this group toward a showdown with the evil Anti-Funk. You'll collect a wide variety of power-ups, take on dangerous side quests, and double-team the clueless Earthlings in style."},{"t":"Tokimeki Memorial Girl's Side","p":["PlayStation 2"],"d":"Konami","u":"Konami","g":"Dating sim, otome game","r":"June 20, 2002","l":"https://en.wikipedia.org/wiki/Tokimeki_Memorial_Girl's_Side","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2uxr.jpg","s":"There is a fairy-tale story of a traveling prince who falls in love with a princess but are torn apart. The story is told by a young boy to the main character as a young girl in a church on the grounds of Habataki High School. The boy promises to one day return to that same place to declare his love. The protagonist returns to Habataki High School, after living away for a time due to her parents' work. While leading a normal high school life including academics, club activities and part-time work, it is also possible to become friendly with boys who can make a declaration of love on graduation day."},{"t":"Tokyo Mew Mew – Enter the New Mew Mew! – Serve Everyone Together","p":[],"l":"https://en.wikipedia.org/wiki/Tokyo_Mew_Mew_%E2%80%93_Enter_the_New_Mew_Mew!_%E2%80%93_Serve_Everyone_Together"},{"t":"Tom and Jerry in War of the Whiskers","p":["PlayStation 2"],"d":"VIS Entertainment","u":"NewKidCo, Ubi Soft","g":"Fighting","r":"October 22, 2002","l":"https://en.wikipedia.org/wiki/Tom_and_Jerry_in_War_of_the_Whiskers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5y3o.jpg","s":"Are you ready to kick some butt with Tom and Jerry and friends? With your choice over 75 weapons, you can duke it out in unique levels such as Frankenmouse, a twisted laboratory, or Towering Infurno, an unstable construction site! Be Prepared for the ultimate game of \"Cat and Mouse\"!"},{"t":"Tom Clancy's Ghost Recon","p":["PlayStation 2"],"r":"December 1","l":"https://en.wikipedia.org/wiki/Tom_Clancy%27s_Ghost_Recon"},{"t":"Tom Clancy's Ghost Recon: Desert Siege","p":["Windows"],"d":"Red Storm Entertainment","u":"Ubi Soft","g":"Tactical shooter","r":"March 26, 2002","l":"https://en.wikipedia.org/wiki/Tom_Clancy's_Ghost_Recon:_Desert_Siege"},{"t":"Tom Clancy's Ghost Recon: Island Thunder","p":["Windows"],"d":"Red Storm Entertainment","u":"Ubi Soft","g":"Tactical shooter","r":"September 24, 2002","l":"https://en.wikipedia.org/wiki/Tom_Clancy's_Ghost_Recon:_Island_Thunder","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8fd8.jpg","s":"Ghost Recon takes the next step in battlefield realism with Tom Clancy's Ghost Recon: Island Thunder."},{"t":"Tom Clancy's Rainbow Six: Lone Wolf","p":["PlayStation"],"d":"Rebellion Developments, Red Storm Entertainment","u":"Ubi Soft","g":"Tactical shooter","r":"July 4, 2002","l":"https://en.wikipedia.org/wiki/Tom_Clancy's_Rainbow_Six:_Lone_Wolf","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co49oe.jpg","s":"Playing as Rainbow Six team member Ding Chavez, players travel to Norway to eliminate a terrorist group planning to destabilize Eastern Europe with illegally smuggled US weapons. In keeping with the \"Lone Wolf\" mode of Rainbow Six assignments, missions are conducted without the help or hindrance of teammates. Planning phases include briefing, intelligence, kit select, and map screens, while actual gameplay takes place from a first-person perspective.\n\nWeapons can be set to fully automatic (continuous), burst (three shots), or semi-automatic (one shot). Crosshair and auto-locking features provide concise control when aiming, though grenades can be used in situations requiring less precise targeting. The mission objectives, a health meter, mini-map, the currently selected weapon, and ammo status are displayed on-screen at all times. Other features in Tom Clancy's Rainbow Six: Lone Wolf include a choice of insertion points for each mission (with different advantages), night vision goggles, and an option to save after successfully completing each mission."},{"t":"Tom Clancy's Splinter Cell","p":["Xbox"],"u":"Ubisoft","r":"November 17, 2002","l":"https://en.wikipedia.org/wiki/Tom_Clancy%27s_Splinter_Cell_(video_game)"},{"t":"Tomato Adventure","p":["Game Boy Advance"],"r":"January 25","l":"https://en.wikipedia.org/wiki/Tomato_Adventure"},{"t":"Tomb Raider: The Prophecy","p":["Game Boy Advance"],"r":"November 12"},{"t":"Tony Hawk's Pro Skater 3","p":["Xbox","Windows","Game Boy Advance","Nintendo 64"],"u":"Activision","r":"March 4, 2002","l":"https://en.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater_3"},{"t":"Tony Hawk's Pro Skater 4","p":["PlayStation 2","GameCube","Xbox","Game Boy Advance"],"u":"Activision","r":"October 23, 2002","l":"https://en.wikipedia.org/wiki/Tony_Hawk%27s_Pro_Skater_4"},{"t":"Top Angler: Real Bass Fishing","p":["PlayStation 2"],"d":"SIMS","u":"SIMS, Xicat Interactive","g":"Fishing","r":"March 7, 2002","l":"https://en.wikipedia.org/wiki/Top_Angler:_Real_Bass_Fishing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p3g.jpg","s":"The game is a real-time bass fishing simulator. The season and time of each stage are dictated by the internal clock of the player's console."},{"t":"Topolon","p":["Mobile phone"],"d":"G-Mode","u":"G-Mode","g":"Puzzle","r":"May 15, 2002","l":"https://en.wikipedia.org/wiki/Topolon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7vbu.jpg","s":"A futuristic action puzzle game that challenges the nano world! It is an action puzzle game that exterminates the virus that erodes the nano circuit \"TOPOLON\". If you defeat all the viruses on the screen, the stage will be cleared. The game can be enjoyed in 3 different game modes and 3 levels of difficulty, and the stage can be played unlimitedly with a random generation function."},{"t":"Torneko's Great Adventure 3","p":["PlayStation 2"],"d":"Chunsoft, Matrix Software","u":"Enix","g":"Role-playing, roguelike","r":"October 31, 2002","l":"https://en.wikipedia.org/wiki/Torneko's_Great_Adventure_3"},{"t":"Total Immersion Racing","p":["Windows","PlayStation 2","Xbox"],"d":"Razorworks","u":"Empire Interactive, Feral Interactive","g":"Racing","r":"November 1, 2002","l":"https://en.wikipedia.org/wiki/Total_Immersion_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6k4e.jpg","s":"Total Immersion Racing is a bare-bones rendition of Gran Turismo 3 or Sega GT 2002, albeit without the preponderance of cars and special effects. What's left over is a driving simulation that offers the rich gameplay of these heavy hitters, as well as a graphical show that's nearly on par with them, but none of the frills or splash that would attract casual players in search of a vicarious speed rush. It's a game for people who want to discover what the weekly toil of GT-class competition is really like, who understand that actual racing often entails driving around the same course lap after lap without much fear of hazards or obstacles, and who don't mind that the ultimate reward is the ability to drive a handful of different cars for various teams on tracks located throughout the world."},{"t":"Totaled!","p":["Xbox","PlayStation 2"],"d":"Rage Software","u":"Rage Games, Majesco","g":"Vehicular combat","r":"June 7, 2002","l":"https://en.wikipedia.org/wiki/Totaled!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6pxj.jpg","s":"Totaled! takes you for a ride in a destructive racing experience. In one of 12 cars, including hot rods, muscle, and performance cars, you must inflict as much damage on other cars as possible. Both the outer shell of each car (windows, hood, fenders, doors) and the chassis underneath can sustain damage that affects the car's performance. You can compete in 18 customizable game types and challenges, including Free for All, Stuntman, Multi-Tag, and Bus Jumping."},{"t":"Toxic Grind","p":["Xbox"],"r":"October 27","l":"https://en.wikipedia.org/wiki/Toxic_Grind"},{"t":"Trailer Park Tycoon","p":["Windows"],"d":"Jaleco Entertainment","u":"Jaleco Entertainment","g":"Business simulation game","r":"November 24, 2002","l":"https://en.wikipedia.org/wiki/Trailer_Park_Tycoon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/koo2snxmleyo2qpdlzae.jpg","s":"Trailer Park Tycoon puts the player in the shoes of a budding trailer park owner.\n\nThe player is tasked with building various trailers and amenities to attract people to their park. They will start with five to eight basic trailers, each upgradable three times. Specialized trailers become available, catering to specific people. A trailer in the theme of a car, for example, will attract garage workers, while a biker themed trailer will attract bikers. The game is now out of print since its developers have gone out of business."},{"t":"Transworld Snowboarding","p":["Xbox"],"d":"Housemarque","u":"Infogrames","g":"Snowboarding","r":"October 15, 2002","l":"https://en.wikipedia.org/wiki/Transworld_Snowboarding_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3g91.jpg","s":"TransWorld Snowboarding offers huge, vibrant, real-world snowboarding levels with natural snow kickers and ramps for launching; rails and downed trees to jib and grind on; and natural half-pipes and quarter-pipes for performing tons of tricks. But it's not all fun and games - treacherous terrain and steep cliffs lurk around every corner!"},{"t":"TransWorld Surf","p":["PlayStation 2"],"r":"April 30","l":"https://en.wikipedia.org/wiki/TransWorld_Surf"},{"t":"Treasure Planet: Battle at Procyon","p":["Windows"],"d":"Barking Dog Studios","u":"Disney Interactive","g":"Real-time strategy","r":"November 12, 2002","l":"https://en.wikipedia.org/wiki/Treasure_Planet:_Battle_at_Procyon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22n4.jpg","s":"Disney's Treasure Planet: Battle at Procyon is a 3D RTS game focusing on space combat. In the main campaign's story-driven missions, you begin play as Jim Hawkins, a cadet in the Royal Navy's fight against pirates and the deadly Procyon Fleet, with an eye toward eventual promotion to fleet commander. Skirmish and multiplayer modes allow the choice of playing as all three factions.\n\nSuccessfully completed missions result in ship and fleet enhancements, more experienced crews, and upgraded weapons. Royal Navy Fleet weapons are only slightly inferior to the reworked weapons of the Procyon Fleet but are sturdier and less vulnerable. Ships for the Royal Navy range from torpedo boats and war sloops to escorts, frigates, and the impressive StarHammer, while pirates man sloops, gunboats, schooners, assault cutters, and more, including several unique designs like the carrack and barque. The Procyon Fleet is built for speed and maneuverability, geared for fast hit-and-run attacks, and as the game progresses, news of a mysterious Ironclad Fleet surfaces as well.\n\nShip designs in Battle at Procyon are fashioned after the seafaring ships from the golden age of sail, with solar winds filling the sails and rigging. Arsenals reflect futuristic models of light, medium, and heavy weapons such as laserball and plasma cannons, beam weapons, Gatling guns, harpoons, fire and net launchers, gravity waves, torpedoes, mortars, and more. Other features include multiple waypoint settings, star maps, panic fire, secondary ship control, docking, repairing, towing, grappling, and boarding actions."},{"t":"Tres Lunas","p":[],"l":"https://en.wikipedia.org/wiki/Tres_Lunas_(video_game)"},{"t":"Tribes: Aerial Assault","p":["PlayStation 2"],"r":"September 23"},{"t":"Triple Play 2002","p":["PlayStation 2"],"r":"March 11","l":"https://en.wikipedia.org/wiki/Triple_Play_2002"},{"t":"Tsunami 2265","p":["Windows"],"d":"Prograph Research","u":"Got Game Entertainment","g":"Action","l":"https://en.wikipedia.org/wiki/Tsunami_2265","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mbo.jpg","s":"A game inspired by the anime genre mecha."},{"t":"Turbo Turtle Adventure","p":["Game Boy Advance"],"r":"September 14","l":"https://en.wikipedia.org/wiki/Legendo#Titles"},{"t":"Turok: Evolution","p":["PlayStation 2"],"r":"August 31"},{"t":"Twisted Metal: Black Online","p":["PlayStation 2"],"r":"August 27"},{"t":"Ty the Tasmanian Tiger","p":["GameCube","PlayStation 2","Xbox"],"r":"September 10","l":"https://en.wikipedia.org/wiki/Ty_the_Tasmanian_Tiger"},{"t":"U.S. Special Forces: Team Factor","p":["Windows"],"d":"7FX","u":"Xicat Interactive","g":"First-person shooter","r":"May 11, 2002","l":"https://en.wikipedia.org/wiki/U.S._Special_Forces:_Team_Factor"},{"t":"UFC: Tapout","p":["Xbox"],"r":"February 17"},{"t":"UFC: Throwdown","p":["GameCube"],"r":"July 29"},{"t":"Ultimate Fighting Championship: Throwdown","p":["PlayStation 2"],"r":"June 3"},{"t":"Ultimate Muscle: Legends vs. New Generation","p":["GameCube"],"d":"AKI Corporation","u":"Bandai","g":"Fighting","r":"November 22, 2002","l":"https://en.wikipedia.org/wiki/Ultimate_Muscle:_Legends_vs._New_Generation","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ufd.jpg","s":"Many years ago, King Muscle and the legendary Muscle League saved the people of Earth by battling against an evil horde of villains who were attempting to conquer the planet. After 28 years, the evil villains have returned, but this time the \"Legends\" can't fight them alone. They need help from a whole new group of younger super-heroes - the New Generation.\n\nNow, the wise and experienced trainer of both generations, Meat, has decided to pit the two generations against each other to decide once and for all which generation is the strongest of all time."},{"t":"Ultraman Fighting Evolution 2","p":["PlayStation 2"],"g":"Fighting","l":"https://en.wikipedia.org/wiki/Ultraman_Fighting_Evolution_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8yqn.jpg","s":"Ultraman Fighting Evolution 2 (ウルトラマン Fightingファイティング Evolutionエボリューション 2ツー Urutoraman Faitingu Eboryūshon Tsū) is a fighting game. It was released and published by Banpresto. It was the sequel of the original Ultraman Fighting Evolution series."},{"t":"Uncommon Valor: Campaign for the South Pacific","p":["Windows"],"d":"2 by 3 Games","u":"Matrix Games","g":"Computer wargame","r":"May 15, 2002","l":"https://en.wikipedia.org/wiki/Uncommon_Valor:_Campaign_for_the_South_Pacific"},{"t":"Unreal Championship","p":["Xbox"],"d":"Epic Games, Digital Extremes","u":"Infogrames","g":"First-person shooter","r":"November 12, 2002","l":"https://en.wikipedia.org/wiki/Unreal_Championship"},{"t":"Unreal Tournament 2003","p":["Windows"],"r":"September 30","l":"https://en.wikipedia.org/wiki/Unreal_Tournament_2003"},{"t":"Urban Yeti!","p":["Game Boy Advance"],"d":"Cave + Barn Studios","u":"Telegames","g":"Action","r":"August 16, 2002","l":"https://en.wikipedia.org/wiki/Urban_Yeti!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6z3a.jpg","s":"Urban Yeti is is a smooth scrolling 2 1/2-D platform adventure, and might very well be the strangest game you've ever played. You can smash your way through 4 twisting city stages, or attempt to avoid detection all together. Either way the Human AI will adapt as you progress - the more contact you have, the more aggressive they'll become. There are even some unique minigames to add to the excitement - Yeti Frisbee, managing the local \"Yeti Kingdom Of Eats\" restaurant, and catching poultry to offer to your prospective mate. You can even float down a lazy sewer river o' fun on a giant tube! Achieve the ultimate goal and show the world just what kind of Bigfoot you really are."},{"t":"Utawarerumono","p":["Windows"],"g":"Role-playing (RPG), Tactical, Visual Novel","l":"https://en.wikipedia.org/wiki/Utawarerumono","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4hgg.jpg","s":"Hakuoro, a man who wakes up in a tiny backwoods village near the mountains with heavy injuries, no memory, and a mask he cannot remove. After being nursed back to health by Eruruw, the girl who found him lying at the point of death in the forest, he starts to view the village as his new home. But when an oppressive ruler threatens the peaceful life of Hakuoro and his newfound friends and family, they find themselves hurtled towards war, chaos, and a destiny far greater than any of them imagined."},{"t":"V-Rally 3","p":["PlayStation 2"],"r":"October 22","l":"https://en.wikipedia.org/wiki/V-Rally_3"},{"t":"Vendetta Online","p":["Windows","macOS","Linux"],"r":"April 20","l":"https://en.wikipedia.org/wiki/Vendetta_Online"},{"t":"Vet Emergency 2","p":["Windows","macOS"],"d":"Legacy Interactive","u":"Legacy Interactive","g":"Simulation","r":"November 26, 2002","l":"https://en.wikipedia.org/wiki/Vet_Emergency_2"},{"t":"Virtua Fighter 4","p":["PlayStation 2"],"u":"Sega","r":"January 31, 2002","l":"https://en.wikipedia.org/wiki/Virtua_Fighter_4"},{"t":"Virtua Tennis","p":["Game Boy Advance"],"r":"October 8","l":"https://en.wikipedia.org/wiki/Virtua_Tennis"},{"t":"Virtua Tennis 2","p":["PlayStation 2"],"r":"July 30","l":"https://en.wikipedia.org/wiki/Virtua_Tennis_2"},{"t":"War and Peace: 1796–1815","p":["Windows"],"d":"Microïds","u":"Microïds","g":"Strategy, Simulation","r":"August 29, 2002","l":"https://en.wikipedia.org/wiki/War_and_Peace:_1796%E2%80%931815"},{"t":"Warcraft III: Reign of Chaos","p":["Windows"],"u":"Blizzard Entertainment","r":"July 3, 2002"},{"t":"Warlords Battlecry II","p":["Windows"],"d":"Strategic Studies Group","u":"Ubi Soft","g":"RTS, role-playing video game","r":"March 12, 2002","l":"https://en.wikipedia.org/wiki/Warlords_Battlecry_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co224z.jpg","s":"The game is set within the world of Etheria. In the campaign the player must take control of one of the twelve races and capture all sixty-seven regions of the land in a non-linear manner. The player does this whilst assuming the role of a \"Hero\" which he or she has created. There are twelve different playable races, each with their own type of Hero, buildings and resource dependencies."},{"t":"Warrior Kings","p":["Windows","macOS"],"d":"Black Cactus, Zonic","u":"Microïds, Feral Interactive","g":"Real-time strategy","l":"https://en.wikipedia.org/wiki/Warrior_Kings","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1yo2.jpg","s":"You are tasked with restoring the power of a kingdom to its former glory using innate cunning, military might and a fearsome will to win. Warrior Kings is an epic real-time strategy game that smashes the mould. Using true 3D it propels you into a living, breathing and fascinating medieval fantasy world. Now it's all in your hands."},{"t":"Way of the Samurai","p":["PlayStation 2"],"r":"May 31","l":"https://en.wikipedia.org/wiki/Way_of_the_Samurai"},{"t":"Whacked!","p":["Xbox"],"d":"Presto Studios","u":"Microsoft Game Studios","g":"Party","r":"October 15, 2002","l":"https://en.wikipedia.org/wiki/Whacked!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9u5i.jpg","s":"In Whacked! you are one of seven demented contestants competing on a dangerous game show. Pitted against each other in free-for-all combat, contestants must use power-ups and weapons, such as giant staplers and rubber ducky grenades, to flatten their opponents. The game's various modes have you fighting to collect resources, fending off a horde of man-eating chickens, or exchanging blows in fierce deathmatches. There are more than a dozen levels--including an arctic pipeline, a Christmas tree, and a kitchen sink--for you to conquer."},{"t":"Whirl Tour","p":["GameCube"],"r":"November 12","l":"https://en.wikipedia.org/wiki/Whirl_Tour"},{"t":"Whiteout","p":["PlayStation 2","Windows","Xbox"],"d":"Vicarious Visions","u":"Konami","g":"Racing","r":"November 26, 2002","l":"https://en.wikipedia.org/wiki/Whiteout_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co978l.jpg","s":"Real winter racing at blinding speeds! Experience the thrills and chills of snowmobile racing action with Whiteout, the fastest racing game on one tread."},{"t":"Widelands","p":[],"l":"https://en.wikipedia.org/wiki/Widelands"},{"t":"Wild Arms 3","p":["PlayStation 2"],"r":"October 15","l":"https://en.wikipedia.org/wiki/Wild_Arms_3"},{"t":"Wind: A Breath of Heart","p":[],"l":"https://en.wikipedia.org/wiki/Wind:_A_Breath_of_Heart"},{"t":"Wipeout Fusion","p":["PlayStation 2"],"r":"June 18","l":"https://en.wikipedia.org/wiki/Wipeout_Fusion"},{"t":"Woody Woodpecker: Escape from Buzz Buzzard Park","p":["PlayStation 2"],"r":"February 19"},{"t":"World Club Champion Football","p":["Arcade"],"d":"Hitmaker, Sega","u":"Sega","g":"Sports, DCCG","l":"https://en.wikipedia.org/wiki/World_Club_Champion_Football"},{"t":"World of Outlaws: Sprint Cars 2002","p":["PlayStation 2"],"d":"Ratbag Games","u":"Infogrames, Ignition Entertainment","g":"Racing","r":"March 27, 2002","l":"https://en.wikipedia.org/wiki/World_of_Outlaws:_Sprint_Cars_2002","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa2xa.jpg","s":"Feel the power of World of Outlaws. Sprint Cars 2002. Hurtle around the oval track at speeds in excess of 170 mph as you race your way to the Sprint Car Hall of Fame. With jaw dropping graphics, realistic physics, and boundless white knuckle action, World of Outlaws Sprint Cars 2002 will take your breath away!"},{"t":"World Rally Championship","p":["PlayStation 2"],"r":"March 21","l":"https://en.wikipedia.org/wiki/World_Rally_Championship_(2001_video_game)"},{"t":"Worms Blast","p":["Windows","PlayStation 2","GameCube","Game Boy Advance"],"d":"Team17","u":"Ubi Soft, Feral Interactive","g":"Puzzle","r":"March 22, 2002","l":"https://en.wikipedia.org/wiki/Worms_Blast","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xmg.jpg","s":"Fall in line for fast, furious fire fights with Worms Blast. Your mission: launch your worm marine into hostile waters and blast your way to survival through intense puzzle action! Take the big chunk of puzzle-styled gameplay and slice into 60 fun-sized missions."},{"t":"WRC II Extreme","p":["PlayStation 2"],"d":"Evolution Studios","u":"Sony Computer Entertainment","g":"Racing","r":"November 27, 2002","l":"https://en.wikipedia.org/wiki/WRC_II_Extreme","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48x0.jpg","s":"WRC II Extreme is a 2002 off-road video game released for the PlayStation 2. The game was developed by Evolution Studios and published by Sony Computer Entertainment Europe."},{"t":"WRC: FIA World Rally Championship Arcade","p":["PlayStation"],"d":"Unique Development Studios","u":"Sony Computer Entertainment","g":"Racing","r":"August 11, 2002","l":"https://en.wikipedia.org/wiki/WRC:_FIA_World_Rally_Championship_Arcade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4a79.jpg","s":"WRC: FIA World Rally Championship Arcade is Driving game, developed by USD and published by SCEE."},{"t":"Wreckless: The Yakuza Missions","p":["Xbox","GameCube","PlayStation 2"],"r":"February 4"},{"t":"WTA Tour Tennis","p":["Game Boy Advance"],"r":"May 31","l":"https://en.wikipedia.org/wiki/WTA_Tour_Tennis"},{"t":"WWE Road to WrestleMania X8","p":["Game Boy Advance"],"d":"Natsume Co., Ltd.","u":"THQ","g":"Sports","r":"October 22, 2002","l":"https://en.wikipedia.org/wiki/WWE_Road_to_WrestleMania_X8","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co48vz.jpg","s":"The road to WrestleMania X8 is a yearlong struggle, which has seen legends reborn, dreams shattered and lives changed forever. It isn?t glamorous, it isn?t easy, and it sure as hell isn?t destiny. It is about the hard-fought brawls, the never-ending passion and the battle hardened emotions that it takes to trudge down the path to the greatest spectacle in sports entertainment. The showcase of the immortals begins with the clash of the titans in World Wrestling Road to WrestleMania X8.\n\nGrow your Superstar through the ranks as his abilities change according to your fighting style. Create your own pay-per-view and see how the crowds react to the matches. Win bouts and see your popularity skyrocket when the Superstar's hats and shirts fly off the shelves in the shopzone. Begin the quest for the most illustrious title in sportsentertainment, the World Wrestling Championship. The Road to WrestleMania begins here!"},{"t":"WWE SmackDown! Shut Your Mouth","p":["PlayStation 2"],"r":"October 31","l":"https://en.wikipedia.org/wiki/WWE_SmackDown!_Shut_Your_Mouth"},{"t":"WWE WrestleMania X8 (video game)","p":["GameCube"],"r":"June 10","l":"https://en.wikipedia.org/wiki/WWE_WrestleMania_X8_(video_game)"},{"t":"WWF Raw","p":["Xbox","Windows"],"d":"Anchor Inc.","u":"THQ, Kadokawa Shoten","g":"Sports","r":"February 12, 2002","l":"https://en.wikipedia.org/wiki/WWF_Raw_(2002_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob22m.jpg","s":"WWF Raw (also known as WWE Raw or WWF Raw is War, depending on version) is a video game released on the Microsoft Xbox and Microsoft Windows by THQ in 2002. It is based on the television series of the same name. It was the first WWE game released on the Xbox and also the last WWE game released on PC until the release of WWE 2K15 thirteen years later in 2015. A sequel was released in 2003. It is also the last game released under the WWF name, as the World Wrestling Federation changed its name to \"World Wrestling Entertainment\" in May of that year."},{"t":"X-Bladez: Inline Skater","p":["PlayStation","Game Boy Advance"],"d":"Vision Scape Interactive, The Code Monkeys","u":"Crave Entertainment, Ubi Soft","g":"Sports","r":"March 22, 2002","l":"https://en.wikipedia.org/wiki/X-Bladez:_Inline_Skater","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co53s4.jpg","s":"In-line skating comes to the flourishing category of \"extreme sports\" video gaming in X-Bladez. Players choose one of six characters to flip, spin, and grind through slalom and circuit courses in an assortment of 3D environments. Race for speed or hot dog for style. Time-of-day and weather effects add variety to the look and mood of the virtual skate parks.\n\nUnlock new environments as you progress and upgrade your skates with the money you earn."},{"t":"X-Men: Next Dimension","p":["PlayStation 2"],"r":"October 15"},{"t":"X-Wars","p":[],"d":"Sebastian Lagemann, Mediatainment GmbH, Sebastian Lagemann, Nils Mitoussis","u":"Mediatainment GmbH, Gameforge AG, Gamigo AG","g":"MMOG, RTS, CMS","l":"https://en.wikipedia.org/wiki/X-Wars"},{"t":"X: Card of Fate","p":["WonderSwan Color"],"g":"Strategy","l":"https://en.wikipedia.org/wiki/X:_Card_of_Fate","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/mhbs0gtgfoxfo39mzsxc.jpg","s":"X: Card of Fate is a Strategy game, developed by Access and published by Bandai, which was released in Japan in 2002."},{"t":"X: Unmei no Sentaku","p":["PlayStation"],"d":"Taito, Atelier Double","u":"Bandai","g":"Fighting","r":"August 22, 2002","l":"https://en.wikipedia.org/wiki/X:_Unmei_no_Sentaku","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uer.jpg","s":"X: Unmei no Tatakai is an 3D fighting game that features a story mode, set in the television series continuity, and a versus mode, which allows players to compete against each other using any of the Dragons of Heaven or Earth. The game was not released outside Japan and it has two different endings."},{"t":"Xenosaga Episode I","p":["PlayStation 2"],"d":"Monolith Soft","u":"Namco","g":"Role-playing","r":"February 28, 2002","l":"https://en.wikipedia.org/wiki/Xenosaga_Episode_I"},{"t":"XII Stag","p":["Arcade","PlayStation 2"],"d":"Triangle Service, Dreams","u":"Taito, 505 Game Street","g":"Shoot 'em up","l":"https://en.wikipedia.org/wiki/XII_Stag","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/offce3uijv2rdyvyspm4.jpg","s":"A space shooter with vertically scrolling stages. Based on the arcade version."},{"t":"XXX","p":["Game Boy Advance"],"d":"Digital Eclipse","u":"Activision","g":"Run and gun, vehicular combat","r":"August 6, 2002","l":"https://en.wikipedia.org/wiki/XXX_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4k9e.jpg","s":"You are underground thrill-seeker turned spy Xander Cage. Can you stop the evil Anarchy 99 organizaton before it unleashes an assault on Earth? Tackle a variety of pulse-pounding, action-packed levels. Face 11 menacing missions, featuring 3 motorcycle tracks. Master an array of high-tech secret agent weapons"},{"t":"Yami to Bōshi to Hon no Tabibito","p":[],"l":"https://en.wikipedia.org/wiki/Yami_to_B%C5%8Dshi_to_Hon_no_Tabibito"},{"t":"Yoshi's Island: Super Mario Advance 3","p":["Game Boy Advance"],"u":"Nintendo","r":"September 24, 2002","l":"https://en.wikipedia.org/wiki/Yoshi%27s_Island"},{"t":"Yu-Gi-Oh! The Sacred Cards","p":["Game Boy Advance"],"d":"Konami","u":"Konami","g":"Digital collectible card game","r":"July 4, 2002","l":"https://en.wikipedia.org/wiki/Yu-Gi-Oh!_The_Sacred_Cards","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ptk.jpg","s":"In Yu-Gi-Oh! The Sacred Cards, it's just as important to play your cards right as it is to get the right cards. This unique RPG gives you cards as weapons against the tough competition. You'll battle in a tournament hosted by Kaiba Corporation and win the powerful Egyptian God Cards. Based on events from the Yu-Gi-Oh! animated TV series, The Sacred Cards offers hundreds of cards, over 100 duelists and rivals, and unexpected twists and surprises."},{"t":"ZanZarah: The Hidden Portal","p":["Windows"],"d":"Funatics Development","u":"THQ, Xicat Interactive","g":"Action-adventure, role-playing","r":"April 26, 2002","l":"https://en.wikipedia.org/wiki/ZanZarah:_The_Hidden_Portal","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2kok.jpg","s":"The legends speak of a long forgotten prophecy... of a shining hero and of perilous adventures... of sinister powers, strange worlds and swarms of fairies ... but they said nothing of a girl with a big heart instead of a big sword!"},{"t":"Zapper: One Wicked Cricket","p":["Windows","PlayStation 2","Xbox","GameCube","Game Boy Advance"],"g":"Action, Adventure","r":"November 5","l":"https://store.steampowered.com/app/2766060","i":"images/steam-2766060.jpg","s":"In this action-adventure game, Zapper (a cricket) hops his way through six worlds in a quest to find his brother, held captive by the evil magpie queen. Dangerous traps and even more dangerous enemies await! It will take skill and timing to conquer all the worlds and survive the final showdown."},{"t":"Zero4 Champ","p":["PC Engine"],"d":"Media Rings","u":"Media Rings","g":"Racing video game","l":"https://en.wikipedia.org/wiki/Zero4_Champ"},{"t":"Zoids Vs.","p":[],"l":"https://en.wikipedia.org/wiki/Zoids_Vs."},{"t":"Zone of the Enders: The Fist of Mars","p":["Game Boy Advance"],"r":"February 12"},{"t":"Zoo Tycoon: Dinosaur Digs","p":["Windows"],"d":"Blue Fang Games","u":"Microsoft Game Studios","g":"Simulation","r":"May 17, 2002","l":"https://en.wikipedia.org/wiki/Zoo_Tycoon:_Dinosaur_Digs"},{"t":"Zoo Tycoon: Marine Mania","p":["Windows","macOS"],"d":"Blue Fang Games","u":"Microsoft Game Studios, Aspyr Media","g":"Simulation","r":"October 21, 2002","l":"https://en.wikipedia.org/wiki/Zoo_Tycoon:_Marine_Mania"},{"t":"ZooCube","p":["GameCube","Game Boy Advance"],"d":"PuzzleKings, Graphic State","u":"Acclaim Entertainment, Midas Interactive Entertainment","g":"Puzzle","r":"May 30, 2002","l":"https://en.wikipedia.org/wiki/ZooCube","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocvbv.jpg","s":"Created by PuzzleKings, ZooCube takes puzzlers to a whole new dimension - the third dimension. Around the world, animals have been transformed by shape-altering science experiments and need help in returning to their natural state. Players use their ZooCube to rescue and return the animals to the flying ark."}];
